window.DATA_READER_RUMEN = [{"num": 1, "title_en": "Greetings", "title_zh": "打招呼", "type": "dialogue", "category": "日常高频情境口语", "tip": "现代日常打招呼更常用 'How's it going?' 或 'How are you doing?'，回复往往是自然随和的 'Pretty good!' 或 'Not bad, you?'，无需拘泥于僵化的 'I'm fine, thank you.'", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Good morning, May. How are you?", "zh": "早啊，小梅。你好吗？"}, {"speaker": "B", "en": "Hi, Tom. I'm fine. And you?", "zh": "嗨，汤姆。我很好，你呢？"}, {"speaker": "A", "en": "Not bad. Thanks.", "zh": "还不错，谢了。"}, {"speaker": "B", "en": "Good. See you.", "zh": "很好，再见。"}, {"speaker": "A", "en": "Bye.", "zh": "再见。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, May. How's it going?", "zh": "嗨，小梅。近来如何？"}, {"speaker": "B", "en": "Great. And how are you doing?", "zh": "很好。那你呢？"}, {"speaker": "A", "en": "Not bad.", "zh": "还不错。"}, {"speaker": "B", "en": "OK. See you later.", "zh": "好吧，再见。"}, {"speaker": "A", "en": "Take care.", "zh": "保重。"}, {"speaker": "B", "en": "You too.", "zh": "你也是。"}]}], "reading": null, "vocab": [{"num": 1, "word": "good morning 早安 good", "phonetic": "[ɡʊd]", "pos": "形", "meaning": "好的；morning ['mɔrnɪŋ] 名 早晨"}, {"num": 2, "word": "May", "phonetic": "[me]", "pos": "名", "meaning": "梅（女性名）"}, {"num": 3, "word": "How are you?", "phonetic": "[haʊ]", "pos": "动", "meaning": "你好吗?"}, {"num": 4, "word": "Tom", "phonetic": "[tɑːm]", "pos": "名", "meaning": "汤姆（男性名）"}, {"num": 5, "word": "hi", "phonetic": "[haɪ]", "pos": "叹", "meaning": "嗨（打招呼用语）"}, {"num": 6, "word": "I'm fine.", "phonetic": "[aɪ]", "pos": "代", "meaning": "（是 &quot;I am fine&quot; 的缩写） 我很好。"}, {"num": 7, "word": "And you?", "phonetic": "[ænd]", "pos": "连", "meaning": "（此处是 &quot;And how are you?&quot; 的简化） 那你呢?"}, {"num": 8, "word": "Not bad.", "phonetic": "[nɑːt]", "pos": "副", "meaning": "还不错。"}, {"num": 9, "word": "thanks", "phonetic": "[θæŋks]", "pos": "名", "meaning": "谢谢"}, {"num": 10, "word": "See you.", "phonetic": "[siː]", "pos": "动", "meaning": "再见。"}, {"num": 11, "word": "bye", "phonetic": "[baɪ]", "pos": "叹", "meaning": "再见（是 goodbye [gʊd'baɪ] 的简化）"}, {"num": 1, "word": "How's it going?", "phonetic": "[ɪz]", "pos": "动", "meaning": "（是 &quot;How is it going?&quot; 的缩写） 近况如何?"}, {"num": 2, "word": "great", "phonetic": "[ɡreɪt]", "pos": "形", "meaning": "很棒的"}, {"num": 3, "word": "And how are you doing?", "phonetic": "[ˈduːɪŋ]", "pos": "", "meaning": "那么你好吗?"}, {"num": 4, "word": "OK", "phonetic": "[ˈoˈke]", "pos": "形", "meaning": "不错的"}, {"num": 5, "word": "See you later. 再见。（= See you.） later", "phonetic": "[ˈletɚ]", "pos": "副", "meaning": "稍后，以后"}, {"num": 6, "word": "Take care.", "phonetic": "[tek]", "pos": "动", "meaning": "保重。"}, {"num": 7, "word": "You too.", "phonetic": "[tuː]", "pos": "副", "meaning": "你也一样。"}], "grammar": [{"num": 1, "title": "good morning 早安", "desc": ["本用语是表示礼貌的招呼语，用于中午12点以前。其他相同的招呼语如下："], "formulas": [], "examples": []}, {"num": 2, "title": "与人道别时表示“再见”的常用语如下：", "desc": [], "formulas": [], "examples": []}, {"num": 3, "title": "有些美国年轻人喜欢使用下列俏皮的对话：", "desc": ["此处 B 故意说 &quot;Alligator.&quot; 取代 &quot;See you later.&quot;，乃因 Alligator ['æləˌgetɚ] 中的 gator 与 &quot;See you later.&quot; 中的 later 押韵。", "Alligator 原指“鳄鱼”，此处全无任何意义，纯属俏皮话，可视作 &quot;See you later.&quot; 之意义。"], "formulas": [], "examples": []}, {"num": 4, "title": "注意下列问候语的区别：", "desc": ["你好吗？（多用于熟朋友之间）", "还好吧/近况如何？", "近况如何？（多为年轻人所用）"], "formulas": [], "examples": []}, {"num": 5, "title": "注意下列的答句：", "desc": ["问句：How are you? 你好吗？", "= How are you doing?", "= How are you getting along?", "答句：I'm fine, thank you. 我很好，谢谢你。", "Great, thanks. 很好，谢谢你。", "Fine, thanks. 不错，谢谢你。", "Not bad, thanks. 还不错，谢谢你。", "So-so, thank you. 马马虎虎/还过得去，谢谢你。", "上述问候句的主语并非 you，故答句不可说 &quot;I'm fine, thank you.&quot;，兹分述如下：", "答句：Not bad, thank you. 还不错，谢谢你。", "So-so, thank you. 马马虎虎，谢谢你。", "Great, thank you. 很好，谢谢你。", "Fine, thank you. 不错，谢谢你。", "答句：Nothing much. 没什么。", "Same as usual. 老样子。", "简化而来。", "same [sem] 形 相同的 as [æz] 连 和 usual ['juʒuəl] 形 平常的"], "formulas": [], "examples": []}, {"num": 6, "title": "表示“感谢”的用语：", "desc": [], "formulas": [], "examples": []}, {"num": 1, "title": "OK. 好的。本用语相当于 &quot;All right.&quot; 之意。", "desc": [], "formulas": [], "examples": []}, {"num": 2, "title": "Take care. 保重。", "desc": ["本句系由 &quot;I hope you will take care of yourself.&quot;（我希望你会照顾自己。）", "简化而成。"], "formulas": [], "examples": []}, {"num": 3, "title": "You too. 你也一样。", "desc": ["这是一种简答句，系由下列句子简化而成：", "这种简答句只用于肯定句中，且通常只有下列两种：", "You too. 你/你们也一样。", "Me too. 我也一样。", "= I hope you can pass the exam, too.", "（甲：我希望你考试能及格。）", "（乙：你也一样。）", "= I hope I can see you tomorrow, too.", "（甲：我希望明天能见到你。）", "（乙：我也一样。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Good [morning / afternoon / evening], May.", "zh": "早安/午安/晚安，小梅。", "pairs": [{"en": "Good [morning / afternoon / evening], May.", "zh": "早安/午安/晚安，小梅。"}]}, {"num": 2, "en": "How are [you? / you doing?]", "zh": "你好吗？", "pairs": [{"en": "How are [you? / you doing?]", "zh": "你好吗？"}]}, {"num": 3, "en": "I'm [fine. / OK.]", "zh": "我很好/还好。", "pairs": [{"en": "I'm [fine. / OK.]", "zh": "我很好/还好。"}]}, {"num": 4, "en": "[And / What about / How about] you?", "zh": "那你呢？", "pairs": [{"en": "[And / What about / How about] you?", "zh": "那你呢？"}]}, {"num": 5, "en": "[Not bad. / Great. / Fine.] Thanks.", "zh": "还不错/很好/还好，谢了。", "pairs": [{"en": "[Not bad. / Great. / Fine.] Thanks.", "zh": "还不错/很好/还好，谢了。"}]}, {"num": 6, "en": "[Thanks. / Thank you. / Thank you very much. / Thanks a lot.]", "zh": "谢谢/谢谢你/非常谢谢你/多谢。", "pairs": [{"en": "[Thanks. / Thank you. / Thank you very much. / Thanks a lot.]", "zh": "谢谢/谢谢你/非常谢谢你/多谢。"}]}, {"num": 7, "en": "Good. [See you. / See you later. / Bye. / Goodbye.]", "zh": "很好，再见。", "pairs": [{"en": "Good. [See you. / See you later. / Bye. / Goodbye.]", "zh": "很好，再见。"}]}, {"num": 8, "en": "[How's it going? / What's up? / What's happening?]", "zh": "近来如何？", "pairs": [{"en": "[How's it going? / What's up? / What's happening?]", "zh": "近来如何？"}]}], "exercises": []}, {"num": 2, "title_en": "Courtesy", "title_zh": "礼貌", "type": "dialogue", "category": "日常高频情境口语", "tip": "在现代美式口语中，'Excuse me' 用途极广：借过、引起注意或听不清时均可用；而听到对方道歉时，常说 'No worries!' 或 'You're good!' 代替正式的 'That's all right.'", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. Are you Ann?", "zh": "对不起，请问你是安吗？"}, {"speaker": "B", "en": "No, I'm not.", "zh": "不，我不是。"}, {"speaker": "A", "en": "I'm sorry. Who's Ann?", "zh": "很抱歉。请问安是哪位？"}, {"speaker": "B", "en": "She is.", "zh": "她是。"}, {"speaker": "A", "en": "Thank you.", "zh": "谢谢。"}, {"speaker": "B", "en": "You're welcome.", "zh": "不客气。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, I'm Tom.", "zh": "嗨，我是汤姆。"}, {"speaker": "B", "en": "I beg your pardon?", "zh": "对不起，请再说一遍好吗？"}, {"speaker": "A", "en": "I'm Tom.", "zh": "我是汤姆。"}, {"speaker": "B", "en": "Oh! Hi, Tom. I'm May.", "zh": "哦！嗨，汤姆。我是小梅。"}, {"speaker": "A", "en": "Nice to meet you, May.", "zh": "很高兴认识你，小梅。"}, {"speaker": "B", "en": "Pleased to meet you.", "zh": "幸会，幸会。"}]}], "reading": null, "vocab": [{"num": 1, "word": "courtesy", "phonetic": "[ˈkɝtəsɪ]", "pos": "名", "meaning": "礼貌"}, {"num": 2, "word": "Excuse me.", "phonetic": "[ɪkˈskjuz]", "pos": "动", "meaning": "对不起/打扰一下。"}, {"num": 3, "word": "Ann", "phonetic": "[æn]", "pos": "名", "meaning": "安（女性名）"}, {"num": 4, "word": "no", "phonetic": "[no]", "pos": "副", "meaning": "不是"}, {"num": 5, "word": "I'm sorry.", "phonetic": "[ˈsɑrɪ]", "pos": "形", "meaning": "（是 &quot;I am sorry.&quot; 的缩写） 对不起/抱歉。"}, {"num": 6, "word": "who", "phonetic": "[hu]", "pos": "疑", "meaning": "谁（本文 Who's 是 &quot;who is&quot; 的缩写）"}, {"num": 7, "word": "thank you 谢谢你；thank", "phonetic": "[θæŋk]", "pos": "动", "meaning": "感谢，向……致谢"}, {"num": 8, "word": "You're welcome.", "phonetic": "[ˈwɛlkəm]", "pos": "形", "meaning": "不客气/不用谢。"}, {"num": 1, "word": "I beg your pardon?", "phonetic": "[bɛɡ]", "pos": "动", "meaning": "对不起,请再说一遍好吗?"}, {"num": 2, "word": "oh", "phonetic": "[o]", "pos": "叹", "meaning": "哦，啊"}, {"num": 3, "word": "Nice to meet you.", "phonetic": "[naɪs]", "pos": "形", "meaning": "很高兴认识你/幸会。"}, {"num": 4, "word": "Pleased to meet you.", "phonetic": "[plizd]", "pos": "形", "meaning": "很高兴认识你/幸会。"}], "grammar": [{"num": 1, "title": "Excuse me.", "desc": ["对不起/打扰一下。", "I'm sorry. 对不起/抱歉。", "以上两句均译成“对不起”，但用法有别：", "&quot;Excuse me.&quot; 用于唤起别人的注意；而 &quot;I'm sorry.&quot; 则多表示“抱歉”，尤其是在犯错或有不好的消息要告诉对方时使用。", "&quot;Excuse me&quot; 或 &quot;I'm sorry&quot; 之后除可置句点以外，亦可置逗点，再置连接词 but，以连接另一个句子。but 原意为“但是”，但此处不必译出。因此上列例句亦可写成："], "formulas": [], "examples": []}, {"num": 2, "title": "You're welcome. 别客气。", "desc": ["对方表示谢谢时，可用下列句子或用语回答，这些句子或用语均可译成“别客气”：", "其他常见表达还有："], "formulas": [], "examples": []}, {"num": 1, "title": "I beg your pardon？对不起，请再说一遍好吗？", "desc": ["本问句理应说成：", "但因为经常使用的关系，反而简化成如下用语：", "= Beg your pardon?", "= Pardon me?", "= Pardon?", "以上问句均译成“对不起，请再说一遍好吗？”，这是很客气的用语。"], "formulas": [], "examples": []}, {"num": 2, "title": "Nice to meet you. 很高兴认识你/幸会。", "desc": ["= Pleased to meet you.", "= Glad to meet you.", "以上三句均表示“幸会”，是两人初见面时的客气用语。", "这三句分别由下列完整的句子简化而成："], "formulas": [], "examples": []}, {"num": 3, "title": "英文中很多句子都是“代名词 + be 动词”开头的，如下列：", "desc": ["但在口语中，常为求说话的速度及口气的自然，经常将“代名词 + be 动词”简化，而形成下列的形态：", "“代名词 + be 动词” 缩写对照表：", "试将下列含“代名词 + be 动词”的句型简化：", "→ They're my good friends.", "→ He's my father.", "→ You're very nice.", "→ We're hungry now.", "→ It's a cute dog."], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "[You're welcome. / Don't mention it. / Not at all. / No problem.]", "zh": "不客气。", "pairs": [{"en": "[You're welcome. / Don't mention it. / Not at all. / No problem.]", "zh": "不客气。"}]}, {"num": 2, "en": "[I beg your pardon? / Beg your pardon? / Pardon me? / Pardon?]", "zh": "对不起，请再说一遍好吗？", "pairs": [{"en": "[I beg your pardon? / Beg your pardon? / Pardon me? / Pardon?]", "zh": "对不起，请再说一遍好吗？"}]}, {"num": 3, "en": "[Nice / Pleased] to meet you.", "zh": "很高兴认识你/幸会。", "pairs": [{"en": "[Nice / Pleased] to meet you.", "zh": "很高兴认识你/幸会。"}]}, {"num": 4, "en": "[I'm Tom. / She's May. / They're students.]", "zh": "我是汤姆。 / 她是小梅。 / 他们/她们是学生。", "pairs": [{"en": "[I'm Tom. / She's May. / They're students.]", "zh": "我是汤姆。 / 她是小梅。 / 他们/她们是学生。"}]}], "exercises": []}, {"num": 3, "title_en": "Name, Age and Nationality", "title_zh": "姓名、年龄和国籍", "type": "dialogue", "category": "日常高频情境口语", "tip": "介绍自己姓名时，口语中最自然的是直接说 'I'm Robert, but call me Bob.'。问对方年龄时在西方通常只对儿童使用，成人社交一般更倾向询问 'What do you do?'（你的职业是什么）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. What's your name?", "zh": "对不起。请问你叫什么名字？"}, {"speaker": "B", "en": "I'm May.", "zh": "我叫小梅。"}, {"speaker": "A", "en": "Hi, May. Where are you from?", "zh": "嗨，小梅。你是哪里人呢？"}, {"speaker": "B", "en": "I'm from Hong Kong. What about you?", "zh": "我是香港人。那你呢？"}, {"speaker": "A", "en": "I'm from Japan.", "zh": "我是日本人。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I have your name, please?", "zh": "请问尊姓大名？"}, {"speaker": "B", "en": "My name is May.", "zh": "我叫小梅。"}, {"speaker": "A", "en": "How old are you?", "zh": "你几岁了？"}, {"speaker": "B", "en": "I'm twenty-five.", "zh": "我25岁。"}, {"speaker": "A", "en": "Where are you from?", "zh": "你是哪里人？"}, {"speaker": "B", "en": "I'm from Hong Kong.", "zh": "我是香港人。"}]}], "reading": null, "vocab": [{"num": 1, "word": "name", "phonetic": "[neɪm]", "pos": "名", "meaning": "姓名，名字"}, {"num": 2, "word": "age", "phonetic": "[edʒ]", "pos": "名", "meaning": "年龄"}, {"num": 3, "word": "nationality", "phonetic": "[næʃəˈnælətɪ]", "pos": "名", "meaning": "国籍"}, {"num": 4, "word": "What's your name?", "phonetic": "[hwɑt]", "pos": "疑", "meaning": "你叫什么名字?"}, {"num": 5, "word": "Where are you from?", "phonetic": "[hwɛr]", "pos": "疑", "meaning": "你是哪里人?"}, {"num": 6, "word": "Hong Kong", "phonetic": "[ˈhɑŋˈkɑŋ]", "pos": "名", "meaning": "香港（地名）"}, {"num": 7, "word": "What about you? 那你呢？（= How about you?）；about", "phonetic": "[əˈbaʊt]", "pos": "介", "meaning": "关于"}, {"num": 8, "word": "Japan", "phonetic": "[dʒəˈpæn]", "pos": "名", "meaning": "日本（国名）"}, {"num": 1, "word": "May I have your name, please?", "phonetic": "[me]", "pos": "助", "meaning": "请问尊姓大名?"}, {"num": 2, "word": "How old are you?", "phonetic": "[old]", "pos": "形", "meaning": "你几岁了?"}, {"num": 3, "word": "twenty-five", "phonetic": "[ˈtwɛntiˈfaɪv]", "pos": "形", "meaning": "25的"}], "grammar": [{"num": 1, "title": "疑问句造句法：", "desc": ["本段会话中，&quot;what's your name? “以及&quot;Where are you from？“为含有疑问词what （什么） 及where （什么地方）", "的问句，称为疑问句或特殊问句。", "（何时）、how （如何） 等，在问句中，这些疑问词一定放在句首。", "':Who is Mary?", "（玛丽是谁？）", "中文的疑问句与陈述句结构完全相同，只是前者在句尾加上问号，而后者则置句点。", "“：疑问句：他是谁？", "陈述句：他是学生。", "疑问句：你籍贯哪儿？", "陈述句：我籍贯河南。", "疑问句:Who is he?", "陈述句：He is a student.", "疑问句：Where are you from?", "陈述句：I'm from Henan.", "他是谁？", "→He is who?", "他何时会来？", "他住在哪里？", "不可写成：", "does 要与第三人称单数的主语（如 he, she, it, Mary, Tom, a boy 等） 并用。原句 &quot;Where he lives?&quot; 中，he 是第三人称单数，故应使用 does，即成 &quot;Where does he live?&quot; 的正确说法。", "do 则可与第三人称单数的主语以外的任何主语并用。", "第三人称复数主语：", "第二人称单数主语：", "第一人称单复数主语：", "中文：谁会来？", "英文：Who will come?（非 Will who come?）", "中文：哪一个比较好？", "英文：Which is better?（非 Is which better?）"], "formulas": [], "examples": []}, {"num": 2, "title": "表示“您府上/籍贯哪儿？”有下列说法：", "desc": ["Where are you from? 您府上哪儿？", "= Where do you come from?", "What's your nationality? 您是什么国籍？", "以上三个问句中，前两句可用以询问对方的省籍或国籍，但最后一句则仅限于国籍。请看下列对话：", "= Where do you come from?", "= I come from New York. / I come from America.", "（甲：您府上哪儿？）", "（乙：我是纽约人。/我是美国人。）"], "formulas": [], "examples": []}, {"num": 3, "title": "What about you? 那你呢？", "desc": ["= How about you?", "这是一种简化的问句，以省略重复的字或短语。这种句型在会话中常见，极为实用。请看下列句子的比较：", "（我喜欢音乐。你也喜欢音乐吗？）", "→ I love music. What about you?", "（佳）", "= I love music. How about you?", "（我喜欢音乐。那您呢？）", "→ He is from China. What about her?", "（佳）", "= He is from China. How about her?（他是中国人。那她呢？）"], "formulas": [], "examples": []}, {"num": 1, "title": "May I have your name, please? 请问尊姓大名？", "desc": ["= May I know your name, please?", "What's your name? 你叫什么名字？", "这个字是副词，多置于句尾，之前置逗点，可用以减缓命令的语气。", "→ Come here, please.（请过来。）", "= Please come here.", "May I..., please? 请问我可以...吗？", "→ May I open the window, please?（请问我可以打开窗户吗？——更客气）"], "formulas": [], "examples": []}, {"num": 2, "title": "How old are you? 你几岁了？", "desc": ["= What's your age? 你年龄多大？", "以上都是询问对方年龄的问句。咱们中国人彼此见面可以询问对方年龄，但与西方人交往时，除非对方主动透露自己的年龄，否则我们随意询问别人的年龄会被视为不礼貌的行为。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "What's [your / his / her] name?", "zh": "你/他/她叫什么名字？", "pairs": [{"en": "What's [your / his / her] name?", "zh": "你/他/她叫什么名字？"}]}, {"num": 2, "en": "[I'm / My name's] May.", "zh": "我叫/我的名字是小梅。", "pairs": [{"en": "[I'm / My name's] May.", "zh": "我叫/我的名字是小梅。"}]}, {"num": 3, "en": "Where [are you from? / do you come from?]", "zh": "你是哪里人？", "pairs": [{"en": "Where [are you from? / do you come from?]", "zh": "你是哪里人？"}]}, {"num": 4, "en": "I [am / come] from Hong Kong.", "zh": "我是香港人。", "pairs": [{"en": "I [am / come] from Hong Kong.", "zh": "我是香港人。"}]}, {"num": 5, "en": "May I [have / know] your name, please?", "zh": "请问尊姓大名？", "pairs": [{"en": "May I [have / know] your name, please?", "zh": "请问尊姓大名？"}]}, {"num": 6, "en": "How old [are you? / is he? / is she?]", "zh": "你/他/她几岁了？", "pairs": [{"en": "How old [are you? / is he? / is she?]", "zh": "你/他/她几岁了？"}]}, {"num": 7, "en": "I'm [twenty-five. / twenty-five years old.]", "zh": "我25岁。", "pairs": [{"en": "I'm [twenty-five. / twenty-five years old.]", "zh": "我25岁。"}]}, {"num": 8, "en": "I'm [Japanese. / Chinese. / American.]", "zh": "我是日本人/中国人/美国人。", "pairs": [{"en": "I'm [Japanese. / Chinese. / American.]", "zh": "我是日本人/中国人/美国人。"}]}], "exercises": []}, {"num": 4, "title_en": "Introductions", "title_zh": "介绍", "type": "dialogue", "category": "日常高频情境口语", "tip": "介绍朋友时口语习惯说 'This is my friend, Mike.'。现代初次见面除了 'Nice to meet you'，年轻人还极高频使用 'Great to meet you!'", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hi, Tom! How's it going?", "zh": "嗨，汤姆！近来如何？"}, {"speaker": "B", "en": "Great! Who's your friend?", "zh": "很好！你的朋友怎么称呼？"}, {"speaker": "A", "en": "Oh! I'm sorry. This is Kay.", "zh": "噪！真抱歉。这位是凯。"}, {"speaker": "B", "en": "Pleased to meet you, Kay.", "zh": "幸会，凯。"}, {"speaker": "C", "en": "Nice to meet you.", "zh": "幸会。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Dad. Please meet my girlfriend, May.", "zh": "爸爸，见见我的女朋友小梅。"}, {"speaker": "B", "en": "Glad to meet you, May.", "zh": "很高兴认识你，小梅。"}, {"speaker": "C", "en": "Glad to meet you, too, Mr. Lin.", "zh": "我也很高兴认识您，林先生。"}, {"speaker": "B", "en": "And what is your family name, May?", "zh": "小梅，那么你贵姓呀？"}, {"speaker": "C", "en": "It's Chen. But you may call me May.", "zh": "我姓陈。不过您可以叫我小梅。"}, {"speaker": "B", "en": "May Chen. It's a nice name.", "zh": "陈小梅，这是个好名字。"}, {"speaker": "C", "en": "Thank you, sir.", "zh": "谢谢您，先生。"}]}], "reading": null, "vocab": [{"num": 1, "word": "introduction", "phonetic": "[ˌɪntrəˈdʌkʃən]", "pos": "名", "meaning": "介绍，引见"}, {"num": 2, "word": "friend", "phonetic": "[frɛnd]", "pos": "名", "meaning": "朋友"}, {"num": 3, "word": "this", "phonetic": "[ðɪs]", "pos": "代", "meaning": "这个"}, {"num": 4, "word": "Kay", "phonetic": "[ke]", "pos": "名", "meaning": "凯（女性名）"}, {"num": 1, "word": "dad", "phonetic": "[dæd]", "pos": "名", "meaning": "爸爸（比 father ['fɑðɚ] 更亲昵的称呼）"}, {"num": 2, "word": "girlfriend", "phonetic": "[ˈɡɜːrlfrend]", "pos": "名", "meaning": "女朋友"}, {"num": 3, "word": "glad", "phonetic": "[ɡlæd]", "pos": "形", "meaning": "高兴的"}, {"num": 4, "word": "Mr. Lin", "phonetic": "[ˈmɪstɚ]", "pos": "名", "meaning": "林先生"}, {"num": 5, "word": "family name 姓（= last name = surname", "phonetic": "[ˈsɝnem]", "pos": "", "meaning": "；family ['fæməlɪ] 形 家族/家庭的 &amp; 名 家族/家庭"}, {"num": 6, "word": "Chen", "phonetic": "[tʃɛn]", "pos": "名", "meaning": "陈（姓氏）"}, {"num": 7, "word": "but", "phonetic": "[bʌt]", "pos": "连", "meaning": "但是"}, {"num": 8, "word": "call", "phonetic": "[kɔl]", "pos": "动", "meaning": "称呼，叫"}, {"num": 9, "word": "sir", "phonetic": "[sɝ]", "pos": "名", "meaning": "先生（称呼语）"}], "grammar": [{"num": 1, "title": "将熟识的人介绍给对方时，一般而言，有一个遵循的法则：", "desc": ["男性被介绍给女性或晚辈被介绍给长辈，以示礼貌。", "请看下列会话：", "（约翰：玛丽，这位是杰克。）", "（玛丽：嗨，杰克。幸会。）", "（杰克：幸会。）", "（儿子：爸，这位是小梅。）", "（爸爸：小梅，很高兴认识你。）", "（小梅：威尔逊先生，我也很高兴认识您。）"], "formulas": [], "examples": []}, {"num": 2, "title": "This is Kay. 这位是凯。", "desc": ["此处 This 是指示代名词，表示“这个”。", "指示代名词就是指名某个或某些东西的代名词，通常有四个：", "this （这个）、that （那个）、these （这些）、those （那些）。前两者代替单数的名词，后两者则代替复数的名词。", "通常离说话者较近的东西，应使用 this 或 these 代替，而离说话者较远的东西，则使用 that 或 those 代替，参阅下列图示：", "会话："], "formulas": [], "examples": []}, {"num": 1, "title": "And what is your family name, Mary?", "desc": ["（小梅，那么你贵姓呀？）", "不过 and 通常作连接词用，译成“和”“与”之意。", "姓：family name = last name = surname", "名：first name = given name"], "formulas": [], "examples": []}, {"num": 2, "title": "Glad to meet you, too, Mr. Lin.", "desc": ["（我也很高兴认识您，林先生。）", "下列是常用的礼貌称谓语：", "Mr. Wang 王先生（Mr. 是 Mister ['mɪstɚ] 的缩写）", "Mrs. Wang 王太太（Mrs. 是 Missus / Missis ['mɪsɪz] 的缩写）", "Miss Wang 王小姐（Miss [mɪs]） 多冠在未婚女士的姓氏前。", "Ms. Wang 王女士（Ms. [mɪz]） 冠在已婚或未婚女士的姓氏前。我们见到某女士，知其未婚时，就用 Miss 称呼，但无法确知其已婚或未婚时，则用 Ms. 称呼。", "Mr. &amp; Mrs. Wang are English teachers. They have a daughter. We call her Miss Wang. She has a friend. She is Ms. Lin. Miss Wang and Ms. Lin are very good friends.", "（王先生夫妇是英文老师，他们有一个女儿，我们称呼她王小姐。她有一位朋友，她是林女士。王小姐和林女士是很要好的朋友。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "[This / She] is Kay.", "zh": "这位/她是凯。", "pairs": [{"en": "[This / She] is Kay.", "zh": "这位/她是凯。"}]}, {"num": 2, "en": "What's your [family name? / last name? / surname?]", "zh": "你贵姓？", "pairs": [{"en": "What's your [family name? / last name? / surname?]", "zh": "你贵姓？"}]}, {"num": 3, "en": "Glad to meet you, too, [Mr. Lin. / Mrs. Wang. / Miss Lin. / Ms. Chen.]", "zh": "我也很高兴认识你，林先生/王太太/林小姐/陈女士。", "pairs": [{"en": "Glad to meet you, too, [Mr. Lin. / Mrs. Wang. / Miss Lin. / Ms. Chen.]", "zh": "我也很高兴认识你，林先生/王太太/林小姐/陈女士。"}]}, {"num": 4, "en": "[This / That] is a book.", "zh": "这/那是一本书。", "pairs": [{"en": "[This / That] is a book.", "zh": "这/那是一本书。"}]}, {"num": 5, "en": "[These / Those] are my students.", "zh": "这些/那些是我的学生。", "pairs": [{"en": "[These / Those] are my students.", "zh": "这些/那些是我的学生。"}]}, {"num": 6, "en": "[This / That] pen is red.", "zh": "这/那支笔是红色的。", "pairs": [{"en": "[This / That] pen is red.", "zh": "这/那支笔是红色的。"}]}, {"num": 7, "en": "[These / Those] chairs are green.", "zh": "这些/那些椅子是绿色的。", "pairs": [{"en": "[These / Those] chairs are green.", "zh": "这些/那些椅子是绿色的。"}]}], "exercises": []}, {"num": 5, "title_en": "Occupations", "title_zh": "职业", "type": "dialogue", "category": "日常高频情境口语", "tip": "现代美语询问职业多用 'What do you do?' 或 'What line of work are you in?'，极少说 'What is your job?'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me, Mr. Li. This is Miss Lin.", "zh": "打扰一下，李先生。这位是林小姐。"}, {"speaker": "B", "en": "How do you do, Miss Lin?", "zh": "林小姐，你好！"}, {"speaker": "C", "en": "How do you do?", "zh": "你好！"}, {"speaker": "A", "en": "Miss Lin works for IBM.", "zh": "林小姐在IBM 公司上班。"}, {"speaker": "B", "en": "What a coincidence! I work in a computer company, too.", "zh": "好巧呀！我也是在一家电脑公司上班。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, Tom! I'd like you to meet my friend, Sal.", "zh": "嗨，汤姆。我想请你见见我的朋友莎儿。"}, {"speaker": "B", "en": "Pleased to meet you, Sal.", "zh": "很高兴认识你，莎儿。"}, {"speaker": "C", "en": "Same here.", "zh": "我也一样。"}, {"speaker": "B", "en": "So, what do you do, Sal?", "zh": "那，你从事哪一行的？"}, {"speaker": "C", "en": "I'm a secretary. What about you?", "zh": "我是个秘书。你呢？"}, {"speaker": "B", "en": "I'm a pilot.", "zh": "我是开飞机的。"}]}], "reading": null, "vocab": [{"num": 1, "word": "occupation", "phonetic": "[ɑkjəˈpeʃən]", "pos": "名", "meaning": "职业"}, {"num": 2, "word": "How do you do?", "phonetic": "", "pos": "", "meaning": "你好!（初次见面时的礼貌用语）"}, {"num": 3, "word": "work for…… 为……工作；work", "phonetic": "[wɝk]", "pos": "动", "meaning": "工作"}, {"num": 4, "word": "what a coincidence!", "phonetic": "[koˈɪnsədəns]", "pos": "名", "meaning": "好巧呀!"}, {"num": 5, "word": "work in……", "phonetic": "", "pos": "", "meaning": "在……上班"}, {"num": 6, "word": "computer", "phonetic": "[kəmˈpjutɚ]", "pos": "名", "meaning": "电脑"}, {"num": 7, "word": "company", "phonetic": "[ˈkʌmpəni]", "pos": "名", "meaning": "公司"}, {"num": 1, "word": "I'd like you to……", "phonetic": "[wʊd]", "pos": "助", "meaning": "我想要你……（是&quot;I would like you to……&quot;的缩写）"}, {"num": 2, "word": "Sal", "phonetic": "[sæl]", "pos": "名", "meaning": "莎儿（女性名）"}, {"num": 3, "word": "Same here!", "phonetic": "[sem]", "pos": "形", "meaning": "我也一样!"}, {"num": 4, "word": "What do you do?", "phonetic": "", "pos": "", "meaning": "你从事哪一行的?"}, {"num": 5, "word": "secretary", "phonetic": "[ˈsekrəteri]", "pos": "名", "meaning": "秘书"}, {"num": 6, "word": "pilot", "phonetic": "[ˈpaɪlət]", "pos": "名", "meaning": "飞行员，驾驶员"}], "grammar": [{"num": 1, "title": "How do you do, Miss Lin? 林小姐，你好！", "desc": ["Mr. Wang: How do you do, Miss Lin?", "（林小姐：王先生，你好！）", "（王先生：林小姐，你好！）", "前句相当于中文的“你/您好！”，不要译成“你/您好吗？”，故不可以&quot;I'm fine, thank you.&quot;（我很好，谢谢你/您。）", "回应。即：", "后两者使用于认识的朋友之间，纯粹表示关怀对方身体的问候语，故可用&quot;I'm fine, thank you.&quot;回应。即："], "formulas": [], "examples": []}, {"num": 2, "title": "work for 为...工作", "desc": [], "formulas": [], "examples": []}, {"num": 3, "title": "What a coincidence! 好巧呀！", "desc": ["本句是已简化过的感叹句。原句完整的写法为：", "What a coincidence this/it is!", "（这真是个巧合呀！）", "感叹句一共有两种，一为What 引导，另一为How 引导，细则如下："], "formulas": [], "examples": []}, {"num": 4, "title": "I'd like you to meet my friend, Sal. 我想请你见见我的朋友莎儿。", "desc": ["本句型&quot;I'd like&quot;乃由&quot;I would like&quot;简化而成，是一种请求某人做某事，但语气客气的祈使句。句型如下：", "若表示“我想要...”时，则可采下列句型："], "formulas": [], "examples": []}, {"num": 5, "title": "Pleased to meet you, Sal. / Same here. 很高兴认识你，莎儿。/ 我也一样。", "desc": ["此处&quot;Same here&quot;按字义译成“这里是相同的。”实则译成“我也一样。”相当于&quot;Me too.&quot;（我也一样。），此处则等于&quot;Pleased to meet you, too.&quot;（我也很高兴认识你。）；换言之，&quot;Same here.&quot;或&quot;Me too.&quot;可用来表示赞同对方的意见。", "此处的&quot;Same here&quot;等于&quot;I love music, too.&quot;（我也喜欢音乐。）"], "formulas": [], "examples": []}, {"num": 6, "title": "What do you do? 你从事哪一行的？", "desc": ["= What's your occupation? （你的职业是什么？）", "= What's your job? （你的工作是什么？）", "在&quot;What do you do?&quot;的问句中，第一个do 是助动词，本身不具任何意义，故不须翻译，第二个do 则是及物动词，作“做什么”解。这是特殊问句（即疑问词引导的问句）。", "（有关特殊问句的造句法请参考第3课。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Miss Lin works [for IBM. / in a bank.]", "zh": "林小姐在IBM公司/某银行上班。", "pairs": [{"en": "Miss Lin works [for IBM. / in a bank.]", "zh": "林小姐在IBM公司/某银行上班。"}]}, {"num": 2, "en": "What a [coincidence! / surprise!]", "zh": "好巧呀/真令人惊奇呀！", "pairs": [{"en": "What a [coincidence! / surprise!]", "zh": "好巧呀/真令人惊奇呀！"}]}, {"num": 3, "en": "I'd like you to [meet my friend, Sal. / call me a cab. / give me a call.]", "zh": "我想请你见见我的朋友莎儿/帮我叫部出租车/打个电话给我。", "pairs": [{"en": "I'd like you to [meet my friend, Sal. / call me a cab. / give me a call.]", "zh": "我想请你见见我的朋友莎儿/帮我叫部出租车/打个电话给我。"}]}, {"num": 4, "en": "What [do you do? / is your occupation? / is your job?]", "zh": "你从事哪一行的/你的职业是什么/你的工作是什么？", "pairs": [{"en": "What [do you do? / is your occupation? / is your job?]", "zh": "你从事哪一行的/你的职业是什么/你的工作是什么？"}]}, {"num": 5, "en": "I'm a [secretary. / teacher. / doctor.]", "zh": "我是个秘书/老师/医生。", "pairs": [{"en": "I'm a [secretary. / teacher. / doctor.]", "zh": "我是个秘书/老师/医生。"}]}], "exercises": []}, {"num": 6, "title_en": "Time", "title_zh": "时间", "type": "dialogue", "category": "日常高频情境口语", "tip": "时间表达中，美语倾向于数字直读法，如 7:15 直接读 'seven fifteen'，比 'a quarter past seven' 更简练高频。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me, ma'am. What time is it, please?", "zh": "小姐，打扰一下。请问现在几点了？"}, {"speaker": "B", "en": "It's two thirty.", "zh": "现在是两点半。"}, {"speaker": "A", "en": "Thanks. What time is the next train?", "zh": "谢谢。请问下一班火车是几点开？"}, {"speaker": "B", "en": "Two forty-five.", "zh": "2点45分。"}, {"speaker": "A", "en": "I see. Is it on time?", "zh": "我明白了。它准时吗？"}, {"speaker": "B", "en": "Yes, it is.", "zh": "是的，它很准时。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hi, Tom. What time is it, please?", "zh": "嗨，汤姆。请问现在几点了？"}, {"speaker": "B", "en": "It's a quarter to seven.", "zh": "现在是6点45分。"}, {"speaker": "A", "en": "Oh, no! I'm late.", "zh": "噢，糟了！我迟到了。"}, {"speaker": "B", "en": "It's OK.", "zh": "没关系。"}, {"speaker": "A", "en": "What do you mean?", "zh": "你说这话什么意思？"}, {"speaker": "B", "en": "My watch is fast.", "zh": "我的表快了。"}]}], "reading": null, "vocab": [{"num": 1, "word": "ma'am", "phonetic": "[mæm]", "pos": "名", "meaning": "夫人，小姐（对妇女的口头尊称）"}, {"num": 2, "word": "time", "phonetic": "[taɪm]", "pos": "名", "meaning": "时间"}, {"num": 3, "word": "two", "phonetic": "[tuː]", "pos": "名", "meaning": "二"}, {"num": 4, "word": "thirty", "phonetic": "[ˈθɝtɪ]", "pos": "名", "meaning": "三十"}, {"num": 5, "word": "next", "phonetic": "[nɛkst]", "pos": "形", "meaning": "下一个的，其次"}, {"num": 6, "word": "train", "phonetic": "[tren]", "pos": "名", "meaning": "火车"}, {"num": 7, "word": "forty-five", "phonetic": "[ˈfɔrtɪ ˈfaɪv]", "pos": "名", "meaning": "四十五"}, {"num": 8, "word": "I see.", "phonetic": "", "pos": "", "meaning": "我明白了。"}, {"num": 9, "word": "on time", "phonetic": "", "pos": "", "meaning": "准时"}, {"num": 1, "word": "quarter", "phonetic": "[ˈkwɔrtɚ]", "pos": "名", "meaning": "四分之一；一刻钟（15分钟）"}, {"num": 2, "word": "seven", "phonetic": "[ˈsɛvən]", "pos": "名", "meaning": "七"}, {"num": 3, "word": "late", "phonetic": "[let]", "pos": "形", "meaning": "迟的，晚的"}, {"num": 4, "word": "mean", "phonetic": "[min]", "pos": "动", "meaning": "意味，表示……的意思"}, {"num": 5, "word": "watch", "phonetic": "[wɑtʃ]", "pos": "名", "meaning": "（手） 表"}, {"num": 6, "word": "fast", "phonetic": "[fæst]", "pos": "形", "meaning": "快的，（钟表） 走得快的"}], "grammar": [{"num": 1, "title": "What time is it, please? 请问现在几点了？", "desc": ["What time is it by your watch, please? 请问你的表现在几点了？", "问句中的 it 是代名词，此处代替时间，可表示现在、过去或未来的时间。在本问句中，it 指现在的时间，译成“现在”，不要译成“它/他”。请参看下"], "formulas": [], "examples": []}, {"num": 2, "title": "注意下列基数词的念法：", "desc": [], "formulas": [], "examples": []}, {"num": 3, "title": "下列原则有助于表示时间的说法：", "desc": ["It's noon. 现在是中午12点。", "= It's twelve noon.", "或：", "It's midnight. 现在是午夜12点。", "= It's twelve midnight.", "It's five past three. 现在是3点5分。", "= It's three o five.", "three o one (3:01), three o two (3:02), three o three (3:03), three o four (3:04), three o five (3:05), three o six (3:06), three o seven (3:07), three o eight (3:08), three o nine (3:09)。", "“10分”之后均不需加“o”，即：", "3点10分：three ten", "3点11分：three eleven", "其他表示“几点几分”均以此类推。如：", "1点02分：one o two / two past one", "a quarter 原指“四分之一”，60分的四分之一即15分之意。如：", "It's one fifteen. 现在是1点15分。", "= It's fifteen past one.", "= It's a quarter past one.", "但不可说：", "如：", "It's two thirty. 现在是2点30分 / 两点半。", "= It's half past two.", "但不可说：", "It's twenty to five. 现在是差20分到5点。", "= It's four forty. （现在是4点40分。）", "It's five to ten. 现在是差5分到10点。", "= It's nine fifty-five. （现在是9点55分。）", "It's one o'clock. 现在是1点。", "= It's one.", "It's seven o'clock. 现在是7点。", "= It's seven.", "表示“现在是中午12点 / 午夜12点”就不必使用 &quot;o'clock&quot; 一字。即："], "formulas": [], "examples": []}, {"num": 4, "title": "精确表示时间时，应念出“时”“分”“秒”，即：", "desc": ["时：o'clock [ə'klɑk] 分：minute ['mɪnɪt] 秒：second ['sɛkənd]", "故若表示“现在是5点20分18秒”理应说成："], "formulas": [], "examples": []}, {"num": 5, "title": "表示“现在是上午/下午5点20分”应念成：", "desc": ["It's five twenty a. m. 现在是上午5点20分。", "= It's five twenty A. M.", "It's five twenty p. m. 现在是下午5点20分。", "= It's five twenty P. M."], "formulas": [], "examples": []}, {"num": 6, "title": "I see. 我明白了。", "desc": ["= I understand.", "see 是动词，原指“看见”，如：", "但 see 亦可表示“明白”、“了解”之意。"], "formulas": [], "examples": []}, {"num": 7, "title": "Is it on time? 它（这班火车） 准时吗？", "desc": ["on time 准时"], "formulas": [], "examples": []}, {"num": 1, "title": "What do you mean? 你这是什么意思？", "desc": [], "formulas": [], "examples": []}, {"num": 2, "title": "My watch is fast. 我的表快了。", "desc": ["My watch is slow. 我的表慢了。", "在上列句型中，fast 或 slow 之前可置表示时间的名词，分别表示“快/慢若干时间”。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "[What time is it, please? / What time is it by your watch, please?]", "zh": "请问现在几点了？ / 请问你的表现在几点了？", "pairs": [{"en": "[What time is it, please? / What time is it by your watch, please?]", "zh": "请问现在几点了？ / 请问你的表现在几点了？"}]}, {"num": 2, "en": "It's [two thirty. / two o'clock. / ten a.m. / one p.m.]", "zh": "现在是2点30分/2点钟/上午10点/下午1点。", "pairs": [{"en": "It's [two thirty. / two o'clock. / ten a.m. / one p.m.]", "zh": "现在是2点30分/2点钟/上午10点/下午1点。"}]}, {"num": 3, "en": "It's [a quarter to seven. / six forty-five.]", "zh": "现在是7点差15分/6点45分。", "pairs": [{"en": "It's [a quarter to seven. / six forty-five.]", "zh": "现在是7点差15分/6点45分。"}]}, {"num": 4, "en": "It's [five twenty. / twenty after five.]", "zh": "现在是5点20分。", "pairs": [{"en": "It's [five twenty. / twenty after five.]", "zh": "现在是5点20分。"}]}, {"num": 5, "en": "My watch is [fast. / one hour fast. / slow. / ten minutes slow.]", "zh": "我的表快了/快了1个小时/慢了/慢了10分钟。", "pairs": [{"en": "My watch is [fast. / one hour fast. / slow. / ten minutes slow.]", "zh": "我的表快了/快了1个小时/慢了/慢了10分钟。"}]}], "exercises": []}, {"num": 7, "title_en": "Day and Date", "title_zh": "日期", "type": "dialogue", "category": "日常高频情境口语", "tip": "询问今日日期最地道的问法是 'What's the date today?' 或简短的 'What's today's date?'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "What day is it today, Tom?", "zh": "汤姆，今天是星期几？"}, {"speaker": "B", "en": "It's Monday.", "zh": "今天星期一。"}, {"speaker": "A", "en": "And is today June 6?", "zh": "那么今天是不是6月6日？"}, {"speaker": "B", "en": "Yes, it is. Why?", "zh": "是的。为什么问呢？"}, {"speaker": "A", "en": "Because it's my birthday.", "zh": "因为今天是我的生日。"}, {"speaker": "B", "en": "Happy birthday, May.", "zh": "小梅，祝你生日快乐。"}, {"speaker": "A", "en": "Thank you.", "zh": "谢谢。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "What's today's date, Tom?", "zh": "汤姆，今天是几月几号？"}, {"speaker": "B", "en": "It's February 14.", "zh": "2月14号。"}, {"speaker": "A", "en": "What day is it?", "zh": "星期几？"}, {"speaker": "B", "en": "It's Friday. Why?", "zh": "星期五。怎么啦？"}, {"speaker": "A", "en": "Today is Valentine's Day.", "zh": "今天是情人节。"}, {"speaker": "B", "en": "Happy Valentine's Day.", "zh": "情人节快乐。"}]}], "reading": null, "vocab": [{"num": 1, "word": "day", "phonetic": "[de]", "pos": "名", "meaning": "白天；（一星期的某） 日"}, {"num": 2, "word": "today", "phonetic": "[təˈde]", "pos": "名", "meaning": "今天"}, {"num": 3, "word": "Sunday", "phonetic": "[ˈsʌnde]", "pos": "名", "meaning": "星期日"}, {"num": 4, "word": "June", "phonetic": "[dʒun]", "pos": "名", "meaning": "6月"}, {"num": 5, "word": "because", "phonetic": "[bɪˈkɔz]", "pos": "连", "meaning": "因为"}, {"num": 6, "word": "my", "phonetic": "[maɪ]", "pos": "代", "meaning": "我的"}, {"num": 7, "word": "birthday", "phonetic": "[ˈbɝθde]", "pos": "名", "meaning": "生日"}, {"num": 8, "word": "happy", "phonetic": "[ˈhæpɪ]", "pos": "形", "meaning": "快乐的；Happy birthday. 生日快乐。"}, {"num": 1, "word": "date", "phonetic": "[det]", "pos": "名", "meaning": "日期"}, {"num": 2, "word": "February", "phonetic": "[ˈfɛbrʊˌɛrɪ]", "pos": "名", "meaning": "2月"}, {"num": 3, "word": "Friday", "phonetic": "[ˈfraɪde]", "pos": "名", "meaning": "星期五"}, {"num": 4, "word": "Valentine's Day", "phonetic": "", "pos": "", "meaning": "圣瓦伦廷节（2月14日情人节）"}, {"num": 13, "word": "Valentine", "phonetic": "[ˈvæləntaɪn]", "pos": "名", "meaning": "圣瓦伦廷（公元3世纪时罗马基督教殉教者）"}], "grammar": [{"num": 1, "title": "What day is it today, Tom? （汤姆，今天是星期几？）", "desc": ["= What day is today?", "同理：", "= What day is tomorrow?", "= What day is the day after tomorrow?", "或：", "咱们中国人习惯将星期一视为一个星期中的第一天，星期日则为最后一天。但西洋人则是将星期日作为第一天，星期六则为最后一天。即："], "formulas": [], "examples": []}, {"num": 2, "title": "And is today June 6? （那么今天是不是6月6日？）", "desc": ["同理，“1999年3月2日”应写成：March 2, 1999。", "上列日期中的阿拉伯数字不是基数（即 one, two, three... 表示一、二、三...），而是序数（即 first, second, third... 表示第一、第二、第三...）。故 &quot;June 6, 1998&quot; 要念成：", "= June the sixth, nineteen ninety-eight (较正式，美式用法)", "= the sixth (day) of June, nineteen ninety-eight (正式，英式用法)", "以上三种念法中，以第一种最为口语，也最为常用。"], "formulas": [], "examples": []}, {"num": 3, "title": "序数词就是表示次序（第一、第二、第三...） 的数词，请参看下列序数词的写法：", "desc": [], "formulas": [], "examples": []}, {"num": 4, "title": "基数词与序数词的区别：", "desc": ["基数词是用来表示数量，序数词则是用来表示次序。请参见下列："], "formulas": [], "examples": []}, {"num": 5, "title": "Happy birthday, May. （小梅，祝你生日快乐。）", "desc": ["这是在某人生日时所使用的祝贺语。原句亦可说成："], "formulas": [], "examples": []}, {"num": 1, "title": "What's today's date, Tom? （汤姆，今天是几月几号？）", "desc": ["上列问句中，date 表示“日期”，而会话 A 中的 day 则指“星期几”，请比较下列对话：", "表示“今天是几月几号？”习惯说成：", "= What's the date today?", "而不要说成："], "formulas": [], "examples": []}, {"num": 2, "title": "Today is Valentine's Day. （今天是情人节。）", "desc": ["Valentine's Day 是为了纪念公元3世纪时为真理及信徒证婚而殉教的圣徒瓦伦廷主教而设立的节日。在这天西洋男女朋友会互赠卡片或巧克力等礼物以表达爱意。", "在西方各种节日的祝贺语通常是在该节日名称前加上 Happy，即：", "Happy + 节日名称"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "What day is it [today? / tomorrow?]", "zh": "今天/明天是星期几？", "pairs": [{"en": "What day is it [today? / tomorrow?]", "zh": "今天/明天是星期几？"}]}, {"num": 2, "en": "It's Sunday [today. / tomorrow.]", "zh": "今天/明天是星期日。", "pairs": [{"en": "It's Sunday [today. / tomorrow.]", "zh": "今天/明天是星期日。"}]}, {"num": 3, "en": "Is today [June 6? / July 7?]", "zh": "今天是不是6月6日/7月7日？", "pairs": [{"en": "Is today [June 6? / July 7?]", "zh": "今天是不是6月6日/7月7日？"}]}, {"num": 4, "en": "Happy [birthday. / New Year.]", "zh": "生日快乐/新年快乐。", "pairs": [{"en": "Happy [birthday. / New Year.]", "zh": "生日快乐/新年快乐。"}]}, {"num": 5, "en": "What's [today's date? / the date today?]", "zh": "今天是几月几号？", "pairs": [{"en": "What's [today's date? / the date today?]", "zh": "今天是几月几号？"}]}, {"num": 6, "en": "It's [February 14, 1999. / February fourteenth, nineteen ninety-nine. / February the fourteenth, nineteen ninety-nine. / the fourteenth of February, nineteen ninety-nine.]", "zh": "今天是1999年2月14日。", "pairs": [{"en": "It's [February 14, 1999. / February fourteenth, nineteen ninety-nine. / February the fourteenth, nineteen ninety-nine. / the fourteenth of February, nineteen ninety-nine.]", "zh": "今天是1999年2月14日。"}]}], "exercises": []}, {"num": 8, "title_en": "The Weather", "title_zh": "天气", "type": "dialogue", "category": "日常高频情境口语", "tip": "聊天气是英美文化最自然的破冰话题：'Nice day today, isn't it?' 或 'Can you believe this rain?' 能迅速拉近距离。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hi, May! I am calling from New York.", "zh": "嗨，小梅！我是从纽约打电话来的。"}, {"speaker": "B", "en": "New York! What are you doing there?", "zh": "纽约！你在那里做什么啊？"}, {"speaker": "A", "en": "I'm here on business.", "zh": "我是来出差的。"}, {"speaker": "B", "en": "How's the weather in New York?", "zh": "纽约的天气怎么样？"}, {"speaker": "A", "en": "It's terrible. It's raining right now.", "zh": "糟透了。现在正在下雨呢。"}, {"speaker": "B", "en": "What a shame!", "zh": "真可惜！"}]}], "reading": {"en": ["There are four seasons in my hometown. It's cool in spring. It's sunny in summer. It's chilly in fall. In winter, it is very cold. Sometimes it even snows."], "zh": ["我家乡有四个季节。春天的天气凉爽，夏天阳光普照，秋天寒冷，而冬天则是非常冷，有时甚至还会下雪呢。"], "sentences": [{"en": "There are four seasons in my hometown.", "zh": "我家乡有四个季节。"}, {"en": "It's cool in spring.", "zh": "春天的天气凉爽，夏天阳光普照，秋天寒冷，而冬天则是非常冷，有时甚至还会下雪呢。"}, {"en": "It's sunny in summer.", "zh": ""}, {"en": "It's chilly in fall.", "zh": ""}, {"en": "In winter, it is very cold.", "zh": ""}, {"en": "Sometimes it even snows.", "zh": ""}]}, "vocab": [{"num": 1, "word": "call", "phonetic": "[kɔl]", "pos": "动", "meaning": "打电话（calling 是 call 的现在分词）"}, {"num": 2, "word": "New York", "phonetic": "[nju ˈjɔrk]", "pos": "名", "meaning": "纽约（地名，位于美国东部）"}, {"num": 3, "word": "on business 出差；business", "phonetic": "[ˈbɪznɪs]", "pos": "名", "meaning": "商业，事业，生意"}, {"num": 4, "word": "weather", "phonetic": "[ˈwɛðɚ]", "pos": "名", "meaning": "天气"}, {"num": 5, "word": "terrible", "phonetic": "[ˈtɛrəbl]", "pos": "形", "meaning": "很糟糕的；恐怖的"}, {"num": 6, "word": "rain", "phonetic": "[ren]", "pos": "动", "meaning": "下雨（raining 是 rain 的现在分词）"}, {"num": 7, "word": "right now 现在；right", "phonetic": "[raɪt]", "pos": "副", "meaning": "立刻，马上（强调用法）；now [naʊ] 副 现在（时间副词）"}, {"num": 8, "word": "what a shame!", "phonetic": "[ʃem]", "pos": "名", "meaning": "真可惜/遗憾!"}, {"num": 1, "word": "there are +", "phonetic": "", "pos": "", "meaning": "复数名词 有……"}, {"num": 2, "word": "season", "phonetic": "[ˈsizn]", "pos": "名", "meaning": "季节"}, {"num": 3, "word": "hometown", "phonetic": "[ˈhomˌtaʊn]", "pos": "名", "meaning": "家乡，故乡"}, {"num": 4, "word": "cool", "phonetic": "[kul]", "pos": "形", "meaning": "凉（爽） 的"}, {"num": 5, "word": "spring", "phonetic": "[sprɪŋ]", "pos": "名", "meaning": "春天"}, {"num": 6, "word": "sunny", "phonetic": "[ˈsʌnɪ]", "pos": "形", "meaning": "出太阳的，有阳光的"}, {"num": 7, "word": "summer", "phonetic": "[ˈsʌmɚ]", "pos": "名", "meaning": "夏天"}, {"num": 8, "word": "chilly", "phonetic": "[ˈtʃɪlɪ]", "pos": "形", "meaning": "寒冷的"}, {"num": 9, "word": "fall", "phonetic": "[fɔl]", "pos": "名", "meaning": "秋天（美式用法）"}, {"num": 10, "word": "winter", "phonetic": "[ˈwɪntɚ]", "pos": "名", "meaning": "冬天"}, {"num": 11, "word": "very", "phonetic": "[ˈvɛrɪ]", "pos": "副", "meaning": "非常地，很"}, {"num": 12, "word": "cold", "phonetic": "[kold]", "pos": "形", "meaning": "（寒） 冷的"}, {"num": 13, "word": "sometimes", "phonetic": "[ˈsʌmˌtaɪmz]", "pos": "副", "meaning": "有时候"}, {"num": 14, "word": "even", "phonetic": "[ˈivən]", "pos": "副", "meaning": "甚至"}, {"num": 15, "word": "snow", "phonetic": "[sno]", "pos": "动", "meaning": "下雪"}], "grammar": [{"num": 1, "title": "语法详解", "desc": ["本会话旨在介绍现在进行式的形态及用法。", "1．现在进行式的形态：", "It's (= It is) raining right now.", "（现在正在下雨。）", "以上各句均属现在进行式的结构。"], "formulas": [], "examples": []}, {"num": 2, "title": "何谓现在进行式？", "desc": ["现在进行式就是一种用来表示“在现在时刻，某动作正在进行”的状态，相当于中文的“（现在） 正在...”之意。其结构如下；主语+现在式的be 动词+现在分词...正在... 现在式的be 动词即：is、am、are。"], "formulas": [], "examples": []}, {"num": 3, "title": "何时使用现在进行式？", "desc": ["只要想表达相当于中文“正在...”的概念时，就可使用现在进行式。", "I'm ( = I am) writing a letter.", "（我正在写--封信。）", "They're ( = They are) doing the work.", "（他们正在做那件工作。）", "换言之，只要中文可说“正在...”时，英文就可使用进行式，否则便不能使用进行式。兹以动词have （有） 为", "有此中文说法：我有钱。（○） 故亦有此英文说法：I have money.（○） 无此中文说法：我正在有钱。（×） 故亦无此英文说法：I'm having money.（x） have 除表示“有”之外，亦可表示“吃（饭）”之意。", "有此中文说法：我正在吃晚餐。（○） 故亦有此英文说法：I'm having dinner.（O） 由上得知，就“现在进行式”而言，中英文是相通的。", "只要本着上述原则，我们就可精确掌握现在进行式使用时机。"], "formulas": [], "examples": []}, {"num": 4, "title": "It's raining right now.", "desc": ["（现在正在下雨。）", "上列句子中，rightnow 及now 意思相同，均译成“现在”，只不过now 之前置rig 有强调的功能，相当于", "“就在现在”。", "不过由于现在进行式本身即已表示“现在”的时刻，故句尾的now 或right now 亦可省略。故：", "He is studying in the library (right) now.", "= He is studying in the library.", "= It's raining."], "formulas": [], "examples": []}, {"num": 5, "title": "How's the weather in New York?", "desc": ["（纽约的天气怎么样？）", "表示“某地的天气如何？”有下列两种说法：", "How's (= How is) the weather in + 地方?", "What's (= What is) the weather like in + 地方?", "= What's the weather like in Tokyo today?", "（东京今天的天气如何？）", "本短文旨在介绍“有”及若干修饰天气的常用形容词。"], "formulas": [], "examples": []}, {"num": 1, "title": "There are four seasons in my hometown.", "desc": ["（我的家乡有四个季节。）", "上句中，&quot;There are&quot; 译成“有”。", "中文里，主语不论是人或地方、事物，均使用相同的动词“有”：", "我有一本书。（人）", "这只猴子有只长尾巴。（动物）", "我的家乡有四个季节。（地方）", "桌上有一本书。（物）", "一年有12个月。（时间）", "但在英文中，表示“有”时，除了动词 have 以外，尚有 there is / there are，这些不同用法经常造成初学英文者的困扰。其实分辨“有”的用法并不难，其详述如下：", "我有一本书。（“我”是人）", "→ I have a book. (O)", "这只猴子有只长尾巴。（“猴子”是动物）", "→ The monkey has a long tail. (O)", "桌上有本书。", "→ There is a book on the desk. (O)", "1年有12个月。", "→ There are twelve months in a year. (O)", "同理：", "树上有只鸟。", "→ There is a bird in the tree. (O)", "我家附近有一所学校。", "→ There is a school near my house. (O)", "试译下列各句：", "参考译句："], "formulas": [], "examples": []}, {"num": 2, "title": "在以 &quot;there is / there are&quot; 起首的句型中，应将 there is 或 there are 视为固定的用语，译成“有”，而不要译成“那里是”。若表示“那里/这里有...”时，应采用下列句型：", "desc": ["那里有个人。", "不可说：", "更不可说：", "而要说：", "这里有五个苹果。"], "formulas": [], "examples": []}, {"num": 3, "title": "修饰天气的形容词常用的如下：", "desc": [], "formulas": [], "examples": []}, {"num": 4, "title": "代名词it 可用以表示“天气”。", "desc": ["在稍早的会话中，我们曾介绍代名词it 可用以代替任何单数的名词、时间。在本课中，我们亦发现it 可用以表示天气，相当于 &quot;the weather&quot; 之意。", "I have a dog. It ( = The dog) is big and strong.", "（我有一条狗，它长得又大又壮。）", "= Today is Monday.", "（今天是星期一。）", "= The weather is cool today.", "（今天的天气凉爽。）"], "formulas": [], "examples": []}, {"num": 5, "title": "比较下列两句的不同：", "desc": ["上列第一句中，rainy 是形容词，表示“下雨的”，强调下雨的“现象”。raining 则是现在分词，与之前的is 形成现在进行式 &quot;is raining&quot;，表示“正在下雨”，强调下雨的“动作”。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "[I am calling from New York. / Helen is watching TV now. / My mother is cooking dinner.]", "zh": "我正从纽约打电话过来。 / 海伦现在正在看电视。 / 我妈妈正在煮晚餐。", "pairs": [{"en": "[I am calling from New York. / Helen is watching TV now. / My mother is cooking dinner.]", "zh": "我正从纽约打电话过来。 / 海伦现在正在看电视。 / 我妈妈正在煮晚餐。"}]}, {"num": 2, "en": "[How's the weather / What's the weather like] in New York?", "zh": "纽约的天气怎么样？", "pairs": [{"en": "[How's the weather / What's the weather like] in New York?", "zh": "纽约的天气怎么样？"}]}, {"num": 3, "en": "[There are four seasons in my hometown. / There is a painting on the wall. / There are many stores near my house.]", "zh": "我家乡有四个季节。 / 墙上有一幅画。 / 我家附近有许多商店。", "pairs": [{"en": "[There are four seasons in my hometown. / There is a painting on the wall. / There are many stores near my house.]", "zh": "我家乡有四个季节。 / 墙上有一幅画。 / 我家附近有许多商店。"}]}, {"num": 4, "en": "There is a dictionary [here. / there.]", "zh": "这里/那里有一本词典。", "pairs": [{"en": "There is a dictionary [here. / there.]", "zh": "这里/那里有一本词典。"}]}, {"num": 5, "en": "It's [cool / cold / hot] today.", "zh": "今天的天气凉爽/寒冷/炎热。", "pairs": [{"en": "It's [cool / cold / hot] today.", "zh": "今天的天气凉爽/寒冷/炎热。"}]}, {"num": 6, "en": "It's a [sunny / rainy / cloudy] day.", "zh": "今天是晴天/雨天/阴天。", "pairs": [{"en": "It's a [sunny / rainy / cloudy] day.", "zh": "今天是晴天/雨天/阴天。"}]}], "exercises": []}, {"num": 9, "title_en": "Telephone Conversation I", "title_zh": "电话会话（一）", "type": "dialogue", "category": "日常高频情境口语", "tip": "接电话口语：'This is Tom speaking.' 或直接 'Tom here.'；若要找人，常用 'Is Mike there?' 或 'Could I speak with Mike?'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hello! May I speak to Bob, please?", "zh": "哈啰！请问我可以跟鲍勃说话吗？"}, {"speaker": "B", "en": "He's not in.", "zh": "他不在。"}, {"speaker": "A", "en": "May I leave a message?", "zh": "我可以留个话吗？"}, {"speaker": "B", "en": "Sure. Go ahead.", "zh": "当然。请说吧。"}, {"speaker": "A", "en": "This is Tom. Please ask him to call me back as soon as possible.", "zh": "我是汤姆。请他尽快回电话给我。"}, {"speaker": "B", "en": "OK. Bye.", "zh": "好的。再见。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I speak to Mr. Wang, please?", "zh": "请问我可以跟王先生说话吗？"}, {"speaker": "B", "en": "Who's calling, please?", "zh": "请问是谁呀？"}, {"speaker": "A", "en": "This is Tom Lin.", "zh": "我是林汤姆。"}, {"speaker": "B", "en": "Hold on, please. (A few seconds later.) He's out at the moment.", "zh": "请稍等一下。（几秒钟后） 他现在出去了。"}, {"speaker": "A", "en": "When will he be back?", "zh": "他什么时候会回来呢？"}, {"speaker": "B", "en": "I don't know.", "zh": "我不知道。"}, {"speaker": "A", "en": "OK, I'll call back later. Bye.", "zh": "好吧。我稍后再打来。再见。"}]}], "reading": null, "vocab": [{"num": 1, "word": "telephone", "phonetic": "[ˈtɛləˌfon]", "pos": "名", "meaning": "电话(机)"}, {"num": 2, "word": "conversation", "phonetic": "[ˌkɑnvɚˈseʃən]", "pos": "名", "meaning": "会话，谈话"}, {"num": 3, "word": "hello", "phonetic": "[həˈlo]", "pos": "叹", "meaning": "哈啰（打招呼用语）"}, {"num": 4, "word": "speak to + 人 跟某人说话；speak", "phonetic": "[spik]", "pos": "动", "meaning": "说话，讲"}, {"num": 5, "word": "Bob", "phonetic": "[bɑb]", "pos": "名", "meaning": "鲍勃（男子名）"}, {"num": 6, "word": "in", "phonetic": "[ɪn]", "pos": "副", "meaning": "在家；在办公室"}, {"num": 7, "word": "leave a message 留话；leave", "phonetic": "[liv]", "pos": "动", "meaning": "留下；message ['mɛsɪdʒ] 名 传言，信息"}, {"num": 8, "word": "sure", "phonetic": "[ʃʊr]", "pos": "副", "meaning": "当然"}, {"num": 9, "word": "go ahead", "phonetic": "[əˈhɛd]", "pos": "副", "meaning": "（电话） 请说话"}, {"num": 10, "word": "ask + 人 + to + 动词 请某人（做……）；ask", "phonetic": "[æsk]", "pos": "动", "meaning": "请求"}, {"num": 11, "word": "back", "phonetic": "[bæk]", "pos": "副", "meaning": "回原处；回来"}, {"num": 12, "word": "as soon as possible", "phonetic": "[æz]", "pos": "副", "meaning": "尽快（地）"}, {"num": 1, "word": "Wang", "phonetic": "[wɑŋ]", "pos": "名", "meaning": "王（姓氏）"}, {"num": 2, "word": "hold on", "phonetic": "[hold]", "pos": "动", "meaning": "（打电话时） 等着,别挂断"}, {"num": 3, "word": "a few +", "phonetic": "[fju]", "pos": "形", "meaning": "名词 一些……"}, {"num": 4, "word": "out", "phonetic": "[aʊt]", "pos": "副", "meaning": "外出"}, {"num": 5, "word": "at the moment", "phonetic": "[ˈmomənt]", "pos": "名", "meaning": "此刻,现在"}, {"num": 6, "word": "know", "phonetic": "[no]", "pos": "名", "meaning": "知道"}, {"num": 7, "word": "call back", "phonetic": "", "pos": "", "meaning": "再回电话,再打电话来"}], "grammar": [{"num": 1, "title": "何谓助动词？", "desc": ["顾名思义，助动词就是一种帮助动词的词类，置于动词之前，以加强动词的语气。", "要了解英文的助动词，就要先了解中文的助动词。", "中文：", "我明天会见你。", "他能做这事。", "你现在可以走了。", "动词“见”“做”“走”之前。", "以上各句若译英文、则为："], "formulas": [], "examples": []}, {"num": 2, "title": "助动词在句中的位置由上得知，中英文均会使用到助动词，且在上述陈述句中，不论中文或英文，助动词均置于动词之前。惟在问句中，助动词所放的位置则有明显的差异。", "desc": ["中文：你明天会见我吗？", "你能做这事吗？", "我现在可以走了吗？", "英文:Will you see me tomorrow?"], "formulas": [], "examples": []}, {"num": 3, "title": "以下是英文中常用的助动词 may （可以），can （能够、可以），will （将要、将会）， must （必须），should （应该/当），shall （要）。", "desc": ["兹将这些助动词的用法介绍如下：", "可以 a. may", "我可以...吗？（语气客气）", "请问我可以...吗？（语气更客气） 说话者想做某件事，礼貌上欲征求对方同意时， 即可使用本句型。", "本课会话中的&quot;May I speak to Bob, please？”（请问我可以跟鲍勃说话吗？）", "及“May I leave a message？”（我可以留个话吗？）", "均属此用法。", "以...长辈或阶级高者准许晚辈或阶级低者行使某件事时，即可使用本句型。", "句型如下：", "...能够...", "= Can I open the window?", "（我可以打开窗户吗？）", "= You can go now.", "（你可以走了。）", "故本课会话中的：", "= Can I speak to Bob, please?", "= Can I leave a message?", "本助动词用以表示未来将发生的事情。句型如下：", "本助动词用以表示应当履行的义务，通常只用在陈述句中。", "本助动词亦用以表示应当履行的义务，语气比 must 弱一些。", "本助动词通常与主语 I 并用，使用于下列问句：", "Shall I...?", "要不要我...？", "这个句型主要是用来主动表示为对方做某件事。"], "formulas": [], "examples": []}, {"num": 4, "title": "He's not in.", "desc": ["他不在。", "本句亦可等于 &quot;He is not here.&quot;"], "formulas": [], "examples": []}, {"num": 5, "title": "下列为表示“留话”的电话用语：", "desc": [], "formulas": [], "examples": []}, {"num": 6, "title": "This is Tom.", "desc": ["我是汤姆。", "两人若没面对面相见，表示“我是...”时则不能说 &quot;I am...&quot;，而要说 &quot;This is...&quot; 或 &quot;It's...&quot;。这种情形用于以下两种情况：", "= Who's calling, please?", "= It's John.", "（甲：请问是谁呀？）", "（乙：我是约翰。）"], "formulas": [], "examples": []}, {"num": 7, "title": "This is he. 我就是。", "desc": ["本句亦是电话用语，常使用于下列对话中："], "formulas": [], "examples": []}, {"num": 8, "title": "as soon as possible 尽快（地）", "desc": ["这是一个固定的短语。第一个 as 是副词，译成“一样地”，soon 是副词，译成“快”，第二个 as 是副词连接词，连接 possible （可能）。字面意思是“和可能一样地快”，实际则译成“尽快（地）”。这个短语使用时多置于句尾。"], "formulas": [], "examples": []}, {"num": 1, "title": "在电话上，表示“请稍候”有下列用语：", "desc": [], "formulas": [], "examples": []}, {"num": 2, "title": "He is out at the moment.", "desc": ["= He is out (now).", "（他此刻不在／外出了。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "[May / Can] I speak to Bob, please?", "zh": "请问我可以跟鲍勃说话吗？", "pairs": [{"en": "[May / Can] I speak to Bob, please?", "zh": "请问我可以跟鲍勃说话吗？"}]}, {"num": 2, "en": "May I [leave a message? / sit down? / ask you a question?]", "zh": "我可以留个话吗？ / 我可以坐下吗？ / 我可以问你一个问题吗？", "pairs": [{"en": "May I [leave a message? / sit down? / ask you a question?]", "zh": "我可以留个话吗？ / 我可以坐下吗？ / 我可以问你一个问题吗？"}]}, {"num": 3, "en": "[This is / It's] Tom.", "zh": "我是汤姆。", "pairs": [{"en": "[This is / It's] Tom.", "zh": "我是汤姆。"}]}, {"num": 4, "en": "[Please ask him to call me back / You must see the doctor / I will finish my homework] as soon as possible.", "zh": "请他尽快回电话给我。 / 你必须尽快去看医生。 / 我会尽快做完家庭作业。", "pairs": [{"en": "[Please ask him to call me back / You must see the doctor / I will finish my homework] as soon as possible.", "zh": "请他尽快回电话给我。 / 你必须尽快去看医生。 / 我会尽快做完家庭作业。"}]}, {"num": 5, "en": "[Hold on, please. / Just a minute, please. / Just a moment, please. / Wait a minute, please. / Wait a moment, please.]", "zh": "请稍候。", "pairs": [{"en": "[Hold on, please. / Just a minute, please. / Just a moment, please. / Wait a minute, please. / Wait a moment, please.]", "zh": "请稍候。"}]}], "exercises": []}, {"num": 10, "title_en": "Telephone Conversation II", "title_zh": "电话会话（二）", "type": "dialogue", "category": "日常高频情境口语", "tip": "电话留言：'Could you take a message for him?' 或 'I'll call back later.'（我稍后再打来）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hello, Dr. Chen's clinic. May I help you?", "zh": "哈啰，这里是陈医师诊所。我可以帮您什么忙吗？"}, {"speaker": "B", "en": "Yes, please. I'd like to make an appointment to see Dr. Chen.", "zh": "是的，麻烦你。我想约见陈医师。"}, {"speaker": "A", "en": "What's your name, please?", "zh": "请问尊姓大名？"}, {"speaker": "B", "en": "My name is Micky Chen.", "zh": "我的名字是陈米其。"}, {"speaker": "A", "en": "Is 4 o'clock in the afternoon OK?", "zh": "下午4点钟可以吗？"}, {"speaker": "B", "en": "That 's fine. Thank you.", "zh": "可以，谢谢你。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "I would like to make a long-distance call to California, please.", "zh": "我想打一个长途电话到加州。"}, {"speaker": "B", "en": "Person to person or station to station?", "zh": "叫人的或叫号的？"}, {"speaker": "A", "en": "Station to station.", "zh": "叫号的。"}, {"speaker": "B", "en": "What's the number, please.", "zh": "请问电话号码几号？"}, {"speaker": "A", "en": "Area code 415,789 - 0277.", "zh": "区域号码为415，对方电话是789-0277。"}, {"speaker": "B", "en": "One moment, please.", "zh": "请稍候。"}]}], "reading": null, "vocab": [{"num": 1, "word": "Dr.", "phonetic": "[ˈdɑktɚ]", "pos": "名", "meaning": "医生，医师（为 doctor 的缩写）"}, {"num": 2, "word": "clinic", "phonetic": "[ˈklɪnɪk]", "pos": "名", "meaning": "诊所"}, {"num": 3, "word": "help", "phonetic": "[hɛlp]", "pos": "动", "meaning": "帮忙，帮助"}, {"num": 4, "word": "I'd like to +", "phonetic": "", "pos": "", "meaning": "动词 我想要……（I'd like 为 I would like 的缩写）"}, {"num": 5, "word": "make an appointment 约定，安排约会；make", "phonetic": "[mek]", "pos": "动", "meaning": "做，安排；appointment [ə'pɔɪntmənt] 名 约定，约会"}, {"num": 6, "word": "Micky", "phonetic": "[ˈmɪki]", "pos": "名", "meaning": "米其（男性名）"}, {"num": 7, "word": "in the afternoon 下午，午后；afternoon", "phonetic": "[ˌæftɚˈnun]", "pos": "名", "meaning": "下午，午后"}, {"num": 8, "word": "OK", "phonetic": "[ˈoˈke]", "pos": "形", "meaning": "好；可以的（= okay）"}, {"num": 1, "word": "long-distance", "phonetic": "[ˈlɔŋˈdɪstəns]", "pos": "形", "meaning": "长途的"}, {"num": 2, "word": "California", "phonetic": "[ˌkæləˈfɔrnjə]", "pos": "名", "meaning": "加州（位于美国西海岸）"}, {"num": 3, "word": "person-to-person", "phonetic": "[ˈpɝsn tə ˈpɝsn]", "pos": "形", "meaning": "叫人的（电话用语）"}, {"num": 4, "word": "station-to-station", "phonetic": "[ˌsteʃən tə ˈsteʃən]", "pos": "形", "meaning": "叫号的"}, {"num": 5, "word": "number", "phonetic": "[ˈn Amba]", "pos": "名", "meaning": "号码"}, {"num": 6, "word": "areacode 区域码，区域代号 area", "phonetic": "[ˈena]", "pos": "名", "meaning": "地区 code[kod] 名代号"}], "grammar": [{"num": 1, "title": "Hello, Dr. Chen's clinic.", "desc": ["= Hello, this is Dr. Chen's clinic.", "（哈啰，我们这里是陈医师诊所。）", "Hello, this is + 公司/组织名称", "不可说：", "Hello, we are Johnson Health Center. ( x ) b. 上述句型中 &quot;this is&quot; 可予省略，故：", "= Hello, Dr. Chen's clinic. May I help you?", "= Hello, Johnson Health Center. May I help you?"], "formulas": [], "examples": []}, {"num": 2, "title": "May I help you?", "desc": ["（我可以帮您什么忙吗？）", "本问句是个礼貌的问句，除可用于电话应对外，尚可用于商店内的对话中。", "咱们中国人进人商店或百货公司时，店员常会说：“请问您要买什么”，直译成英文则为："], "formulas": [], "examples": []}, {"num": 3, "title": "I'd like to make an appointment to see Dr. Chen.", "desc": ["= I would like to make an appointment to see Dr. Chen.", "（我想约见陈医师。）", "注意 &quot;I would like to&quot; 与 &quot;I like to&quot; 的不同：", "I'd like to...", "我想要...", "I want to...", "我要...", "以上两个句型均表示说话者的意愿，但 &quot;I'd like to&quot;", "语气较为委婉客气，而 &quot;I want to&quot; 则语气较直接。"], "formulas": [], "examples": []}, {"num": 4, "title": "Is 4 o'clock in the afternoon OK?", "desc": ["（下午四点钟可以吗？）", "本问句采用了下列句型：", "Is... OK / fine / all right (with you)? ...（对你） 可以吗？"], "formulas": [], "examples": []}, {"num": 5, "title": "语法详解", "desc": ["本会话旨在介绍透过总机小姐或先生（均称为 operator ['ɑpəˌretɚ]） 打国际长途电话时的一些用语。今天许多国家的电话系统已采用国际直拨系统（即 the International Direct Dialing System，简称 IDD），也就是我们可直接在电话上拨号码便可与我们想要联络的人直接通话。但出国旅游或在某些情况下，我们得借重电话总机为我们联络，故下列这些实用的用语我们应牢记之："], "formulas": [], "examples": []}, {"num": 1, "title": "make a call 打一通电话", "desc": ["= make a telephone call", "= make a phone call"], "formulas": [], "examples": []}, {"num": 2, "title": "Person-to-person or station-to-station?", "desc": ["（叫人的还是叫号的？）", "本问句系由下列问句简化而成：", "我们透过总机打长途电话时，若指定要某人接电话，这时就称做 &quot;a person-to-person call&quot;（叫人的电话）；若不指定某人接电话，即任何人接电话都可以，这时就称做 &quot;a station-to-station call&quot;（叫号的电话）。"], "formulas": [], "examples": []}, {"num": 3, "title": "Area code 415, 789-0277.", "desc": ["（区域码为415，对方电话是789-0277。）", "area code 区域码/代号（指对方住的省份或城市代号）", "country code 国家代号"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Hello, [Dr. Chen's / this is Dr. Chen's] [clinic. / office.]", "zh": "哈啰，这里是陈医师诊所/办公室。", "pairs": [{"en": "Hello, [Dr. Chen's / this is Dr. Chen's] [clinic. / office.]", "zh": "哈啰，这里是陈医师诊所/办公室。"}]}, {"num": 2, "en": "[May / Can] I help you? (= What can I do for you?)", "zh": "我可以帮您什么忙吗？", "pairs": [{"en": "[May / Can] I help you? (= What can I do for you?)", "zh": "我可以帮您什么忙吗？"}]}, {"num": 3, "en": "I'd like to [make an appointment to see Dr. Chen. / have a cup of tea. / go with you.]", "zh": "我想约见陈医师。 / 我想要喝杯茶。 / 我想要跟你去。", "pairs": [{"en": "I'd like to [make an appointment to see Dr. Chen. / have a cup of tea. / go with you.]", "zh": "我想约见陈医师。 / 我想要喝杯茶。 / 我想要跟你去。"}]}, {"num": 4, "en": "Is 4 o'clock in the afternoon [OK? / fine? / all right?]", "zh": "下午4点钟可以吗？", "pairs": [{"en": "Is 4 o'clock in the afternoon [OK? / fine? / all right?]", "zh": "下午4点钟可以吗？"}]}, {"num": 5, "en": "I would like to [make / place] a long-distance call to California, please.", "zh": "我想打一个长途电话到加州。", "pairs": [{"en": "I would like to [make / place] a long-distance call to California, please.", "zh": "我想打一个长途电话到加州。"}]}], "exercises": []}, {"num": 11, "title_en": "Telephone Conversation III", "title_zh": "电话会话（三）", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hello, room service.", "zh": "哈啰，这里是客房服务中心。"}, {"speaker": "B", "en": "This is room 369. I'd like to order some food, please.", "zh": "这里是369号房。我想要点一些菜。"}, {"speaker": "A", "en": "I'm sorry, but the kitchen's closed.", "zh": "很抱歉，厨房已经关闭了。"}, {"speaker": "B", "en": "What do you have?", "zh": "那你们有什么？"}, {"speaker": "A", "en": "We have only sandwiches and drinks.", "zh": "我们只有三明治和饮料。"}, {"speaker": "B", "en": "That'll be fine. I'm starving.", "zh": "那也可以。我饿坏了。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Hello, front desk. Can I help you?", "zh": "哈啰，这里是前台。我可以为您效劳吗？"}, {"speaker": "B", "en": "Can you give me a morning call, please?", "zh": "可不可以请你在早上打电话叫我起床？"}, {"speaker": "A", "en": "Sure. What time do you want to get up?", "zh": "当然。你想什么时候起床呢？"}, {"speaker": "B", "en": "Please call me at 6:00 AM.", "zh": "请在早上6点钟打电话来叫我。"}, {"speaker": "A", "en": "No problem.", "zh": "没问题。"}, {"speaker": "B", "en": "Thank you.", "zh": "谢谢。"}]}], "reading": null, "vocab": [{"num": 1, "word": "room service", "phonetic": "[rum]", "pos": "名", "meaning": "（饭店内的） 客房服务（中心）"}, {"num": 2, "word": "order", "phonetic": "[ˈɔrdɚ]", "pos": "动", "meaning": "点（餐）；订购"}, {"num": 3, "word": "some", "phonetic": "[sʌm]", "pos": "形", "meaning": "一些，若干"}, {"num": 4, "word": "food", "phonetic": "[fud]", "pos": "名", "meaning": "食物"}, {"num": 5, "word": "kitchen", "phonetic": "[ˈkɪtʃɪn]", "pos": "名", "meaning": "厨房"}, {"num": 6, "word": "closed", "phonetic": "[klozd]", "pos": "形", "meaning": "（尤指商店或公共场所等） 停止营业的，关闭的"}, {"num": 7, "word": "only", "phonetic": "[ˈonli]", "pos": "副", "meaning": "仅，只"}, {"num": 8, "word": "sandwich", "phonetic": "[ˈsændwɪtʃ]", "pos": "名", "meaning": "三明治"}, {"num": 9, "word": "drink", "phonetic": "[drɪŋk]", "pos": "名", "meaning": "饮料"}, {"num": 10, "word": "starve", "phonetic": "[stɑrv]", "pos": "动", "meaning": "饥饿；饿死（starving 是starve 的现在分词）"}, {"num": 1, "word": "front desk", "phonetic": "[frʌnt]", "pos": "形", "meaning": "（饭店中的） 前台"}, {"num": 2, "word": "morning call", "phonetic": "", "pos": "", "meaning": "早上叫人起床的电话"}, {"num": 3, "word": "get up", "phonetic": "", "pos": "", "meaning": "起床"}, {"num": 4, "word": "No problem.", "phonetic": "[ˈprɑbləm]", "pos": "名", "meaning": "没问题。"}], "grammar": [{"num": 1, "title": "Hello, room service. 哈啰，这里是客房服务中心。", "desc": ["本句之原句法为：", "Hello, this is the room service department/section.", "但实际使用时，只说 room service，而不说 the room service department 或 the room service section。", "room service 是饭店中的客房服务中心，供房客叫餐饮、点心之类的地方。有些房客不在餐厅中用餐，这时就可通过 room service 的服务将餐点送至房间。"], "formulas": [], "examples": []}, {"num": 2, "title": "I'd like to order some food, please. 我想点一些菜。", "desc": [], "formulas": [], "examples": []}, {"num": 3, "title": "I'm sorry, but the kitchen's closed. 很抱歉，厨房已经关闭了。", "desc": ["The bookstore closes at 10:00 PM every day.", "（那家书店每天晚上10点打烊。）"], "formulas": [], "examples": []}, {"num": 4, "title": "That'll be fine. 那也可以。", "desc": [], "formulas": [], "examples": []}, {"num": 5, "title": "I'm starving. 我饿坏了。", "desc": ["上句中的 starving 是动词 starve 的现在分词。starve 作不及物动词用，原意为“饿死”，在此夸张地作“饿坏了”，也就等于 &quot;I am very hungry.&quot;。", "甚至还有下列夸张的说法："], "formulas": [], "examples": []}, {"num": 6, "title": "Hello, front desk. 哈啰，这里是前台。", "desc": ["front desk 的字面意思直译为“前面的桌子”，但我们可千万不能这样翻译，front desk 的真正意思指的是“饭店中的前台”。我们现在来介绍有关 front 的一个重要用法：", "in front of... 在...的前面"], "formulas": [], "examples": []}, {"num": 7, "title": "Can you give me a morning call, please? 可不可以请你在早上打电话叫我起床？", "desc": ["morning call 乃特指在早上叫人起床的电话，而 wake-up call 也是指叫人起床的电话，但则不限于在什么时间。", "Can you give me a morning call at 5:00 tomorrow, please?", "（可不可以请你在明早5点钟打电话叫我起床？）", "Can you give me a wake-up call at 4:00 PM, please?", "（可不可以请你在下午4点钟打电话叫我起床？）"], "formulas": [], "examples": []}, {"num": 8, "title": "get up 起床 / go to bed 上床睡觉", "desc": ["I usually go to bed at 10:00 PM and get up at 6:00 in the morning every day.", "（我每天通常在晚上10点钟就寝，早上6点钟起床。）"], "formulas": [], "examples": []}, {"num": 9, "title": "Please call me at 6:00 AM. 请在早上6点钟打电话叫我。", "desc": ["= Please give me a call at 6:00 AM.", "= Please ring me (up) at 6:00 AM.", "= Please give me a ring at 6:00 AM.", "欲表示“打电话给某人”可采用下列短语：", "= I'll give you a call tonight.", "= I'll ring you (up) tonight.", "= I'll give you a ring tonight.", "（今晚我会打电话给你。）"], "formulas": [], "examples": []}, {"num": 10, "title": "No problem. 没问题。", "desc": ["这是一种用来回应他人，表示愿意做对方所要求之事或有能力做某事的用语。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "I'd like to order [some food, / two steaks, / a cup of coffee,] please.", "zh": "我想点一些菜/两块牛排/一杯咖啡，麻烦你。", "pairs": [{"en": "I'd like to order [some food, / two steaks, / a cup of coffee,] please.", "zh": "我想点一些菜/两块牛排/一杯咖啡，麻烦你。"}]}, {"num": 2, "en": "I'm sorry, but [the kitchen's closed. / I can't go with you. / you must leave now.]", "zh": "很抱歉，厨房已经关闭了/我不能和你一起去/你现在必须要离开了。", "pairs": [{"en": "I'm sorry, but [the kitchen's closed. / I can't go with you. / you must leave now.]", "zh": "很抱歉，厨房已经关闭了/我不能和你一起去/你现在必须要离开了。"}]}, {"num": 3, "en": "I'm [starving. / very hungry.]", "zh": "我饿坏了/我很饿。", "pairs": [{"en": "I'm [starving. / very hungry.]", "zh": "我饿坏了/我很饿。"}]}, {"num": 4, "en": "Can you give me a [morning call? / wake-up call?]", "zh": "可不可以请你在早上打电话给我叫我起床？", "pairs": [{"en": "Can you give me a [morning call? / wake-up call?]", "zh": "可不可以请你在早上打电话给我叫我起床？"}]}, {"num": 5, "en": "Please [call me at 6:00 am. / give me a call tomorrow. / ring me up as soon as possible.]", "zh": "请在早上6点打电话给我/请明天打电话给我/请尽快打电话给我。", "pairs": [{"en": "Please [call me at 6:00 am. / give me a call tomorrow. / ring me up as soon as possible.]", "zh": "请在早上6点打电话给我/请明天打电话给我/请尽快打电话给我。"}]}], "exercises": []}, {"num": 12, "title_en": "Buying Things", "title_zh": "买东西", "type": "dialogue", "category": "日常高频情境口语", "tip": "商店买东西：店员问 'May I help you?'，若只想随便看看，标准回应是 'I'm just looking, thanks.'（我就先看看，谢谢）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "How much does that pen cost?", "zh": "那枝笔要多少钱？"}, {"speaker": "B", "en": "It costs ten dollars.", "zh": "10块钱。"}, {"speaker": "A", "en": "That's very expensive. Do you have anything cheaper?", "zh": "那很贵。你们有没有比较便宜的？"}, {"speaker": "B", "en": "Sure. This pen is only two dollars.", "zh": "当然。这枝笔只要两块钱。"}, {"speaker": "A", "en": "Good. I'll take it.", "zh": "好。我就买这枝。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "How much is this book?", "zh": "这本书要多少钱？"}, {"speaker": "B", "en": "It's seven dollars.", "zh": "七块钱。"}, {"speaker": "A", "en": "Do you have change for a hundred?", "zh": "你有零钱找开100块吗？"}, {"speaker": "B", "en": "No problem.", "zh": "没问题。"}, {"speaker": "A", "en": "OK. Here's the money.", "zh": "好。钱给你。"}, {"speaker": "B", "en": "Thank you. Here's the book and your change.", "zh": "谢谢。这儿是你的书和零钱。"}]}], "reading": null, "vocab": [{"num": 1, "word": "buy", "phonetic": "[baɪ]", "pos": "动", "meaning": "（购） 买"}, {"num": 2, "word": "thing", "phonetic": "[θɪŋ]", "pos": "名", "meaning": "东西，物品"}, {"num": 3, "word": "how much 多少钱；much", "phonetic": "[mʌtʃ]", "pos": "代", "meaning": "大量，许多"}, {"num": 4, "word": "pen", "phonetic": "[pɛn]", "pos": "名", "meaning": "笔（可指钢笔或圆珠笔）"}, {"num": 5, "word": "cost", "phonetic": "[kɔst]", "pos": "动", "meaning": "价值（若干），需花（多少钱）"}, {"num": 6, "word": "dollar", "phonetic": "[ˈdɑlɚ]", "pos": "名", "meaning": "美元，圆"}, {"num": 7, "word": "expensive", "phonetic": "[ɪkˈspensɪv]", "pos": "形", "meaning": "昂贵的"}, {"num": 8, "word": "anything", "phonetic": "[ˈɛnɪθɪŋ]", "pos": "代", "meaning": "任何东西"}, {"num": 9, "word": "cheaper", "phonetic": "[ˈtʃipɚ]", "pos": "形", "meaning": "比较便宜的（cheap 的比较级）；cheap [tʃip] 形 便宜的"}, {"num": 1, "word": "book", "phonetic": "[bʊk]", "pos": "名", "meaning": "书（籍）"}, {"num": 2, "word": "change", "phonetic": "[tʃeɪndʒ]", "pos": "名", "meaning": "零钱"}, {"num": 3, "word": "money", "phonetic": "[ˈmʌni]", "pos": "名", "meaning": "（金） 钱"}], "grammar": [{"num": 1, "title": "How much does that pen cost? 那枝笔要花多少钱？", "desc": ["= How much is that pen? 那枝笔多少钱？", "当我们想表示“某物品要（花） 多少钱？”时，可用下列句型：", "How much (money) does + 单数物品 + cost?", "= How much (money) is + 单数物品?", "How much (money) do + 复数物品 + cost?", "= How much (money) are + 复数物品?", "= How much is that shirt?", "（那件衬衫要多少钱？）", "= How much are these pencils?", "（这些铅笔要多少钱？）", "上列句型中的 much 为代名词，how much 理论上是由 how much money 简化而来。money （金钱） 是不可数名词，不能说 one money, two moneys，因此必须用 much 修饰：", "（你有多少钱？）", "paper （纸） 也是不可数名词，不能说 a paper、two papers，必须用单位 piece，如 a piece of paper （一张纸）、two pieces of paper （两张纸）。water （水） 也是不可数名词，须用单位，如 a glass of water （一杯水）、two glasses of water （两杯水）。", "可数名词像 book （书）、student （学生） 等，本身可以数，就不能用 much 修饰，而要用 many：", "（你有多少本书？）", "（房间里有多少个学生？）", "上列句型中的 cost 表示“价值（多少钱）”，使用这个字时，必须以“物品”作主语，不可以“人”作主语："], "formulas": [], "examples": []}, {"num": 2, "title": "That's very expensive. 那很贵。", "desc": ["（这部车很贵。）", "（这栋房子的价格很高。）", "（这栋房子很贵。）"], "formulas": [], "examples": []}, {"num": 3, "title": "Do you have anything cheaper? 你们有没有比较便宜的东西？", "desc": ["形容词修饰一般名词时置于名词前，但修饰 anything, something, nothing 时，形容词必须置于其后：", "（你有什么重要的事情要告诉我吗？）", "= The poor man doesn't have anything to eat. ( ✔ )", "（那可怜的男人没有东西可吃。）", "= There isn't anything nice to eat in that restaurant.", "（那家餐厅没什么好吃的东西。）", "规则 1：双音节或三音节以上的形容词，在其前加 more：", "规则 2：单音节的形容词，在字尾加 -er：", "规则 3：以单一辅音字母结尾的单音节形容词，先双写该辅音字母，再加 -er："], "formulas": [], "examples": []}, {"num": 4, "title": "I'll take it. 我就把它买下了。", "desc": ["这是在商店中常用的会话，表示要买下某个东西之意，就等于 &quot;I'll buy it.&quot;。"], "formulas": [], "examples": []}, {"num": 5, "title": "Do you have change for a hundred? 你有零钱找开100块吗？", "desc": ["= Do you have change for a hundred dollars?", "change 在此处作“零钱”解，是不可数名词。cash （现金） 也是不可数名词，不能说 a cash 或 two cashes。", "（你需要多少零钱？）"], "formulas": [], "examples": []}, {"num": 6, "title": "OK. Here's the money. 好。钱给你。", "desc": [], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "How much [does that pen cost? / is that pen?]", "zh": "那支钢笔要多少钱？", "pairs": [{"en": "How much [does that pen cost? / is that pen?]", "zh": "那支钢笔要多少钱？"}]}, {"num": 2, "en": "[It costs / It's] ten dollars.", "zh": "它价值/要10块钱。", "pairs": [{"en": "[It costs / It's] ten dollars.", "zh": "它价值/要10块钱。"}]}, {"num": 3, "en": "That's very [expensive. / cheap.]", "zh": "那很贵/便宜。", "pairs": [{"en": "That's very [expensive. / cheap.]", "zh": "那很贵/便宜。"}]}, {"num": 4, "en": "Do you have anything [cheaper? / special?]", "zh": "你们有没有比较便宜的/特别的？", "pairs": [{"en": "Do you have anything [cheaper? / special?]", "zh": "你们有没有比较便宜的/特别的？"}]}, {"num": 5, "en": "I'll [take / buy] it.", "zh": "我就买下了。", "pairs": [{"en": "I'll [take / buy] it.", "zh": "我就买下了。"}]}, {"num": 6, "en": "Here's [the money. / the book.]", "zh": "钱在这里。 / 书在这儿。", "pairs": [{"en": "Here's [the money. / the book.]", "zh": "钱在这里。 / 书在这儿。"}]}, {"num": 7, "en": "Here you [are. / go.]", "zh": "拿去吧/在这儿。", "pairs": [{"en": "Here you [are. / go.]", "zh": "拿去吧/在这儿。"}]}], "exercises": []}, {"num": 13, "title_en": "At the Restaurant", "title_zh": "在餐厅", "type": "dialogue", "category": "日常高频情境口语", "tip": "西餐厅点餐：常用 'I'll have the steak, please.' 或 'Could I get the burger?'，结账时说 'Check, please.' 或 'Could we get the bill?'。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Do you have a table for two?", "zh": "你们有两个人坐的餐桌吗？"}, {"speaker": "B", "en": "Yes. In the smoking or non-smoking section?", "zh": "有的。您是要在吸烟区或非吸烟区？"}, {"speaker": "A", "en": "Non-smoking. please.", "zh": "麻烦在非吸烟区。"}, {"speaker": "B", "en": "OK. This way, please.", "zh": "好的。请跟我这边走。"}, {"speaker": "A", "en": "May I have the menu?", "zh": "可以给我菜单吗？"}, {"speaker": "B", "en": "Sure. Here you are.", "zh": "当然。在这儿。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I take your order now?", "zh": "我可以接受您的点菜了吗？"}, {"speaker": "B", "en": "Yes, please. I'll have the steak.", "zh": "是的，麻烦你。我要牛排。"}, {"speaker": "A", "en": "How would you like it?", "zh": "您的牛排要几分熟？"}, {"speaker": "B", "en": "Well-done, please.", "zh": "麻烦全熟。"}, {"speaker": "A", "en": "Would you like some dessert?", "zh": "您要不要来些甜点呢？"}, {"speaker": "B", "en": "No, thank you.", "zh": "不用了，谢谢。"}, {"speaker": "A", "en": "How about something to drink?", "zh": "那您要不要喝点什么呢？"}, {"speaker": "B", "en": "Hot coffee, please.", "zh": "麻烦热咖啡。"}]}], "reading": null, "vocab": [{"num": 1, "word": "restaurant", "phonetic": "[ˈrestarant]", "pos": "名", "meaning": "餐厅"}, {"num": 2, "word": "table", "phonetic": "[ˈtebl]", "pos": "名", "meaning": "桌"}, {"num": 3, "word": "smoking section", "phonetic": "[ˈsmokɪŋ]", "pos": "形", "meaning": "吸烟区；non-smoking section 非吸烟区,禁烟区"}, {"num": 4, "word": "or", "phonetic": "[ɔr]", "pos": "连", "meaning": "或，或者"}, {"num": 5, "word": "way", "phonetic": "[we]", "pos": "名", "meaning": "方向；路线"}, {"num": 6, "word": "menu", "phonetic": "[ˈmɛnju]", "pos": "名", "meaning": "菜单"}, {"num": 1, "word": "order", "phonetic": "[ˈɔrdɚ]", "pos": "名", "meaning": "&amp; 动 点（餐）"}, {"num": 2, "word": "steak", "phonetic": "[stek]", "pos": "名", "meaning": "牛排"}, {"num": 3, "word": "well-done", "phonetic": "[ˈwɛlˈdʌn]", "pos": "形", "meaning": "（食物） 煮透的，完全熟透的"}, {"num": 4, "word": "dessert", "phonetic": "[dɪˈzɝt]", "pos": "名", "meaning": "餐后甜点，点心"}, {"num": 5, "word": "something", "phonetic": "[ˈsʌmθɪŋ]", "pos": "代", "meaning": "某物；某事"}, {"num": 6, "word": "drink", "phonetic": "[drɪŋk]", "pos": "动", "meaning": "喝 &amp; 名 饮料"}, {"num": 7, "word": "coffee", "phonetic": "[ˈkɔfɪ]", "pos": "名", "meaning": "咖啡"}], "grammar": [{"num": 1, "title": "语法详解", "desc": ["本课主要介绍一些在餐厅用餐时常用的会话，希望读者能够熟悉这些用语。"], "formulas": [], "examples": []}, {"num": 1, "title": "Do you have a table for two?", "desc": ["= Do you have a table for two people?", "（你们有两个人坐的餐桌吗？）", "用电话预约餐桌时，则可使用下列句型：", "= Yes. I'd like to reserve a table for seven.", "（甲：哈哆，来来餐厅。我可以帮您什么忙吗？）", "（乙：是的，我想订一张七个人的餐桌。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Yes. ln the smoking or non-smoking section?", "desc": ["（有的。您是要在吸烟区或非吸烟区？）", "本句是由 &quot;Yes. Do you want a table in the smoking section or in the non-smoking section？&quot;简化而来的。", "目前在一般的公共场所都有划分吸烟区和非吸烟区， 这是因为现代人的健康意识高涨，而二手烟有害身体健康，故有此区别；而有些场所，像飞机上，车站内等甚至还有全面禁烟的规定。"], "formulas": [], "examples": []}, {"num": 3, "title": "This way, please.", "desc": ["（请跟我这边走。）", "本句原为&quot;Follow me (in) this way, please.，但因为经常使用，故简化为 &quot;This way, please.&quot;。", "follow ['fɑlo] 动跟随", "(in) this way 朝这边一般使用时，in this way 中的 in 经常可予以省略，而简化为 &quot;this way&quot;。", "会话"], "formulas": [], "examples": []}, {"num": 1, "title": "May I take your order now?", "desc": ["我可以接受您的点菜了吗？", "餐厅的服务人员欲要求用餐的客人点菜时，通常有下列说法：", "（我可以接受您的点菜了吗？）", "（先生/女士，您现在准备要点菜了吗？）", "（先生/女士，您现在想要点菜了吗？）", "上列第二个及第三个用法中的 sir 及 ma'am 分别表示“先生”“女士”，sir 是对男性的尊称，ma'am 则是对女性的尊称。", "（侍者：我可以接受您的点菜了吗？）", "（顾客：是的，麻烦你。请给我来份鸡肉饭。）", "（女侍者：先生/女士，您现在准备要点菜了吗？）", "（顾客：请再等我一下。）"], "formulas": [], "examples": []}, {"num": 2, "title": "How would you like it?", "desc": ["= How would you like your steak?", "（您的牛排要几分熟？）", "本句中的it 为代名词，代替上一句中已提过的名词 steak. 我们想询问某人的食物要如何调理时，可使用下列句型：", "How would you like your+食物名称?", "你的...（食物） 要如何调理？", "（牛排） 煎成中等嫩度的", "（肉） 半熟的，未完全煮熟的", "（乙：麻烦什么都不加（即纯咖啡）/只加糖/加奶精不要加糖/糖与奶精都要。）"], "formulas": [], "examples": []}, {"num": 3, "title": "No, thank you. 不用了，谢谢。", "desc": ["当有人询问你需不需要什么东西或任何帮忙、服务时，表示“要”与“不要”通常用下列说法来表示：", "表示“（需） 要”时：", "表示“不（需） 要”时：", "No, thank you. / No, thanks.（不用了，谢谢。）"], "formulas": [], "examples": []}, {"num": 4, "title": "How about something to drink?", "desc": ["= Would you like something to drink?", "（要不要喝点什么呢？）", "= Would you like a cup of tea?", "（要不要来杯茶呢？）", "= Would you like to go to a movie tonight?", "（今晚要不要去看场电影呀？）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Do you have a table for [two? / six?]", "zh": "你们有两个人/六个人坐的餐桌吗？", "pairs": [{"en": "Do you have a table for [two? / six?]", "zh": "你们有两个人/六个人坐的餐桌吗？"}]}, {"num": 2, "en": "May I have the [check? / bill?]", "zh": "可以给我账单吗？", "pairs": [{"en": "May I have the [check? / bill?]", "zh": "可以给我账单吗？"}]}, {"num": 3, "en": "[May I take your order now? / Are you ready to order now? / Would you like to order now?]", "zh": "我可以接受您的点菜了吗？ / 您现在准备要点菜了吗？ / 您现在想要点菜了吗？", "pairs": [{"en": "[May I take your order now? / Are you ready to order now? / Would you like to order now?]", "zh": "我可以接受您的点菜了吗？ / 您现在准备要点菜了吗？ / 您现在想要点菜了吗？"}]}, {"num": 4, "en": "How would you like your [steak? / eggs?]", "zh": "你的牛排要几分熟？ / 你的蛋要怎么煮？", "pairs": [{"en": "How would you like your [steak? / eggs?]", "zh": "你的牛排要几分熟？ / 你的蛋要怎么煮？"}]}, {"num": 5, "en": "How about [something to drink? / going on a picnic tomorrow?]", "zh": "要不要喝点什么呢？ / 明天去野餐怎么样呀？", "pairs": [{"en": "How about [something to drink? / going on a picnic tomorrow?]", "zh": "要不要喝点什么呢？ / 明天去野餐怎么样呀？"}]}], "exercises": []}, {"num": 14, "title_en": "At the Clothing Store", "title_zh": "在服装店", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I have a look at that jacket, please?", "zh": "请问我可以看一下那件夹克吗？"}, {"speaker": "B", "en": "what size do you wear?", "zh": "你穿几号的呢？"}, {"speaker": "A", "en": "Extra large.", "zh": "特大号的。"}, {"speaker": "B", "en": "Here you are.", "zh": "在这里。"}, {"speaker": "A", "en": "Can I try it on?", "zh": "我可以试穿吗？"}, {"speaker": "B", "en": "Sure. Go ahead.", "zh": "当然。请便。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "May I help you?", "zh": "我可以为你效劳吗？"}, {"speaker": "B", "en": "Yes, please. I'm looking for a necktie.", "zh": "是的，麻烦你，我正在找一条领带。"}, {"speaker": "A", "en": "Any special brand?", "zh": "要任何特别的品牌吗？"}, {"speaker": "B", "en": "No. Just something simple and not too expensive.", "zh": "不用。只要样式简单又不太贵就可以了。"}, {"speaker": "A", "en": "How about this one?", "zh": "这一条如何？"}, {"speaker": "B", "en": "That's fine. How much is it?", "zh": "可以。要多少钱呢？"}, {"speaker": "A", "en": "lt's only US $10 and it's on sale.", "zh": "只要10块美金，而且现在正在特价。"}, {"speaker": "B", "en": "OK. I'll take it. Thanks.", "zh": "好，我就把它买下了。谢谢。"}]}], "reading": null, "vocab": [{"num": 1, "word": "clothing", "phonetic": "[ˈkloon]", "pos": "名", "meaning": "衣服"}, {"num": 2, "word": "store", "phonetic": "[stor]", "pos": "名", "meaning": "商店"}, {"num": 3, "word": "have a look at……", "phonetic": "[lʊk]", "pos": "动", "meaning": "看一看/瞧一瞧……"}, {"num": 4, "word": "jacket", "phonetic": "[ˈdʒækɪt]", "pos": "名", "meaning": "夹克"}, {"num": 5, "word": "size", "phonetic": "[saɪz]", "pos": "名", "meaning": "尺寸；（东西的） 大小"}, {"num": 6, "word": "wear", "phonetic": "[wɛr]", "pos": "动", "meaning": "穿；戴"}, {"num": 7, "word": "extra large 特大（号） 的；extra", "phonetic": "[ˈɛkstrə]", "pos": "副", "meaning": "格外地，特别地；large [lɑrdʒ] 形 大的"}, {"num": 8, "word": "try…… on", "phonetic": "[traɪ]", "pos": "动", "meaning": "试穿/戴……（衣服、帽子等）"}, {"num": 1, "word": "necktie", "phonetic": "[ˈnɛk, taɪ]", "pos": "名", "meaning": "领带"}, {"num": 2, "word": "special", "phonetic": "[ˈspɛʃəl]", "pos": "形", "meaning": "特别的"}, {"num": 3, "word": "brand", "phonetic": "[brænd]", "pos": "名", "meaning": "品牌；厂牌"}, {"num": 4, "word": "simple", "phonetic": "[ˈsɪmpl]", "pos": "形", "meaning": "简单的"}, {"num": 5, "word": "on sale 减价售出，廉卖，打折；sale", "phonetic": "[sel]", "pos": "名", "meaning": "出售；贩卖"}], "grammar": [{"num": 1, "title": "clothing ['kloðɪŋ] 名 衣服（不可数名词）", "desc": ["clothing 是不可数名词，虽然中文说“一件衣服”、“两件衣服”...但英文却不能说 &quot;a clothing&quot;、&quot;two clothings&quot;...在英文中，上衣与裤子是分开的，此时表示上衣与裤子的名词才是可数名词。例如：", "上衣：", "jacket ['dʒækɪt] 夹克：a jacket （一件夹克）、two jackets （两件夹克）...", "coat [kot] 外套：a coat （一件外套）、two coats （两件外套）...", "shirt [ʃɝt] 衬衫：a shirt （一件衬衫）、two shirts （两件衬衫）...", "blouse [blaʊs] 女式衬衫/短上衣：a blouse （一件女衬衫）、two blouses （两件女衬衫）...", "裤子：", "由于裤子都有两条裤管，所以表示裤子的字都用复数形式，而表示“一条裤子”“两条裤子”...的单位则要用 &quot;a pair of&quot;、&quot;two pairs of&quot;...来表示。", "trousers ['traʊzɚz] 裤子：a pair of trousers （一条裤子）、two pairs of trousers （两条裤子）...", "pants [pænts] 裤子：a pair of pants （一条裤子）、two pairs of pants （两条裤子）...", "slacks [slæks] 休闲裤：a pair of slacks （一条休闲裤）、two pairs of slacks （两条休闲裤）...", "以上不管是上衣或裤子总称均称为 clothing，因为说 clothing 时搞不清楚是指上衣还是裤子，因此不说 a clothing，但我们可以说 some clothing （一些衣服）、a lot of clothing （很多衣服），因为 some 及 a lot of 都是可以用来修饰不可数名词的形容词。"], "formulas": [], "examples": []}, {"num": 2, "title": "clothes [kloz] 名 衣服（恒用复数）", "desc": ["clothes 也是“衣服”的意思，但和 clothing 不同的是，clothes 始终要用复数。且 clothes 亦是不可数名词，我们除了可说 some clothes, a lot of clothes 外，还可说 many clothes，因为 many 之后要接复数名词，所以 many clothes 是正确的，但我们不能说 many clothings，因为 clothing 无复数，但 clothing 可以用 much 来修饰。", "→ He has many clothes. (O)", "（他有很多衣服。）"], "formulas": [], "examples": []}, {"num": 3, "title": "cloth [klɔθ] 名 （不可数名词） 布", "desc": ["cloth （布） 也是不可数名词，“一块布”要说 &quot;a piece of cloth&quot;，&quot;some cloth&quot;、&quot;a lot of cloth&quot; 则表示“一些布”、“很多布”。", "“很多布”。"], "formulas": [], "examples": []}, {"num": 1, "title": "Can I have a look at that jacket, please?", "desc": ["（请问我可以看一下那件夹克吗？）", "我可不可以看一看...呢？"], "formulas": [], "examples": []}, {"num": 2, "title": "What size do you wear?", "desc": ["= What size jacket do you wear?", "（你穿几号的夹克？）", "（你穿几号鞋？）"], "formulas": [], "examples": []}, {"num": 3, "title": "extra large 特大号", "desc": ["一般衣服、裤子等的号码可分为 small （小号）、medium （中号）、large （大号） 及 extra large （特大号），这些号码通常是用大写的 &quot;S&quot;、&quot;M&quot;、&quot;L&quot; 及 &quot;XL&quot; 来表示。"], "formulas": [], "examples": []}, {"num": 4, "title": "Can I try it on?", "desc": ["（我可以试穿吗？）", "凡是身上的衣服、裤子、帽子等物件的“试穿”、“试戴”都可用 try on 来表示。", "= Can I try on this cap?", "（我可以试戴这顶帽子吗？）"], "formulas": [], "examples": []}, {"num": 5, "title": "go ahead 请便", "desc": ["go ahead 通常是用在同意让某人（自行） 做某事的情况中。"], "formulas": [], "examples": []}, {"num": 1, "title": "I'm looking for a necktie.", "desc": ["（我正在物色一条领带。）", "...正在..."], "formulas": [], "examples": []}, {"num": 2, "title": "Any special brand?", "desc": ["= Do you want any special brand?", "（你想要任何特别的品牌的吗？）", "本句是由 &quot;Do you want any special brand?&quot; 简化而来。其中的 brand 是名词，表示“厂牌”、“牌子”、“商标”的意思；brand-new 则是由 brand 衍生而来的形容词，表示“全新的”、“未用过的”之意，也是个常用的单词。", "Be careful with that car; it's brand-new!", "（请小心那辆车子；它是全新的！）"], "formulas": [], "examples": []}, {"num": 3, "title": "It's only US$ 10 and it's on sale.", "desc": ["（那只要10块美金，而且现在正在特价。）", "on sale 是指“减价售出”、“廉卖”或“打折”的意思，而 for sale 则是单纯指“出售”之意。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Can I [have / take] a look at that jacket, please?", "zh": "请问我可以看一下那件夹克吗？", "pairs": [{"en": "Can I [have / take] a look at that jacket, please?", "zh": "请问我可以看一下那件夹克吗？"}]}, {"num": 2, "en": "What size [shirt / pants] do you wear?", "zh": "你穿几号的衬衫/裤子？", "pairs": [{"en": "What size [shirt / pants] do you wear?", "zh": "你穿几号的衬衫/裤子？"}]}, {"num": 3, "en": "Can I [try it on? / try on the watch?]", "zh": "我可以试穿吗/试戴这只表吗？", "pairs": [{"en": "Can I [try it on? / try on the watch?]", "zh": "我可以试穿吗/试戴这只表吗？"}]}, {"num": 4, "en": "I'm looking for a [necktie. / wedding ring.]", "zh": "我正在物色一条领带/一枚结婚戒指。", "pairs": [{"en": "I'm looking for a [necktie. / wedding ring.]", "zh": "我正在物色一条领带/一枚结婚戒指。"}]}, {"num": 5, "en": "Any special [brand? / kind? / type?]", "zh": "要任何特别的品牌/种类/样式吗？", "pairs": [{"en": "Any special [brand? / kind? / type?]", "zh": "要任何特别的品牌/种类/样式吗？"}]}, {"num": 6, "en": "Just something [simple. / plain.]", "zh": "只要样式简单/朴素就可以了。", "pairs": [{"en": "Just something [simple. / plain.]", "zh": "只要样式简单/朴素就可以了。"}]}], "exercises": []}, {"num": 15, "title_en": "At the Department Store", "title_zh": "在百货公司", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I help you, please?", "zh": "能不能请你帮我一个忙呢？"}, {"speaker": "B", "en": "Sure. What can I do for you?", "zh": "当然。我能为你做什么？"}, {"speaker": "A", "en": "I'm looking for a gift for my son's birthday.", "zh": "我正在为我儿子物色一个生日礼物。"}, {"speaker": "B", "en": "How about this video game?", "zh": "这个电视游戏如何？"}, {"speaker": "A", "en": "That's a good idea. Can you gift-wrap it, please?", "zh": "那是个好主意。可以请你把它用礼品纸包装起来吗？"}, {"speaker": "B", "en": "Sure. No problem.", "zh": "当然。没问题。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me, ma'am. Do you have a blue dress my size?", "zh": "小姐，打扰一下。你这儿有合乎我尺寸的蓝色洋装吗？"}, {"speaker": "B", "en": "I think so. Let me take your measurements. OK. How about this dress over here?", "zh": "我想有的。让我量一下你的尺寸。好了，这边的这件洋装如何？"}, {"speaker": "A", "en": "Do you have a fitting room?", "zh": "你们有试衣间吗？"}, {"speaker": "B", "en": "It's in the corner over there.", "zh": "就在那边的角落里。"}, {"speaker": "A", "en": "Thank you.", "zh": "谢谢。"}, {"speaker": "B", "en": "You're welcome.", "zh": "不客气。"}]}], "reading": null, "vocab": [{"num": 1, "word": "department store 百货公司；department", "phonetic": "[dɪˈpɑrtmənt]", "pos": "名", "meaning": "（公司、政府等的） 部门"}, {"num": 2, "word": "gift", "phonetic": "[ɡɪft]", "pos": "名", "meaning": "礼物"}, {"num": 3, "word": "son", "phonetic": "[sʌn]", "pos": "名", "meaning": "儿子；daughter ['dɔtɚ] 名 女儿"}, {"num": 4, "word": "video game", "phonetic": "[ˈvɪdɪo ˈɡem]", "pos": "名", "meaning": "电视游戏，电玩"}, {"num": 5, "word": "idea", "phonetic": "[aɪˈdiə]", "pos": "名", "meaning": "主意；想法"}, {"num": 6, "word": "gift-wrap", "phonetic": "[ˈɡɪft, ræp]", "pos": "动", "meaning": "（用包装纸、缎带等把物品） 包装（成礼物）"}, {"num": 1, "word": "blue", "phonetic": "[blu]", "pos": "形", "meaning": "蓝色的"}, {"num": 2, "word": "dress", "phonetic": "[drɛs]", "pos": "名", "meaning": "洋装；服装"}, {"num": 3, "word": "think", "phonetic": "[θɪŋk]", "pos": "动", "meaning": "认为；想"}, {"num": 4, "word": "so", "phonetic": "[so]", "pos": "代", "meaning": "如此"}, {"num": 5, "word": "let", "phonetic": "[lɛt]", "pos": "动", "meaning": "让"}, {"num": 6, "word": "measurement", "phonetic": "[ˈmɛʒɚmənt]", "pos": "名", "meaning": "测量；尺寸，大小"}, {"num": 7, "word": "over here", "phonetic": "", "pos": "", "meaning": "在这里,在这边；over there 在那里,在那边"}, {"num": 8, "word": "fitting room 试衣间；fitting", "phonetic": "[ˈfɪtɪŋ]", "pos": "名", "meaning": "试衣，试穿"}, {"num": 9, "word": "corner", "phonetic": "[ˈkɔrnɚ]", "pos": "名", "meaning": "角落"}], "grammar": [{"num": 1, "title": "Can you help me, please?", "desc": ["= Can you do me a favor, please?", "= Can you give me a hand, please?", "（能不能请你帮我一个忙呢？）"], "formulas": [], "examples": []}, {"num": 2, "title": "I'm looking for a gift for my son's birthday.", "desc": ["（我正在为我儿子物色一样生日礼物。）", "表示“买/送东西给某人作为生日礼物”有下列说法：", "= I'm going to buy a necklace as my wife's birthday gift.", "（我要买一条项链给我太太作为生日礼物。）", "= I'll give my friend a book as her birthday gift.", "（我会送一本书给我朋友作为生日礼物。）"], "formulas": [], "examples": []}, {"num": 3, "title": "That's a good idea.", "desc": ["（那是个好主意。）", "在回应别人的提议、想法时，除了 &quot;That's a good idea.&quot; 外，尚有下列类似用法：", "因为口语中经常使用，因此常将主语 That 省略，而简化为："], "formulas": [], "examples": []}, {"num": 1, "title": "Excuse me, ma'am. Do you have a blue dress my size?", "desc": ["（小姐，打扰一下。你们有合乎我尺寸的蓝色洋装吗？）", "对男士的尊称则通常用 sir 一字。"], "formulas": [], "examples": []}, {"num": 2, "title": "I think so.", "desc": ["我想有的。", "上列句中的 so 是用来代替前面句中所提过的概念，表示“我认为如此”、“我也这么想”之意。", "因此本句的 &quot;I think so&quot; 即下列句子的简化：", "I think (that) we have a blue dress (in) your size.", "若要表示不同意对方的说法、想法或对某事不以为然时，则可用 &quot;I don't think so&quot; 表示。", "= I don't think we're going to be late.", "（甲：我们要迟到了吗？）", "（乙：我不这么认为。）"], "formulas": [], "examples": []}, {"num": 3, "title": "Let me take your measurements.", "desc": ["（让我量一下你的尺寸。）", "measurement 是指所量得的长度、高度、大小等；此处 &quot;take your measurements&quot; 中的 measurements 用复数，这是因为量身材时所量的部位不只一处（如：腰围、肩宽、手长等），因此要用复数。"], "formulas": [], "examples": []}, {"num": 4, "title": "How about this dress over here?", "desc": ["（在这里的这件洋装如何？）"], "formulas": [], "examples": []}, {"num": 5, "title": "It's in the corner over there.", "desc": ["（就在那边的角落里。）", "in the corner 在角落里", "on the corner 在转角处", "around the corner 在转角附近", "&quot;in the corner&quot; 指的是在空间内的角落，&quot;on the corner&quot; 是指空间外的转角处，&quot;around the corner&quot; 则指转角附近。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Can you [help me, / do me a favor, / give me a hand,] please?", "zh": "能不能请你帮我一个忙呢？", "pairs": [{"en": "Can you [help me, / do me a favor, / give me a hand,] please?", "zh": "能不能请你帮我一个忙呢？"}]}, {"num": 2, "en": "[That's / That sounds like / Sounds like] a good idea.", "zh": "那是个好主意/那听起来像是个好主意。", "pairs": [{"en": "[That's / That sounds like / Sounds like] a good idea.", "zh": "那是个好主意/那听起来像是个好主意。"}]}, {"num": 3, "en": "Do you have a blue dress [my size? / her size?]", "zh": "你们有合乎我/她尺寸的蓝色洋装吗？", "pairs": [{"en": "Do you have a blue dress [my size? / her size?]", "zh": "你们有合乎我/她尺寸的蓝色洋装吗？"}]}, {"num": 4, "en": "How about the dress over [here? / there?]", "zh": "在这/那里的蓝色洋装如何？", "pairs": [{"en": "How about the dress over [here? / there?]", "zh": "在这/那里的蓝色洋装如何？"}]}, {"num": 5, "en": "It's [in / at / around] the corner over there.", "zh": "就在那边的角落里/转角处/转角附近。", "pairs": [{"en": "It's [in / at / around] the corner over there.", "zh": "就在那边的角落里/转角处/转角附近。"}]}], "exercises": []}, {"num": 16, "title_en": "At the Shoe Store", "title_zh": "在鞋店", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Do you have these shoes in size 8?", "zh": "你们这些鞋有没有八号的？"}, {"speaker": "B", "en": "Sure. Here you are.", "zh": "当然。在这里。"}, {"speaker": "A", "en": "I'm sorry, but they are too small. Do you have a bigger pair?", "zh": "对不起，这双太小了。你们有比较大号的吗？"}, {"speaker": "B", "en": "Here. Try these on.", "zh": "这儿。试穿看看。"}, {"speaker": "A", "en": "Wow! These are just right.", "zh": "哇！这一双刚好。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me. Can you show me some high heeled shoes?", "zh": "打扰一下。你能不能拿一些高跟鞋给我看？"}, {"speaker": "B", "en": "Sure. This way, please.", "zh": "当然。请这边走。"}, {"speaker": "A", "en": "These are too high. Do you have lower ones?", "zh": "这些太高了。你们有低一点的吗？"}, {"speaker": "B", "en": "How about these?", "zh": "那这些如何？"}, {"speaker": "A", "en": "They don't fit. Do you have smaller ones?", "zh": "这些不合脚。你们有小一点的吗？"}, {"speaker": "B", "en": "I'm afraid we don't have your size.", "zh": "恐怕我们没有你的尺寸。"}, {"speaker": "A", "en": "what a shame!", "zh": "真可惜！"}]}], "reading": null, "vocab": [{"num": 1, "word": "shoe", "phonetic": "[juː]", "pos": "名", "meaning": "鞋子"}, {"num": 2, "word": "small", "phonetic": "[smol]", "pos": "形", "meaning": "小的"}, {"num": 3, "word": "bigger", "phonetic": "[ˈbiɡa]", "pos": "形", "meaning": "较大的（是big 的比较级） big[big]形大的"}, {"num": 4, "word": "pair", "phonetic": "[per]", "pos": "名", "meaning": "一双，一对，一副"}, {"num": 5, "word": "wow", "phonetic": "[wau]", "pos": "", "meaning": "哇！（表示惊奇、羡慕等）"}, {"num": 6, "word": "just", "phonetic": "[dʒʌst]", "pos": "副", "meaning": "正好，恰好"}, {"num": 7, "word": "right", "phonetic": "[raɪt]", "pos": "形", "meaning": "适当的，恰好的"}, {"num": 1, "word": "show", "phonetic": "[ʃo]", "pos": "动", "meaning": "指出，指给……看"}, {"num": 2, "word": "high-heeled", "phonetic": "[ˈhaɪˈhild]", "pos": "形", "meaning": "高跟的"}, {"num": 3, "word": "lower", "phonetic": "[ˈloɚ]", "pos": "形", "meaning": "较低/矮的（是 low 的比较级）；low [lo] 形 低的；矮的"}, {"num": 4, "word": "one", "phonetic": "[wʌn]", "pos": "代", "meaning": "用以代替单数的事物或人（ones 为复数）"}, {"num": 5, "word": "fit", "phonetic": "[fɪt]", "pos": "动", "meaning": "适合，合身"}, {"num": 6, "word": "smaller", "phonetic": "[ˈsmɔlɚ]", "pos": "形", "meaning": "较小的（是 small 的比较级）"}, {"num": 7, "word": "I'm afraid……", "phonetic": "[əˈfred]", "pos": "形", "meaning": "恐怕……"}], "grammar": [{"num": 1, "title": "Do you have these shoes in size 8?", "desc": ["（你们这些鞋有没有八号的？）", "你们有没有...（尺寸） 的...（东西） 呢？", "（顾客：你们这些袜子有没有九号的？）", "（店员：当然有。请这边走。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Do you have a bigger pair?", "desc": ["（你们有比较大号的吗？）", "pair 表示“一双、一对”，凡是成双或成对的物品，通常都要用 pair 这个字。例如：", "a pair of trousers / pants 一条裤子", "a pair of jeans 一条牛仔裤", "a pair of shorts 一条短裤", "a pair of glasses 一副眼镜（因为眼睛有两个，故有两个镜片，因此要用复数。）", "a pair of scissors 一把剪刀"], "formulas": [], "examples": []}, {"num": 3, "title": "Wow! These are just right.", "desc": ["（哇！这一双刚好。）", "wow 是感叹词，乃表示惊奇、羡慕等时所发出的声音；除了 wow 之外，还可以用 gee [dʒi] 或 gee-whiz ['dʒi 'hwɪz] 代替，不过 wow 通常用在好的方面，而 gee 或 gee-whiz 则好、坏方面都可使用。", "会话"], "formulas": [], "examples": []}, {"num": 1, "title": "Can you show me some high-heeled shoes?", "desc": ["= Can you show me some high-heels?", "（你能不能拿一些高跟鞋给我看？）", "在上述用法中，“人”之后亦可接“地方”形成下列用法："], "formulas": [], "examples": []}, {"num": 2, "title": "These are too high. Do you have lower ones?", "desc": ["（这些太高了。你们有低一点的吗？）", "上列第二个句子中的 ones 是代名词，用来代替前面已提过的名词 shoes。原句实为：", "These (= These high-heeled shoes) are too high. Do you have lower high-heeled shoes?", "但 high-heeled shoes 重复了一次，就修辞而言应予避免，故用 ones 代替。这个 ones 专用来代替前面已提过的复数名词，而 one 则是用来代替前面已提过的单数名词。", "→ Those mangos are delicious, especially the red ones.（佳）", "（那些芒果很好吃，尤其是红色的那些。）", "→ Jack wants a new bike, but he doesn't have enough money to buy one.（佳）", "（杰克想要一辆新的自行车，但他没有足够的钱买。）"], "formulas": [], "examples": []}, {"num": 3, "title": "They don't fit.", "desc": ["= They don't fit me.", "（这些不合脚。）", "fit 除了作不及物动词用，也可以在后面加“人”作宾语。"], "formulas": [], "examples": []}, {"num": 4, "title": "I'm afraid we don't have your size.", "desc": ["= I'm afraid that we don't have your size.", "（恐怕我们没有你的尺寸。）", "在上列句型中，that 可以省略，而直接在 I'm afraid 后面接另一个从句。", "这是一句要在给某人不愉快的讯息或消息时所用的婉转措词，表示“恐怕...”的意思。", "I'm afraid (that) I have some bad news for you.", "（恐怕我有不好的消息要给你。）", "I'm afraid (that) we don't have what you want.", "（恐怕我们没有你要的。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Do you have [these shoes in size 8? / this shirt in size 9?]", "zh": "你们这些鞋有没有8号的？ / 你们这件衬衫有没有9号的？", "pairs": [{"en": "Do you have [these shoes in size 8? / this shirt in size 9?]", "zh": "你们这些鞋有没有8号的？ / 你们这件衬衫有没有9号的？"}]}, {"num": 2, "en": "[Sure. / Of course.] Here you are.", "zh": "当然。在这里。", "pairs": [{"en": "[Sure. / Of course.] Here you are.", "zh": "当然。在这里。"}]}, {"num": 3, "en": "Do you have a [bigger / smaller] one?", "zh": "你们有比较大号/小号的吗？", "pairs": [{"en": "Do you have a [bigger / smaller] one?", "zh": "你们有比较大号/小号的吗？"}]}, {"num": 4, "en": "Can you show me some [high-heeled shoes? / sunglasses?]", "zh": "你能不能拿一些高跟鞋/太阳镜给我看？", "pairs": [{"en": "Can you show me some [high-heeled shoes? / sunglasses?]", "zh": "你能不能拿一些高跟鞋/太阳镜给我看？"}]}, {"num": 5, "en": "They [don't fit. / don't fit me. / aren't my size.]", "zh": "这些不合我的尺寸。", "pairs": [{"en": "They [don't fit. / don't fit me. / aren't my size.]", "zh": "这些不合我的尺寸。"}]}, {"num": 6, "en": "I'm afraid [we don't have your size. / I can't help you.]", "zh": "恐怕我们没有你的尺寸。 / 恐怕我无法帮你。", "pairs": [{"en": "I'm afraid [we don't have your size. / I can't help you.]", "zh": "恐怕我们没有你的尺寸。 / 恐怕我无法帮你。"}]}], "exercises": []}, {"num": 17, "title_en": "At the Bookstore", "title_zh": "在书店", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. Do you have A Tale of Two Cities?", "zh": "打扰一下。你们有《双城记》这本书吗？"}, {"speaker": "B", "en": "Who is the author?", "zh": "作者是谁？"}, {"speaker": "A", "en": "Charles Dickens.", "zh": "查尔斯·狄更斯。"}, {"speaker": "B", "en": "Sorry, we're sold out right now. Please come back next week.", "zh": "很抱歉，我们现在卖完了。请下个星期再来。"}, {"speaker": "A", "en": "OK. Thanks!", "zh": "好的。多谢！"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Do you have a good English-Chinese dictionary?", "zh": "你们有没有好的英汉词典？"}, {"speaker": "B", "en": "Sure. How about this one?", "zh": "当然有。这一本如何？"}, {"speaker": "A", "en": "Is this the latest edition?", "zh": "这是最新版本吗？"}, {"speaker": "B", "en": "Yes. We have both the paperback and the hardcover.", "zh": "是的。我们有平装本和精装本。"}, {"speaker": "A", "en": "What's the difference?", "zh": "有什么差别呢？"}, {"speaker": "B", "en": "The hardcover is more expensive.", "zh": "精装本比较贵。"}, {"speaker": "A", "en": "Oh! I see. I'll have the paperback, please.", "zh": "噢！我明白了。请给我平装本的。"}]}], "reading": null, "vocab": [{"num": 1, "word": "bookstore", "phonetic": "[ˈbukstor]", "pos": "名", "meaning": "书店"}, {"num": 2, "word": "A Tale of Two Cities", "phonetic": "[tel]", "pos": "名", "meaning": "《双城记》（书名）"}, {"num": 3, "word": "author", "phonetic": "[ˈɔθɚ]", "pos": "名", "meaning": "作者，作家"}, {"num": 4, "word": "Charles Dickens", "phonetic": "[ˈtʃɑrlz ˈdɪkɪnz]", "pos": "名", "meaning": "查尔斯·狄更斯（1812～1870，英国名小说家）"}, {"num": 5, "word": "be sold out", "phonetic": "[sold]", "pos": "动", "meaning": "全部卖/售完"}, {"num": 6, "word": "next week 下星期，下周；next", "phonetic": "[nɛkst]", "pos": "形", "meaning": "下一个的；week [wik] 名 一星期，一周"}, {"num": 7, "word": "come back 回来；come", "phonetic": "[kʌm]", "pos": "动", "meaning": "来（到）"}, {"num": 1, "word": "English-Chinese", "phonetic": "[ˈɪŋɡlɪʃˈtʃaɪˈniz]", "pos": "形", "meaning": "英汉的"}, {"num": 2, "word": "dictionary", "phonetic": "[ˈdɪkʃənɛri]", "pos": "名", "meaning": "词典"}, {"num": 3, "word": "latest", "phonetic": "[ˈletɪst]", "pos": "形", "meaning": "最新的；最近的（是 late 的最高级）；late [let] 形 迟的，晚的"}, {"num": 4, "word": "edition", "phonetic": "[ɪˈdɪʃən]", "pos": "名", "meaning": "版，版本"}, {"num": 5, "word": "both…… and……", "phonetic": "[boθ]", "pos": "连", "meaning": "既……且……；以及……"}, {"num": 6, "word": "paperback", "phonetic": "[ˈpepɚbæk]", "pos": "名", "meaning": "平装本/书"}, {"num": 7, "word": "hardcover", "phonetic": "[ˈhɑrd, kʌvɚ]", "pos": "名", "meaning": "精装本/书"}, {"num": 8, "word": "difference", "phonetic": "[ˈdɪfərəns]", "pos": "名", "meaning": "不同，差异"}], "grammar": [{"num": 1, "title": "Do you have A Tale of Two Cities?", "desc": ["（你们有《双城记》这本书吗？）", "（《做慢与偏见》是我最喜欢的小说。）", "（你知道《傲慢与偏见》的作者是谁吗？）"], "formulas": [], "examples": []}, {"num": 2, "title": "Sorry. We're sold out right now.", "desc": ["= I'm sorry. We're sold out right now.", "= I'm sorry, but we're sold out right now.", "（很抱歉，我们现在卖完了。）", "上列句中的 &quot;Sorry.&quot; 是 &quot;I'm sorry.&quot; 的简化；在口语中，经常可以使用 &quot;Sorry!&quot; 一个字来代替 &quot;I'm sorry&quot;。例如：", "= I'm sorry. I can't go to your party tonight.", "= Sorry. I can't go to your party tonight.", "（很抱歉，今晚我无法去参加你的派对。）"], "formulas": [], "examples": []}, {"num": 3, "title": "We're sold out right now.", "desc": ["（我们现在卖完了。）", "&quot;We're sold out&quot; 是常见的用法，意思是“我们卖完了”，其中的 sold out 视作形容词，表示“卖完/光的”。", "表示“我们已将某东西卖完了”有下列两种用法：", "上述用法是 &quot;sell out of...&quot; 的现在完成式，也就是", "&quot;have + sold out of + 宾语”，其中的 have 称为现在完成式助动词，译成“已经”；此种现在完成式的句型如下：", "他将会离开。", "→He will leave.", "他已经离开了。", "→He has left.（left[left]是leave[liv] 的过去分词）", "他们将会去美国。", "→ They will go to the States.", "他们已经去美国了。", "→They have gone to the States.", "（gone[gon]是go 的过去分词）"], "formulas": [], "examples": []}, {"num": 4, "title": "Please come back next week.", "desc": ["（请下个星期再来。）", "nexweek 是“下个星期”的意思；同理，表示“下（一） 个", "...（时间）”我们通常都可用“next+时间名词”来表示。例如：", "next month 下个月 next year 明年 next Sunday 下个星期日：：", "next Saturday 下个星期六"], "formulas": [], "examples": []}, {"num": 1, "title": "Do you have a good English-Chinese dictionary?", "desc": ["（你们有没有好的英汉词典？）", "“汉英词典”的说法为 &quot;Chinese-English dictionary&quot;，“英英词典”的说法则为 &quot;English-English dictionary&quot;；读者要知道的是，我们在念这种中间有连字号（即“-”） 的词时，只要把两旁的英文词念出来就可以了，而不用把连字号的英文 &quot;hyphen [ˈhaɪfən]&quot; 也说出来。例如 English-Chinese 的念法为 [ˌɪŋglɪʃ 'tʃaɪniz]，而不是 [ˌɪŋglɪʃ ˈhaɪfən 'tʃaɪniz]。", "我们在学英文时，一定时常会碰到单词或不懂的用法，这个时候我们就要去查词典，这“查词典”的英文就可以说 &quot;consult the dictionary&quot;；如果是“在词典里查单词”，这时就要用 &quot;look up the word in the dictionary&quot;。也就是说，“查词典”的动词要用 consult，“查单词”的动词要用 look up，可不要说成 &quot;look up the dictionary&quot;。"], "formulas": [], "examples": []}, {"num": 2, "title": "Is this the latest edition?", "desc": ["（这是最新版本吗？）", "以上第一句中的 latest 为形容词 late 的最高级，与定冠词 the 并用；第二句中的 more expensive 则为形容词 expensive 的比较级。我们在 Lesson 12 中已提过形容词的比较级变化，在本课中我们将再做一些复习及补充说明，并介绍形容词的最高级变化，兹说明如下：", "不管是在中文或英文中均有原级、比较级和最高级的用语，例如：", "中文：她很漂亮。（“漂亮”是原级）", "英文：She is beautiful.（beautiful 是原级）", "中文：我比她更漂亮。（“更漂亮”是“漂亮”的比较级）", "英文: I am more beautiful than she.", "中文：她是我们班上最漂亮的女孩。（“最漂亮”是“漂亮”的最高级）", "英文: She is the most beautiful girl in our class.", "一般而言，形容词的比较级和最高级变化有下列原则：", "比较级：more + 原级；最高级：most + 原级", "比较级：原级 + -er；最高级：原级 + -est", "比较级：重复该辅音字母 + -er；最高级：重复该辅音字母 + -est", "比较级：原级 + -r；最高级：原级 + -st", "比较级：将 y 改成 i + -er；最高级：将 y 改成 i + -est", "以上的比较级和最高级变化称做规则变化。但亦有些形容词则呈不规则变化，如：", "所幸这些不规则变化的形容词并不多，只要读者多阅读英文文章，见到一个就记一个，自然就会熟悉这些不规则变化的形容词。", "形容词的最高级要与定冠词the 并用。", "（约翰是他班上最好的学生。）"], "formulas": [], "examples": []}, {"num": 3, "title": "We have both the paperback and the hardcover.", "desc": ["= We have both the paperback dictionaries and the hardcover dictionaries.", "（我们有平装本和精装本。）", "使用。"], "formulas": [], "examples": []}, {"num": 4, "title": "what's the difference?", "desc": ["= What's the difference between the paperback and the hardcover?", "（平装本和精装本之间有什么差别呢？）", "the difference between A and B与B之间的差别/不同"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Who is the [author? / writer?]", "zh": "作者是谁？", "pairs": [{"en": "Who is the [author? / writer?]", "zh": "作者是谁？"}]}, {"num": 2, "en": "Please come back [next week. / next Friday. / next month.]", "zh": "请下个星期/下个星期五/下个月再来。", "pairs": [{"en": "Please come back [next week. / next Friday. / next month.]", "zh": "请下个星期/下个星期五/下个月再来。"}]}, {"num": 3, "en": "Do you have a good [English-Chinese / Chinese-English / English-English] dictionary?", "zh": "你们有没有好的英汉/汉英/英英词典？", "pairs": [{"en": "Do you have a good [English-Chinese / Chinese-English / English-English] dictionary?", "zh": "你们有没有好的英汉/汉英/英英词典？"}]}, {"num": 4, "en": "[We have both the paperback and the hardcover. / I like both jazz and rock'n'roll. / Both he and I are students.]", "zh": "我们有平装本和精装本。 / 我喜欢爵士乐以及摇滚乐。 / 他和我都是学生。", "pairs": [{"en": "[We have both the paperback and the hardcover. / I like both jazz and rock'n'roll. / Both he and I are students.]", "zh": "我们有平装本和精装本。 / 我喜欢爵士乐以及摇滚乐。 / 他和我都是学生。"}]}, {"num": 5, "en": "[The hardcover is more expensive. / Lily is more beautiful than Helen. / David is taller than Tom.]", "zh": "精装本比较贵。 / 莉莉比海伦更漂亮。 / 大伟比汤姆高。", "pairs": [{"en": "[The hardcover is more expensive. / Lily is more beautiful than Helen. / David is taller than Tom.]", "zh": "精装本比较贵。 / 莉莉比海伦更漂亮。 / 大伟比汤姆高。"}]}], "exercises": []}, {"num": 18, "title_en": "Taking a Taxi", "title_zh": "搭出租车", "type": "dialogue", "category": "日常高频情境口语", "tip": "搭乘出租车或打车软件：上车直接说 'To the airport, please.' 或 'Could you drop me off at...?'（可以在...让我下车吗）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Where to, ma'am?", "zh": "小姐，你要到哪里去？"}, {"speaker": "B", "en": "The train station, please.", "zh": "麻烦到火车站。"}, {"speaker": "A", "en": "Here we are, ma'am.", "zh": "（抵达后） 小姐，到了。"}, {"speaker": "B", "en": "How much do I owe you?", "zh": "要给你多少钱？"}, {"speaker": "A", "en": "It's 135 Yuan on the meter,", "zh": "里程表上是135元。"}, {"speaker": "B", "en": "Here's 150 Yuan, keep the change.", "zh": "这里是150元钱。零钱不用找了。"}, {"speaker": "A", "en": "Thanks!", "zh": "多谢！"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "To the airport, please.", "zh": "麻烦到机场。"}, {"speaker": "B", "en": "The international or domestic one?", "zh": "国际机场还是国内机场？"}, {"speaker": "A", "en": "The international airport.", "zh": "国际机场。"}, {"speaker": "B", "en": "Got it!", "zh": "知道了。"}, {"speaker": "A", "en": "Could you speed up, please? I don't want to miss my flight.", "zh": "麻烦能请你开快一点吗？我不想误了我的班机。"}, {"speaker": "B", "en": "What time's your flight?", "zh": "你的班机是几点？"}, {"speaker": "A", "en": "10:45 pm.", "zh": "晚上10点45分。"}, {"speaker": "B", "en": "Don't worry! I'll get you there in time.", "zh": "别担心！我会及时把你送到那儿去。"}]}], "reading": null, "vocab": [{"num": 1, "word": "take a taxi", "phonetic": "[tek]", "pos": "动", "meaning": "搭出租车"}, {"num": 2, "word": "train station", "phonetic": "[tren]", "pos": "名", "meaning": "火车站"}, {"num": 3, "word": "arrive", "phonetic": "[əˈraɪv]", "pos": "动", "meaning": "抵达，到达"}, {"num": 4, "word": "Here we are.", "phonetic": "", "pos": "", "meaning": "（我们） 到了（目的地）。"}, {"num": 5, "word": "owe", "phonetic": "[o]", "pos": "动", "meaning": "欠（债）"}, {"num": 6, "word": "meter", "phonetic": "[ˈmitɚ]", "pos": "名", "meaning": "里程表；计量器"}, {"num": 7, "word": "keep the change", "phonetic": "[kip]", "pos": "动", "meaning": "（零钱） 不用找了"}, {"num": 1, "word": "airport", "phonetic": "[ˈɛrport]", "pos": "名", "meaning": "机场"}, {"num": 2, "word": "international", "phonetic": "[ˌɪntɚˈnæʃənl]", "pos": "形", "meaning": "国际（间） 的"}, {"num": 3, "word": "domestic", "phonetic": "[dəˈmɛstɪk]", "pos": "形", "meaning": "国内的，本国的"}, {"num": 4, "word": "Got it!", "phonetic": "", "pos": "", "meaning": "了解/知道/明白了!（= I've got it!）"}, {"num": 5, "word": "speed up 加快速度；speed", "phonetic": "[spid]", "pos": "动", "meaning": "加速，增速"}, {"num": 6, "word": "want", "phonetic": "[wɑnt]", "pos": "动", "meaning": "想要"}, {"num": 7, "word": "miss", "phonetic": "[mɪs]", "pos": "动", "meaning": "错过，未赶上"}, {"num": 8, "word": "flight", "phonetic": "[flaɪt]", "pos": "名", "meaning": "（飞机的） 飞行班次，班机"}, {"num": 9, "word": "worry", "phonetic": "[ˈwɝi]", "pos": "动", "meaning": "担心，忧虑"}, {"num": 10, "word": "in time", "phonetic": "", "pos": "", "meaning": "及时,来得及"}], "grammar": [{"num": 1, "title": "我们一般要表示“搭乘”某种交通工具时，动词通常用 take 来表示，此时在该交通工具前要置不定完词a/an 或定词the，如：", "desc": ["take the/a taxi 搭出租车", "take the/a bus 搭公交车", "take the/a train 搭火车", "take the/an airplane 搭飞机", "take the/a ship/boat 搭船", "（我必须搭船才能到那座岛上。）"], "formulas": [], "examples": []}, {"num": 2, "title": "除了用动词take 来表示“搭乘”某种交通工具外，尚可用“介词by+交通工具”来表示，但此时该交通工具前不可置任何冠词（a, an, the）, 如：by taxi （搭出租车）、by bus （搭公交车）、by train （搭火车）、by ship/boat （搭船）、 因此上列第一句及第二句亦可写成：", "desc": ["Jimmy goes to school by bus every day.："], "formulas": [], "examples": []}, {"num": 3, "title": "若要表示“步行”时，则可以用 &quot;on foot&quot;。", "desc": ["'.: The only way to get to the village is on foot.", "（到那个村庄去的惟一途径是步行。）", "全话："], "formulas": [], "examples": []}, {"num": 1, "title": "where to，ma'am？小姐，你要到哪里去？", "desc": ["= where are you going, ma'am?", "这是一般乘客上了出租车后，司机询问乘客要到哪里去的问句；直接说 &quot;Where to, ma'am / sir?&quot;（小姐/先生，你要到哪里去？）", "是较简化的口语用法，但 Where to 实由 Where are you going? 简化而来，因为经常使用而变成了习惯语。", "（出租车司机：先生，你要到哪里去？）", "（乘客：麻烦到国立故宫博物院。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Here we are, ma'am. 小姐, 我们到 了。", "desc": ["以下是一些有关here 及there 起首的习惯用语，这些都是很常用的句子，希望读者能熟悉这些用法：", "a:Here we are．（我们） 到了。", "某甲要去见某女生，但胆小如鼠，于是便请某乙陪他一块去。两人乘了一部出租车，到了该女生家门口时，某甲、某乙以及出租车司机都可说这句话：”", "= There you go.", "某甲到麦当劳买汉堡，服务小姐叫他稍候片刻。不久，服务小姐就把汉堡递给某甲，同时说了一句：", "&quot;Here you go&quot;；所以我们知道，给任何人所要的东西时，均可使用 &quot;Here you are.&quot;、&quot;Here you go&quot; 及 &quot;There you go.&quot;。", "在那里/原来你在这儿。", "4710:", "你又来（这一套） 了/你老毛病又犯了。", "孵说：", "小强很不喜欢上学，所以经常编借口找理由不去学校；在一个寒流来袭的冬天早上，小强告诉妈妈说他牙齿痛无法去上课，由于这个理由小强上个礼拜已经用过了，于是妈妈就对小强说道：", "&quot;There you go again.&quot;（你又来了。），然后还是押着小强去上学。"], "formulas": [], "examples": []}, {"num": 3, "title": "How much do I owe you? 我要给你多少钱？", "desc": ["owe 是动词，表示“欠（债）”的意思，此处乘客问欠司机多少钱，也就是在问要给司机多少车钱的意思。", "有关 owe 的用法句型如下："], "formulas": [], "examples": []}, {"num": 4, "title": "Keep the change. 零钱不用找了。", "desc": ["我们下出租车要给司机车费，或是去买东西给钱时，要把剩下找的零钱给对方当小费时，就可以用 &quot;Keep the change.&quot;。", "（店员：麻烦总共要90元。）", "（顾客：这儿是100元。不用找了。）"], "formulas": [], "examples": []}, {"num": 1, "title": "To the airport, please.", "desc": ["麻烦到机场。", "= Take me to the airport, please.", "表示“（用车） 载某人到某地”可用下列句型："], "formulas": [], "examples": []}, {"num": 2, "title": "The international or domestic one?", "desc": ["= Do you want me to take you to the international airport or the domestic airport?", "（你要我载你到国际机场还是国内机场？）", "本句中的 one 用来代替前一句中 airport；我们在 Lesson 16 会话 B 中，已提过用 one 及 ones 代替前面已提过的单数名词和复数名词之用法，这里仅再提供例句供读者参考。"], "formulas": [], "examples": []}, {"num": 3, "title": "Got it!", "desc": ["知道了！", "&quot;Got it!&quot; 是极口语的用法，表示“知道了！”、“我明白了！”或“我了解了！”的意思，也就等于 &quot;I see.&quot; 或 &quot;I understand!&quot;。"], "formulas": [], "examples": []}, {"num": 4, "title": "could you speed up, please?", "desc": ["麻烦能请你开快一点吗？", "speedup 是“加速”的意思，其相反词是slowdown （慢下来），这两个短语也是常见的用法。"], "formulas": [], "examples": []}, {"num": 5, "title": "I don't want to miss my flight.", "desc": ["（我不想误了我的班机。）"], "formulas": [], "examples": []}, {"num": 6, "title": "Don't worry! 别担心!", "desc": [], "formulas": [], "examples": []}, {"num": 7, "title": "I'll get you there in time.", "desc": ["= I'll get you to the airport in time.", "（我会及时把你送到那儿去。）", "in time 及时", "on time 准时", "in time 表示“及时”，是指在预定时间前一、两分钟；而 on time 则是“准时”或“按时”，指刚刚好在预定时间。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Let's take a [taxi / bus] to the restaurant. (= Let's go to the restaurant by [taxi. / bus.])", "zh": "咱们搭出租车/公交车到那家餐厅去吧。", "pairs": [{"en": "Let's take a [taxi / bus] to the restaurant. (= Let's go to the restaurant by [taxi. / bus.])", "zh": "咱们搭出租车/公交车到那家餐厅去吧。"}]}, {"num": 2, "en": "We will go to the States by [plane / ship] tomorrow.", "zh": "我们明天要搭飞机/坐船去美国。", "pairs": [{"en": "We will go to the States by [plane / ship] tomorrow.", "zh": "我们明天要搭飞机/坐船去美国。"}]}, {"num": 3, "en": "[Where to, / Where are you going,] ma'am?", "zh": "小姐，你要到哪里去？", "pairs": [{"en": "[Where to, / Where are you going,] ma'am?", "zh": "小姐，你要到哪里去？"}]}, {"num": 4, "en": "To the [airport, / train station,] please.", "zh": "麻烦到机场/火车站。", "pairs": [{"en": "To the [airport, / train station,] please.", "zh": "麻烦到机场/火车站。"}]}, {"num": 5, "en": "Could you [speed up, / slow down,] please?", "zh": "麻烦能请你开快/慢一点吗？", "pairs": [{"en": "Could you [speed up, / slow down,] please?", "zh": "麻烦能请你开快/慢一点吗？"}]}, {"num": 6, "en": "I don't want to miss my [flight. / train.]", "zh": "我不想误了我的班机/火车。", "pairs": [{"en": "I don't want to miss my [flight. / train.]", "zh": "我不想误了我的班机/火车。"}]}], "exercises": []}, {"num": 19, "title_en": "Booking a Room", "title_zh": "订房间", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Excuse me. Do you have a single room?", "zh": "请问一下，你们有单人房吗？"}, {"speaker": "B", "en": "Sorry. We're fully booked. The only room available at the moment is a twin room.", "zh": "很抱歉，我们全订满了。目前惟一的空房是双人房。"}, {"speaker": "A", "en": "OK. I'll take it.", "zh": "好，我就要双人房。"}, {"speaker": "B", "en": "May I have your name, please?", "zh": "请问尊姓大名？"}, {"speaker": "A", "en": "I'm John Li.", "zh": "我是李约翰。"}, {"speaker": "B", "en": "How many days do you want to stay?", "zh": "您想要住几天呢？"}, {"speaker": "A", "en": "Five days.", "zh": "五天。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me. My name is Jack Wu. I'd like to book a room.", "zh": "麻烦你，我的名字是吴杰克，我想要订房间。"}, {"speaker": "B", "en": "Single or double?", "zh": "您要单人房还是双人房？"}, {"speaker": "A", "en": "what are the rates?", "zh": "房价怎么算？"}, {"speaker": "B", "en": "l It's US $100 for a single and Us $150 for a double.", "zh": "单人房是100块美金，而双人房是150块美金。"}, {"speaker": "A", "en": "I'll take a single for 3 days.", "zh": "我要一间单人房的，住三天。"}, {"speaker": "B", "en": "OK. Just come to the front desk at the lobby.", "zh": "好。请到大厅的柜台来就行了。"}, {"speaker": "A", "en": "Ok. I'll arrive tomorrow.", "zh": "好的。我明天到。"}, {"speaker": "B", "en": "See you then.", "zh": "到时候见。"}]}], "reading": null, "vocab": [{"num": 1, "word": "book", "phonetic": "[bʊk]", "pos": "动", "meaning": "预订（座位、房间等）"}, {"num": 2, "word": "single", "phonetic": "[ˈsɪŋɡl]", "pos": "形", "meaning": "单一的，单人用的；single room 单人房"}, {"num": 3, "word": "fully", "phonetic": "[ˈfʊlɪ]", "pos": "副", "meaning": "完全地；充分地"}, {"num": 4, "word": "available", "phonetic": "[əˈveləbl]", "pos": "形", "meaning": "可用的，可获得的；有空的"}, {"num": 5, "word": "twin", "phonetic": "[twɪn]", "pos": "形", "meaning": "成对的；双胞胎的 &amp; 名 双胞胎（之一）；twin room （有两张单人床的） 双人房"}, {"num": 6, "word": "How many +", "phonetic": "", "pos": "", "meaning": "复数名词? 多少……?"}, {"num": 7, "word": "many", "phonetic": "[ˈmɛnɪ]", "pos": "形", "meaning": "很多的，许多的"}, {"num": 7, "word": "stay", "phonetic": "[ste]", "pos": "动", "meaning": "留，停留，逗留"}, {"num": 1, "word": "double", "phonetic": "[ˈdʌbl]", "pos": "形", "meaning": "双人的，双的；两倍"}, {"num": 2, "word": "rate", "phonetic": "[ret]", "pos": "名", "meaning": "价格，费用"}, {"num": 3, "word": "lobby", "phonetic": "[ˈlɑbɪ]", "pos": "名", "meaning": "（公共场所出入口处的） 大厅"}, {"num": 4, "word": "arrive", "phonetic": "[əˈraɪv]", "pos": "动", "meaning": "到达，抵达"}, {"num": 5, "word": "See you then.", "phonetic": "[ðɛn]", "pos": "副", "meaning": "到时候见。"}], "grammar": [{"num": 1, "title": "我们要“预订”旅馆房间、飞机票、餐厅座位或门票等时，都可以用 book 来表示。", "desc": ["但 book 亦可作名词，表示“书本”的意思。"], "formulas": [], "examples": []}, {"num": 2, "title": "表示“预订”“预约”“订票”等除了用 book 外，还可以用 reserve 或 make a reservation 来表示，因此上列例句亦可写成：", "desc": ["= I am going to make a reservation for a suite at the hotel in Tokyo.", "= I will make a reservation for two seats for tonight's concert.", "在这三种用法中，以 book 较为口语，也最常用。"], "formulas": [], "examples": []}, {"num": 1, "title": "Do you have a single room?", "desc": ["（你们有单人房吗？）", "旅馆或饭店的房间通常分为下列数种："], "formulas": [], "examples": []}, {"num": 2, "title": "Sorry, we're fully booked.", "desc": ["（很抱歉，我们全订满了。）", "fully booked 是很常见的用法，表示旅馆房间、座位、餐桌、门票等已全被预订完了时，就可用 fully booked。其中 fully 是副词，表示“完完全全地”，booked 作形容词，表示“预订的”。"], "formulas": [], "examples": []}, {"num": 3, "title": "The only room available at the moment is a twin room.", "desc": ["（目前惟一的空房是双人房。）", "一般的形容词修饰名词时，多置于该名词的前面。", "但在英文中，有少数形容词修饰名词时，形容词要放在该名词之后，而不可置于其前，如本句的 available 就是属于这类的形容词，因此我们不能说：", "→ The only doctor available in the hospital does not have much experience. (O)", "（这家医院惟一有空的一位医生没什么经验。）"], "formulas": [], "examples": []}, {"num": 4, "title": "How many days do you want to stay?", "desc": ["（您想要住几天呢？）", "在中文里，虽然我们会说“住”旅馆，但在英文中却不用live 这个字，而要用stay （停留、待），因为使用live 时，是指长期居住在某个地方，把那个地方当做家一样，而住在旅馆只是短期的行为，所以要用stay 这个字。因此本问句不可说成：", "E.: I have lived in Taipei for three years.", "（我已经在台北住了三年了。）", "（我去纽约时会住在那家旅馆。）", "同理，如果你这个周末要待在朋友家里过夜时， 也要用stay，但如果你是和朋友住在一起的话，那就可以用live。", "This weekend I'm going to stay (over) at a friend's house.", "（这个周末我要待在朋友家过夜。）", "apartment[a'partment ]名公寓"], "formulas": [], "examples": []}, {"num": 1, "title": "Single or double?", "desc": ["= Do you want to book a single or a double room?", "（你想要订单人房还是双人房？）"], "formulas": [], "examples": []}, {"num": 2, "title": "What are the rates?", "desc": ["= What are the charges?", "（房价怎么算？）", "rate 及 charge [tʃɑrdʒ] 是指“价格”、“费用”，使用时一般都用复数 rates 及 charges，住旅馆或请人当家教时都可使用。", "（你到学生家里去当家教的费用怎么算？）", "at the rate of... 以...的速度/率"], "formulas": [], "examples": []}, {"num": 3, "title": "It's US $100 for a single and US $150 for a double.", "desc": ["= It's US $100 for a single room and US $150 for a double room.", "（单人房是100美元，而双人房是150美元。）", "上列句中，US $100 （100美元） 的念法为 &quot;one hundred US dollars&quot;，而不是 &quot;US dollars one hundred&quot;；同理，US $150 的念法为 &quot;one hundred fifty US dollars&quot;，而非 &quot;US dollars one hundred fifty&quot;。", "有关于表示“金钱”的写法，除了把货币名称置于数字", "前面外，还可以把数字写在前面，这时代表钱的符号", "US $150 = 150 US (dollars)", "US $100 = 100 US (dollars)"], "formulas": [], "examples": []}, {"num": 4, "title": "See you then. 到时候见。", "desc": ["= See you at that time.", "= See you when you arrive.", "我们常听到的道别用语有 &quot;See you.&quot; 及 &quot;See you later.&quot;；但如果有约定时间再见面时，这时我们就可以在 &quot;See you&quot; 后面加上 then （到那时），形成 &quot;See you then.&quot;。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Do you have a [single room? / twin room? / double room? / suite?]", "zh": "你们有单人房/两张单人床的双人房/一张双人床的双人房/套房吗？", "pairs": [{"en": "Do you have a [single room? / twin room? / double room? / suite?]", "zh": "你们有单人房/两张单人床的双人房/一张双人床的双人房/套房吗？"}]}, {"num": 2, "en": "[How many days / How long] do you want to stay?", "zh": "你要住几天呢？ / 你要住多久呢？", "pairs": [{"en": "[How many days / How long] do you want to stay?", "zh": "你要住几天呢？ / 你要住多久呢？"}]}, {"num": 3, "en": "I'd like to book [a room. / two tickets to Taipei. / a table for twelve.]", "zh": "我想要订房间。 / 我想订两张到台北的票。 / 我想订一张12个人坐的餐桌。", "pairs": [{"en": "I'd like to book [a room. / two tickets to Taipei. / a table for twelve.]", "zh": "我想要订房间。 / 我想订两张到台北的票。 / 我想订一张12个人坐的餐桌。"}]}, {"num": 4, "en": "See you [then. / at that time.]", "zh": "到时候见。", "pairs": [{"en": "See you [then. / at that time.]", "zh": "到时候见。"}]}], "exercises": []}, {"num": 20, "title_en": "Checking into a Hotel", "title_zh": "办理住宿手续", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Good morning. I'm Mr. Jack Wu. I have a reservation for a suite.", "zh": "早安。我是吴杰克。我订了一间套房。"}, {"speaker": "B", "en": "Oh, yes, Mr. Wu. Please fill out this form.", "zh": "哦，有的，吴先生。请填一下这张表格。"}, {"speaker": "A", "en": "Here you are.", "zh": "拿去吧。"}, {"speaker": "B", "en": "will you pay by cash or charge?", "zh": "您要付现金还是刷卡？"}, {"speaker": "A", "en": "Do you take traveler's checks?", "zh": "你们收旅行支票吗？"}, {"speaker": "B", "en": "Certainly.", "zh": "当然收。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Excuse me. I'd like to check in, please. My name is Jack Wu.", "zh": "打扰一下，我想办理住宿手续，我是吴杰克。"}, {"speaker": "B", "en": "One moment, please. Oh, yes. You have a reservation for a single room, right?", "zh": "请稍等一下。哦，有的。你订了一间单人房，对不对？"}, {"speaker": "A", "en": "That's right.", "zh": "没错。"}, {"speaker": "B", "en": "May I have a look at your passport?", "zh": "我可以看一下您的护照吗？"}, {"speaker": "A", "en": "Here you go.", "zh": "拿去吧。"}, {"speaker": "B", "en": "OK. You're booked in Room 609. Do you have any luggage?", "zh": "好了。您预订的是609号房。您有行李吗？"}, {"speaker": "A", "en": "Yes. These two suitcases.", "zh": "有的。就这两个手提箱。"}, {"speaker": "B", "en": "No problem. The bellboy will take them and show you to your room.", "zh": "没问题。服务生会拿行李并带您到房间去。"}]}], "reading": null, "vocab": [{"num": 1, "word": "check into a hotel 在旅馆办理住宿手续；hotel", "phonetic": "[hoˈtɛl]", "pos": "名", "meaning": "旅馆，饭店"}, {"num": 2, "word": "reservation", "phonetic": "[ˌrɛzɚˈveʃən]", "pos": "名", "meaning": "（旅馆房间、座位等的） 预订"}, {"num": 3, "word": "suite", "phonetic": "[swit]", "pos": "名", "meaning": "套房"}, {"num": 4, "word": "fill out…… 填写……（文件、表格等）；fill", "phonetic": "[fɪl]", "pos": "动", "meaning": "填满；填补"}, {"num": 5, "word": "form", "phonetic": "[fɔrm]", "pos": "名", "meaning": "表格"}, {"num": 6, "word": "pay by cash 用现金支付，付现金；pay", "phonetic": "[peɪ]", "pos": "动", "meaning": "付(钱)；cash [kæʃ] 名 现金"}, {"num": 7, "word": "charge", "phonetic": "[tʃɑːrdʒ]", "pos": "名", "meaning": "记账；收费"}, {"num": 8, "word": "traveler's check 旅行支票；traveler", "phonetic": "[ˈtrævəlɚ]", "pos": "名", "meaning": "旅行者，旅人；check [tʃɛk] 名 支票"}, {"num": 9, "word": "certainly", "phonetic": "[ˈsɝtnli]", "pos": "副", "meaning": "当然，一定，的确"}, {"num": 1, "word": "check in", "phonetic": "", "pos": "", "meaning": "（在旅馆） 登记办理住宿手续；check out （在旅馆） 办理退房手续"}, {"num": 2, "word": "One moment, please.", "phonetic": "", "pos": "", "meaning": "请稍候。"}, {"num": 3, "word": "passport", "phonetic": "[ˈpæsport]", "pos": "名", "meaning": "护照"}, {"num": 4, "word": "Here you go.", "phonetic": "", "pos": "", "meaning": "在这儿/拿去吧。（= Here you are.）"}, {"num": 5, "word": "be booked in Room +", "phonetic": "", "pos": "", "meaning": "数字 预订……（号码） 的房间"}, {"num": 6, "word": "luggage", "phonetic": "[ˈlʌɡɪdʒ]", "pos": "名", "meaning": "行李（不可数名词）"}, {"num": 7, "word": "suitcase", "phonetic": "[ˈsutkes]", "pos": "名", "meaning": "手提箱"}, {"num": 8, "word": "bellboy", "phonetic": "[ˈbɛlbɔɪ]", "pos": "名", "meaning": "（旅馆中帮人提行李或送东西等的） 男服务生"}, {"num": 9, "word": "show +", "phonetic": "", "pos": "", "meaning": "人 + to + 地方 将某人带到某地"}], "grammar": [{"num": 1, "title": "&quot;check into a / the hotel&quot; 是指在旅馆或饭店登记办理住宿的手续，也就等于 &quot;check in (at a / the hotel)&quot; 的用法。", "desc": [], "formulas": [], "examples": []}, {"num": 2, "title": "如果要表示“办理退房手续”时，则可以用 &quot;check out (of a / the hotel)&quot; 这个短语。", "desc": [], "formulas": [], "examples": []}, {"num": 1, "title": "I have a reservation for a suite.", "desc": ["（我订了一间套房。）", "我们在 Lesson 19 中已介绍过 &quot;make a reservation for&quot;（预订...） 的用法，这里再介绍另一个常用的短语 &quot;have a reservation for&quot;。&quot;have a reservation for&quot; 强调的是预订的事实；而 &quot;make a reservation for&quot; 则强调预订的动作。"], "formulas": [], "examples": []}, {"num": 2, "title": "Please fill out this form.", "desc": ["= Please fill in this form.", "（请填一下这张表格。）", "fill out （美式用法） 或 fill in （英式用法） 也是很实用的短语，表示“填写（表格、文件等）”的意思。"], "formulas": [], "examples": []}, {"num": 3, "title": "will you pay by cash or charge?", "desc": ["= Will you pay by cash or (by) credit card?", "（您要付现金还是刷卡？）", "此处的by charge 就是不付现金，而用信用卡付账的意思，也就等于by credit card 之意。", "charge 除了用做名词外，还可以作动词用，表示“收费”、“索价”之意。其句型如下：", "The tutor charges his students US $1 an hour for English lessons.", "（那个家教教一个小时英文课向学生收一块美金。）"], "formulas": [], "examples": []}, {"num": 4, "title": "Do you take traveler's checks?", "desc": ["= Do you accept traveler's checks?", "（你们收旅行支票吗？）", "这里的 take 和 accept [ək'sɛpt] 都是表示“接受”的意思；要询问对方“接不接受...（的付款方式）”时，都可用 take 或 accept。"], "formulas": [], "examples": []}, {"num": 5, "title": "Certainly. 当然。", "desc": ["= Of course.", "当赞成对方的说法、看法或请求、帮助时，就可用 &quot;Certainly&quot; 来回答，也就等于 &quot;Of course.&quot;。"], "formulas": [], "examples": []}, {"num": 1, "title": "One moment, please.", "desc": ["= One minute, please.", "= Just a moment, please.", "= Just a minute, please.", "（请稍候/请稍等一下。）"], "formulas": [], "examples": []}, {"num": 2, "title": "You have a reservation for a single room, right?", "desc": ["= You have a reservation for a single room, don't you?", "（您订了一间单人房，对不对？）", "此处的 right 就等于 don't you，表示“对不对（呀）”的意思；这种在叙述句之后加上 right 的用法（此时 right 的语气要上扬） 称做反问句（又叫附加问句），这在英文中是很常见的。形成反问句的基本原则是：", "肯定句要以否定反问；否定句要以肯定反问；而且反问部分的主语始终为人称代名词（he、she、they、you、we...）。", "肯定句：John is nice, right?", "= John is nice, isn't he?", "（约翰人很好，对不对？）", "否定句：Tom and Mary aren't students, right?", "= Tom and Mary aren't students, are they?", "（汤姆和小梅都不是学生，对吗？）", "肯定句：You will come, right?", "= You will come, won't you?", "（你会来，对不对？）", "否定句：She can't speak English, right?", "= She can't speak English, can she?", "（她不会说英文，对吗？）", "肯定句：Helen loves flowers, right?", "= Helen loves flowers, doesn't she?", "（海伦很喜欢花，对不对？）", "否定句：You don't like me, right?", "= You don't like me, do you?", "（你不喜欢我，对吗？）"], "formulas": [], "examples": []}, {"num": 3, "title": "Do you have any luggage?", "desc": ["（您有行李吗？）", "luggage 和 baggage 都是“行李”的意思，而且都是不可数名词。", "因为“行李”包括旅行时所带的袋子、手提袋、手提箱、公事包等，所以 luggage 和 baggage 是一种集合名词，因此就不能说 a luggage / baggage、two luggages / baggages...", "但如果加上单位名称如 &quot;a piece of...&quot;（一件...） 时，我们就可以说 &quot;a piece of luggage / baggage&quot;（一件行李）、&quot;two pieces of luggage / baggage&quot;（两件行李）...", "luggage 和 baggage 虽然是不可数名词，但组成行李的箱子、袋子等都是可数名词，这些常见的字有下列：", "bag [bæg]（袋子）、handbag ['hændˌbæg]（手提包）、box [bɑks]（箱子）、suitcase ['sutˌkes]（手提箱）、briefcase ['brifˌkes]（公事包）。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Mr. Brown will [check into the hotel / check in at the hotel] tomorrow.", "zh": "布朗先生明天将在那家旅馆登记办理住宿手续。", "pairs": [{"en": "Mr. Brown will [check into the hotel / check in at the hotel] tomorrow.", "zh": "布朗先生明天将在那家旅馆登记办理住宿手续。"}]}, {"num": 2, "en": "I have a reservation for a [suite. / table for six.]", "zh": "我订了一间套房。 / 我订了一张六个人坐的餐桌。", "pairs": [{"en": "I have a reservation for a [suite. / table for six.]", "zh": "我订了一间套房。 / 我订了一张六个人坐的餐桌。"}]}, {"num": 3, "en": "Please fill [out / in] this [form. / application.]", "zh": "请填一下这张表格/申请书。", "pairs": [{"en": "Please fill [out / in] this [form. / application.]", "zh": "请填一下这张表格/申请书。"}]}, {"num": 4, "en": "Will you pay by cash or [credit card? / charge?]", "zh": "您要付现金还是刷卡？", "pairs": [{"en": "Will you pay by cash or [credit card? / charge?]", "zh": "您要付现金还是刷卡？"}]}, {"num": 5, "en": "You have a reservation for a single room, [right? / don't you?]", "zh": "你订了一间单人房，对不对？", "pairs": [{"en": "You have a reservation for a single room, [right? / don't you?]", "zh": "你订了一间单人房，对不对？"}]}, {"num": 6, "en": "[Let's have lunch together, shall we? / Speak louder, will you?]", "zh": "咱们一起吃个午饭吧，要不要？ / 说大声一点，好吗？", "pairs": [{"en": "[Let's have lunch together, shall we? / Speak louder, will you?]", "zh": "咱们一起吃个午饭吧，要不要？ / 说大声一点，好吗？"}]}], "exercises": []}, {"num": 21, "title_en": "Changing Money", "title_zh": "换钱", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "I would like to cash these traveler's checks, please.", "zh": "麻烦你，我想把这些旅行支票换成现金。"}, {"speaker": "B", "en": "How much do you have?", "zh": "你有多少？"}, {"speaker": "A", "en": "Five hundred US dollars.", "zh": "500美元。"}, {"speaker": "B", "en": "Do you have any identification?", "zh": "你有任何身分证明文件吗？"}, {"speaker": "A", "en": "Will my passport do?", "zh": "我的护照可以吗？"}, {"speaker": "B", "en": "That'll be fine.", "zh": "那就可以了。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "What's the exchange rate for US dollars, please?", "zh": "请问美元的汇率是多少？"}, {"speaker": "B", "en": "Which currency do you want to change your money into?", "zh": "你要把钱换成哪一种货币？"}, {"speaker": "A", "en": "Hong Kong dollars, please.", "zh": "港币，麻烦你。"}, {"speaker": "B", "en": "It's 7.89 Hong Kong dollars to 1 US dollar.", "zh": "汇率是7.89港币兑1美元。"}, {"speaker": "A", "en": "Can you change US $100?", "zh": "你能换100美元吗？"}, {"speaker": "B", "en": "How do you want your money?", "zh": "你要多少面额的钱？"}, {"speaker": "A", "en": "Seven hundreds, eight tens and the rest in change, please.", "zh": "七张100元，八张10元，其余的换成零钱。"}, {"speaker": "B", "en": "No problem.", "zh": "没问题。"}]}], "reading": null, "vocab": [{"num": 1, "word": "change", "phonetic": "[tʃeɪndʒ]", "pos": "动", "meaning": "（交） 换"}, {"num": 2, "word": "cash", "phonetic": "[kæʃ]", "pos": "动", "meaning": "兑换现金 &amp; 名 现金"}, {"num": 3, "word": "identification", "phonetic": "[aɪˌdɛntəfəˈkeʃən]", "pos": "名", "meaning": "身份证明（文件）"}, {"num": 1, "word": "exchange rate", "phonetic": "[ɪksˈtʃendʒ ret]", "pos": "名", "meaning": "（外汇） 汇率"}, {"num": 2, "word": "currency", "phonetic": "[ˈkɝənsɪ]", "pos": "名", "meaning": "货币"}, {"num": 3, "word": "rest", "phonetic": "[rɛst]", "pos": "名", "meaning": "剩余（部分），其余"}], "grammar": [{"num": 1, "title": "语法详解", "desc": ["change money 换钱，有时亦可说 exchange money。", "change A into B 把A换成B", "I want to change HK$ 30,000 into US dollars.", "（我想把三万港币换成美金。）"], "formulas": [], "examples": []}, {"num": 1, "title": "I would like to cash these traveler's checks, please.", "desc": ["（麻烦你，我想把这些旅行支票换成现金。）", "How many cashes/changes do you have? ( × )", "→ How much cash/change do you have? (O)", "= How much do you have in cash/change?", "（你有多少现金/零钱？）", "I have 20 dollars in cash/change.", "（我有20元现金/零钱。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Do you have any identification?", "desc": ["（你有任何身份证明文件吗？）", "identification 是指证明身份的文件，一般有三种证照可为证明：", "ID card = identity card [aɪ'dɛntətɪ kɑrd]（身份证）", "driver's license ['draɪvɚz 'laɪsəns]（驾驶执照）", "passport ['pæspɔrt]（护照）"], "formulas": [], "examples": []}, {"num": 3, "title": "Will my passport do?", "desc": ["（我的护照可以吗？）", "do 原表示“做（工作）”，此处则表示“行”或“可以”。"], "formulas": [], "examples": []}, {"num": 4, "title": "That'll be fine.（那就可以了。）", "desc": ["= That'll be OK.", "= That'll do."], "formulas": [], "examples": []}, {"num": 1, "title": "what's the exchange rate for US dollars, please?", "desc": ["（请问美元的汇率是多少？）", "What's the exchange rate for +货币名称?", "某货币的汇率是多少？", "What's the exchange rate between +货 币名称+ and +货币名称？", "某货币兑某货币的汇率是多少？"], "formulas": [], "examples": []}, {"num": 2, "title": "Which currency do you want to change your money into?", "desc": ["（你要把钱换成哪一种货币？）", "currency 是指某一国实际通用的货币而言。"], "formulas": [], "examples": []}, {"num": 3, "title": "It's 7.89 Hong Kong dollars to 1 US dollar.", "desc": ["（汇率是7.89港币兑1美元。）"], "formulas": [], "examples": []}, {"num": 7, "title": "89 的读法为 seven point eight nine。小数点之后的数字须一个一个分开念，不可合成十位数或百位数来念。如 18.18 须念成 eighteen point one eight，而不可念成 eighteen point eighteen；0.235 须念成 zero point two three five，不可念成 zero point two hundred and thirty-five。", "desc": [], "formulas": [], "examples": []}, {"num": 4, "title": "How do you want your money?", "desc": ["（你要多少面额的钱？）", "本句为兑换外币时，银行行员问顾客的话。比如说，你用港币换了350美元，而美元有1元、5元、10元、20元、50元、100元等面额不同的纸钞，要凑足350美元就会有各种不同的排列组合，所以行员会问你要如何分配。"], "formulas": [], "examples": []}, {"num": 5, "title": "Seven hundreds, eight tens and the rest in change, please.", "desc": ["= Seven one-hundred-dollar bills, eight ten-dollar bills and the rest in change, please.", "（七张100元钞，八张10元钞，其余的换成零钱。）", "此处的 the rest 为代名词，是 the rest of the money 之省略。", "Only two students are absent, and the rest (of the students) are all present today.", "（今天只有两位学生缺席，其余的均出席了。）"], "formulas": [], "examples": []}, {"num": 6, "title": "No problem.", "desc": ["（没问题。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "I would like to cash [these traveler's checks, / this check,] please.", "zh": "麻烦你，我想把这些旅行支票/这张支票换成现金。", "pairs": [{"en": "I would like to cash [these traveler's checks, / this check,] please.", "zh": "麻烦你，我想把这些旅行支票/这张支票换成现金。"}]}, {"num": 2, "en": "[Will my passport do? / That'll do. / That won't do.]", "zh": "我的护照可以吗？ / 那可以。 / 那不行。", "pairs": [{"en": "[Will my passport do? / That'll do. / That won't do.]", "zh": "我的护照可以吗？ / 那可以。 / 那不行。"}]}, {"num": 3, "en": "What's the exchange rate [for US dollars, please? / between US dollars and Hong Kong dollars, please?]", "zh": "请问美元的汇率是多少？ / 请问美元对港币的汇率是多少？", "pairs": [{"en": "What's the exchange rate [for US dollars, please? / between US dollars and Hong Kong dollars, please?]", "zh": "请问美元的汇率是多少？ / 请问美元对港币的汇率是多少？"}]}, {"num": 4, "en": "How much do you have in [cash? / change?]", "zh": "你有多少现金/零钱？", "pairs": [{"en": "How much do you have in [cash? / change?]", "zh": "你有多少现金/零钱？"}]}, {"num": 5, "en": "I have only ten dollars in [cash. / change.]", "zh": "我只有10块现金/零钱。", "pairs": [{"en": "I have only ten dollars in [cash. / change.]", "zh": "我只有10块现金/零钱。"}]}], "exercises": []}, {"num": 22, "title_en": "Booking an Airline Ticket", "title_zh": "订机票", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Hi! My name is John Lin. I'd like to book a flight to Rome, please.", "zh": "嗨！我叫林约翰。我想预订到罗马的班机。"}, {"speaker": "B", "en": "Do you wish to fly first class, business or economy?", "zh": "您想搭头等舱、商务舱还是经济舱？"}, {"speaker": "A", "en": "Economy.", "zh": "经济舱。"}, {"speaker": "B", "en": "Date of departure?", "zh": "出发的日期呢？"}, {"speaker": "A", "en": "July 4th.", "zh": "7月4日"}, {"speaker": "B", "en": "OK. You're booked on flight number CX167. It departs at 11:15 AM.", "zh": "好的。您预订的是CX167班机。早上11点15分起飞。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Japan Airlines. Can I help you?", "zh": "日本航空公司。我可以为您效劳吗？"}, {"speaker": "B", "en": "Yes. I'm Peter Lai. I'd like to reserve a round-trip ticket to Paris, please.", "zh": "是的。我是赖彼得。麻烦你，我想预订到巴黎的来回机票。"}, {"speaker": "A", "en": "Which class? And for when?", "zh": "您要搭什么舱位？还有时间是什么时候？"}, {"speaker": "B", "en": "Business class; for this Sunday.", "zh": "商务舱；时间是这个星期天。"}, {"speaker": "A", "en": "One moment, please. OK. I've booked you on flight number 007. lt departs at 5 :30 PM. Please call back on Friday to reconfirm.", "zh": "请稍候。好了，我已为您订了下午5：30起飞的007号班机。请在星期五打电话来再确认。"}, {"speaker": "B", "en": "OK.", "zh": "好的。"}, {"speaker": "A", "en": "Your confirmation code number is XE3849.", "zh": "您的确认代码是XE3849。"}, {"speaker": "B", "en": "Thank you.", "zh": "谢谢。"}]}], "reading": null, "vocab": [{"num": 1, "word": "airline", "phonetic": "[ˈɛrˌlaɪn]", "pos": "名", "meaning": "航空公司"}, {"num": 2, "word": "Rome", "phonetic": "[rom]", "pos": "名", "meaning": "罗马（意大利首都）"}, {"num": 3, "word": "wish", "phonetic": "[wɪʃ]", "pos": "动", "meaning": "想（要），希望"}, {"num": 4, "word": "fly", "phonetic": "[flaɪ]", "pos": "动", "meaning": "搭乘（飞机）；飞（行）"}, {"num": 5, "word": "class", "phonetic": "[klæs]", "pos": "名", "meaning": "等级；first class 头等舱"}, {"num": 6, "word": "business", "phonetic": "[ˈbɪznɪs]", "pos": "名", "meaning": "商业，生意；business class 商务舱"}, {"num": 7, "word": "economy", "phonetic": "[ɪˈkɑnəmɪ]", "pos": "名", "meaning": "经济；economy class 经济舱"}, {"num": 8, "word": "departure", "phonetic": "[dɪˈpɑrtʃɚ]", "pos": "名", "meaning": "离开；出发"}, {"num": 9, "word": "flight number", "phonetic": "", "pos": "", "meaning": "班机号"}, {"num": 10, "word": "depart", "phonetic": "[dɪˈpɑrt]", "pos": "动", "meaning": "出发"}, {"num": 1, "word": "round-trip", "phonetic": "[ˈraʊndˌtrɪp]", "pos": "形", "meaning": "来回的，往返的"}, {"num": 2, "word": "Paris", "phonetic": "[ˈpærɪs]", "pos": "名", "meaning": "巴黎（法国首都）"}, {"num": 3, "word": "reconfirm", "phonetic": "[ˌrikənˈfɝm]", "pos": "动", "meaning": "再确认"}, {"num": 4, "word": "confirmation", "phonetic": "[ˌkɑnfɚˈmeʃən]", "pos": "名", "meaning": "确定，确认"}, {"num": 15, "word": "confirmation code number", "phonetic": "", "pos": "", "meaning": "确认代码"}], "grammar": [{"num": 1, "title": "Do you wish to fly first class, business or economy?", "desc": ["= Do you wish to fly first class, business class or economy class?", "（你想搭头等舱、商务舱还是经济舱？）", "= I hope to study abroad.", "（我想要出国念书。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Date of departure?", "desc": ["= What's the date of your departure?", "（出发的日期呢？）", "date 是指年、月、日等的“日期”，&quot;date of departure&quot; 译作“出发日期”；“出生日期”的说法则为 &quot;date of birth&quot;；但 date of birth 与 birthday 不同的是：date of birth 包括出生的年、月、日，而 birthday 则不包括出生的年份。"], "formulas": [], "examples": []}, {"num": 3, "title": "It departs at 11:15 AM.", "desc": ["（它起飞的时间是早上11点15分。）", "depart for + 地方 出发/动身前往某地", "Jimmy usually arrives at school at 6:30 am.", "（吉米通常早上6：30到校。）"], "formulas": [], "examples": []}, {"num": 1, "title": "I'd like to reserve a round-trip ticket to Paris, please.", "desc": ["= I'd like to book a round-trip ticket to Paris, please.", "（麻烦你，我想预订到巴黎的来回机票。）", "a round-trip ticket 来回票", "a one-way ticket 单程票", "You can't drive in there; it's a one-way street.", "（你不能开进去那里；那条是单行道。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Which class? And for when?", "desc": ["= Which class would you like to fly? And when do you want to leave?", "（你要搭乘哪一种舱位？还有您要什么时候离开？）"], "formulas": [], "examples": []}, {"num": 3, "title": "I've booked you on flight number 007.", "desc": ["= I have booked you on flight number 007.", "（我已为您订了007号班机。）", "动词book （预订） 之后，除了可以接旅馆房间、座位、门票等，还可以接“人”作宾语，表示“为某人预订...”的意思。"], "formulas": [], "examples": []}, {"num": 4, "title": "Please call back on Friday to reconfirm.", "desc": ["（请在星期五打电话来再确认。）", "我们一般在预订班机时，为避免机位被取消，都还要在出发前三天打电话给航空公司再做确认，以确保机位。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "I [wish / hope] to travel around the world.", "zh": "我希望能够环游世界。", "pairs": [{"en": "I [wish / hope] to travel around the world.", "zh": "我希望能够环游世界。"}]}, {"num": 2, "en": "Mr. Wang will leave for Hong Kong tomorrow.", "zh": "王先生明天将动身前往香港。", "pairs": [{"en": "Mr. Wang will leave for Hong Kong tomorrow.", "zh": "王先生明天将动身前往香港。"}]}, {"num": 3, "en": "John goes to bed at [midnight / ten o'clock] every day.", "zh": "约翰每天都到半夜/10点钟才上床睡觉。", "pairs": [{"en": "John goes to bed at [midnight / ten o'clock] every day.", "zh": "约翰每天都到半夜/10点钟才上床睡觉。"}]}, {"num": 4, "en": "Mr. Li works best [in the morning. / in the afternoon. / at night.]", "zh": "李先生早上/下午/晚上的工作效率最好。", "pairs": [{"en": "Mr. Li works best [in the morning. / in the afternoon. / at night.]", "zh": "李先生早上/下午/晚上的工作效率最好。"}]}, {"num": 5, "en": "My birthday is on [February 29. / Christmas Day.]", "zh": "我的生日是2月29号/圣诞节那天。", "pairs": [{"en": "My birthday is on [February 29. / Christmas Day.]", "zh": "我的生日是2月29号/圣诞节那天。"}]}, {"num": 6, "en": "How much is it for a [round-trip / one-way] ticket to Los Angeles?", "zh": "到洛杉矶的来回票/单程票要多少钱？", "pairs": [{"en": "How much is it for a [round-trip / one-way] ticket to Los Angeles?", "zh": "到洛杉矶的来回票/单程票要多少钱？"}]}], "exercises": []}, {"num": 23, "title_en": "At the Airport I", "title_zh": "在机场（一）", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "This is the arrival lounge.", "zh": "这里是入境大厅。"}, {"speaker": "B", "en": "I know. Where is the departure lounge?", "zh": "我知道。出境大厅在哪里呢？"}, {"speaker": "A", "en": "Come. Follow me.", "zh": "来吧，跟我走。"}, {"speaker": "B", "en": "There! The check-in counters are over there.", "zh": "那里！办理登机手续的柜台在那里。"}, {"speaker": "A", "en": "Don't we have to go pay the airport tax first?", "zh": "我们不用先去付机场税吗？"}, {"speaker": "B", "en": "No. We pay it after we check in.", "zh": "不用。先办完登机手续后再付。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Good morning. May I have your passport, please?", "zh": "早安。请把你的护照给我好吗？"}, {"speaker": "B", "en": "Here you are.", "zh": "在这儿。"}, {"speaker": "A", "en": "Smoking or non-smoking?", "zh": "你要坐在吸烟区或非吸烟区？"}, {"speaker": "B", "en": "Non-smoking.", "zh": "非吸烟区。"}, {"speaker": "A", "en": "Aisle or window seat?", "zh": "你要靠过道还是靠窗的座位？"}, {"speaker": "B", "en": "Window seat, please.", "zh": "请给我靠窗的座位。"}, {"speaker": "A", "en": "Do you have any luggage to check in?", "zh": "你有任何行李要托运吗？"}, {"speaker": "B", "en": "Yes. This is my carry-on luggage and I'll check in these two suitcases.", "zh": "有的。这是我的随身行李，这两个行李箱我要托运。"}]}], "reading": null, "vocab": [{"num": 1, "word": "airport", "phonetic": "[ˈɛrˌpɔrt]", "pos": "名", "meaning": "机场"}, {"num": 2, "word": "arrival lounge", "phonetic": "[əˈraɪvl ˈlaʊndʒ]", "pos": "名", "meaning": "（机场） 入境大厅"}, {"num": 3, "word": "departure lounge", "phonetic": "[dɪˈpɑrtʃɚ ˈlaʊndʒ]", "pos": "名", "meaning": "（机场） 出境大厅"}, {"num": 4, "word": "follow", "phonetic": "[ˈfɑlo]", "pos": "动", "meaning": "跟随"}, {"num": 5, "word": "check-in counter", "phonetic": "[ˈtʃɛkˌɪn ˌkaʊntɚ]", "pos": "名", "meaning": "办理登机手续的柜台；counter ['kaʊntɚ] 名 柜台"}, {"num": 6, "word": "pay", "phonetic": "[peɪ]", "pos": "动", "meaning": "付（钱）"}, {"num": 7, "word": "tax", "phonetic": "[tæks]", "pos": "名", "meaning": "税"}, {"num": 1, "word": "aisle", "phonetic": "[aɪl]", "pos": "名", "meaning": "通道，过道"}, {"num": 2, "word": "window", "phonetic": "[ˈwɪndo]", "pos": "名", "meaning": "窗（户）"}, {"num": 3, "word": "seat", "phonetic": "[sit]", "pos": "名", "meaning": "座位"}, {"num": 4, "word": "carry-on", "phonetic": "[ˈkæriˈɑn]", "pos": "形", "meaning": "随身携带的"}], "grammar": [{"num": 1, "title": "This is the arrival lounge.", "desc": ["（这里是人境大厅。）", "arrive [ə'raɪv] 动 到达", "armive 之后常接介词at 或in 再接地方名词，如下列用法：", "arrive at + 地点（建筑物如邮局、车站等） 到达", "arrive in + 地方（大地方如城市、国家等） 到达", "上列两个大厅皆在机场航站大厦（air terminal ['ɛr ˌtɝmənəl]） 里面。lounge ['laʊndʒ] 是大厅或休息室的意思，如 teacher's lounge （教师休息室），但旅馆或饭店内的大厅则叫做 lobby ['lɑbɪ]。"], "formulas": [], "examples": []}, {"num": 2, "title": "Come, follow me.", "desc": ["（来吧，跟我走。）", "follow me 表示“跟我走”，在口语对话中就等于 this way。"], "formulas": [], "examples": []}, {"num": 3, "title": "There! The check-in counters are over there.", "desc": ["（那里！办理登机手续的柜台在那里。）", "上列中 over 为作强调用的副词。over there / here 为目视距离内的指示用法，通常亦可在其前加上另一个强调副词 right，形成 right over there （就在那里） 和 right over here （就在这里）。此外，亦可将 over 省略，形成 right here / here，但此时则无距离的含意。", "right 亦可用来强调介词短语，over 则不可。"], "formulas": [], "examples": []}, {"num": 4, "title": "Don't we have to go pay the airport tax first?", "desc": ["= Don't we have to go and pay the airport tax first?", "（我们不用先去付机场税吗？）", "→ They sing and dance happily day after day. (O)", "（日复一日他们快乐地唱歌和跳舞。）", "= Please go buy me a newspaper.", "（请去帮我买一份报纸。）", "= When you have time, come visit me.", "（有时间的时候，请来看我。）", "pay + 钱 + for... 付钱买...", "政府向人民征收机场税以回收建造机场的费用。"], "formulas": [], "examples": []}, {"num": 5, "title": "We pay it after we check in.", "desc": ["（我们先办完登机手续后再付。）", "我们在 Lesson 20 中已学过 &quot;check in&quot; 乃指（在旅馆） 办理住宿的手续；但此处的 &quot;check-in&quot; 则表示（在机场） 办理登机的手续。"], "formulas": [], "examples": []}, {"num": 1, "title": "May I have your passport, please?", "desc": ["（请把你的护照给我好吗？）", "May I have your..., please?", "请把你的...给我好吗？", "这是很客气的要求，your 之后可接各种名词。"], "formulas": [], "examples": []}, {"num": 2, "title": "Smoking or non-smoking?", "desc": ["= Would you like to sit in the smoking section or the non-smoking section?", "（你要坐在吸烟区或非吸烟区？）", "以前飞机上有分吸烟区和非吸烟区。近年来由于考虑到飞行安全，大部分飞机上都全面禁烟，空服员会作类似下列广播："], "formulas": [], "examples": []}, {"num": 3, "title": "Aisle or window seat?", "desc": ["= Would you like an aisle seat or a window seat?", "（你要靠走道的座位还是靠窗的座位？）", "aisle seat 是指在飞机上或火车上等靠过道的座位，而 window seat 是指靠窗户的座位。"], "formulas": [], "examples": []}, {"num": 4, "title": "Do you have any luggage to check in?", "desc": ["（你有任何行李要托运吗？）", "= baggage ['bægɪdʒ] 名", "上列为集合名词，是不可数名词，不可说 a luggage / baggage, two luggages / baggages, many luggages / baggages，而须说 a piece of luggage / baggage （一件行李），two pieces of luggage / baggage （两件行李），a lot of luggage / baggage （很多行李）。", "所谓集合名词是指任何同类东西总称的名词，例如 handbag （手提袋）、suitcase （行李箱），它们是可数的普通名词，可说 a handbag，two handbags，a suitcase，two suitcases，但总称为 luggage 或 baggage （行李）。其他如 a dollar （1美元）、a cent （1分钱） 亦为可数的普通名词，但总称为 money （钱） 时，就变成不可数的集合名词，不可说成 a money, two moneys。类似的集合名词如 trash [træʃ]、garbage ['gɑrbɪdʒ]、rubbish ['rʌbɪʃ] 均为“垃圾”之意，news [njuz] 表示“消息”，information [ˌɪnfɚ'meʃən] 表示“资讯”，furniture ['fɝnɪtʃɚ] 表示“家具”等，为数并不多，只要稍加留意即可。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "This is the [arrival / departure] lounge.", "zh": "这里是入境/出境大厅。", "pairs": [{"en": "This is the [arrival / departure] lounge.", "zh": "这里是入境/出境大厅。"}]}, {"num": 2, "en": "[Jack usually arrives at the school at seven o'clock. / Rose will arrive in Taipei tomorrow.]", "zh": "杰克通常7点到校。 / 罗丝明天将抵达台北。", "pairs": [{"en": "[Jack usually arrives at the school at seven o'clock. / Rose will arrive in Taipei tomorrow.]", "zh": "杰克通常7点到校。 / 罗丝明天将抵达台北。"}]}, {"num": 3, "en": "[Follow me. / This way.]", "zh": "跟我来。 / 这边请。", "pairs": [{"en": "[Follow me. / This way.]", "zh": "跟我来。 / 这边请。"}]}, {"num": 4, "en": "The check-in counters are [over there. / right over there.]", "zh": "办理登机手续的柜台在那里/就在那里。", "pairs": [{"en": "The check-in counters are [over there. / right over there.]", "zh": "办理登机手续的柜台在那里/就在那里。"}]}, {"num": 5, "en": "[Don't we have to go pay the airport tax first? / My friends and I will go see a movie tonight.]", "zh": "我们不用先去付机场税吗？ / 我和我朋友今晚要去看电影。", "pairs": [{"en": "[Don't we have to go pay the airport tax first? / My friends and I will go see a movie tonight.]", "zh": "我们不用先去付机场税吗？ / 我和我朋友今晚要去看电影。"}]}, {"num": 6, "en": "May I have your [passport, / coat,] please?", "zh": "请把你的护照/外套给我好吗？", "pairs": [{"en": "May I have your [passport, / coat,] please?", "zh": "请把你的护照/外套给我好吗？"}]}], "exercises": []}, {"num": 24, "title_en": "At the Airport II", "title_zh": "在机场（二）", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Please fill out these tags and attach them to your suitcases. Then put them on the scale.", "zh": "请填好这些标签后把它们系在你的行李箱上。然后把它们放在秤上。"}, {"speaker": "B", "en": "OK.", "zh": "好的。"}, {"speaker": "A", "en": "I'm afraid your luggage is overweight. You'll have to pay an excess baggage charge.", "zh": "恐怕你的行李超重了。你必须额外付行李超重费。"}, {"speaker": "B", "en": "How much will that be?", "zh": "那要多少钱？"}, {"speaker": "A", "en": "Let me see -- US $10.", "zh": "让我看看——10美元。"}, {"speaker": "B", "en": "That's not too bad.", "zh": "还不算太糟。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Here are your tickets. The baggage claim stubs are attached to them.", "zh": "这里是你的机票。领取行李的存根就附在上面。"}, {"speaker": "B", "en": "Thank you.", "zh": "谢谢。"}, {"speaker": "A", "en": "And here is your boarding pass. You board at Gate 12.", "zh": "这儿是你的登机证。你在12号门登机。"}, {"speaker": "B", "en": "OK. Is that all?", "zh": "好的。就这样吗？"}, {"speaker": "A", "en": "No. Please wait here till your luggage goes through the X-ray machine.", "zh": "还没。请在这里等你的行李通过X光检测机。"}, {"speaker": "B", "en": "OK.", "zh": "好吧。"}, {"speaker": "A", "en": "Have a nice flight.", "zh": "祝你搭机愉快。"}, {"speaker": "B", "en": "Thank You.", "zh": "谢谢。"}]}], "reading": null, "vocab": [{"num": 1, "word": "tag", "phonetic": "[tæɡ]", "pos": "名", "meaning": "标签"}, {"num": 2, "word": "attach", "phonetic": "[əˈtætʃ]", "pos": "动", "meaning": "系，固定"}, {"num": 3, "word": "put", "phonetic": "[pʊt]", "pos": "动", "meaning": "放，摆"}, {"num": 4, "word": "scale", "phonetic": "[skel]", "pos": "名", "meaning": "秤，磅秤"}, {"num": 5, "word": "overweight", "phonetic": "[ˌovɚˈwet]", "pos": "形", "meaning": "超/过重的"}, {"num": 6, "word": "excess", "phonetic": "[ɪkˈsɛs]", "pos": "形", "meaning": "额外的；超过的"}, {"num": 1, "word": "baggage claim stub", "phonetic": "[klem]", "pos": "名", "meaning": "提领行李的存根"}, {"num": 2, "word": "boarding pass", "phonetic": "[ˈbɔrdɪŋ pæs]", "pos": "名", "meaning": "登机证"}, {"num": 3, "word": "board", "phonetic": "[bord]", "pos": "动", "meaning": "登上（飞机、船等）"}, {"num": 4, "word": "gate", "phonetic": "[ɡet]", "pos": "名", "meaning": "大门，登机门"}, {"num": 5, "word": "wait", "phonetic": "[wet]", "pos": "动", "meaning": "等（待）"}, {"num": 6, "word": "till", "phonetic": "[tɪl]", "pos": "连", "meaning": "直到……为止"}, {"num": 7, "word": "X-ray machine", "phonetic": "[ˈɛks, re məˈʃin]", "pos": "名", "meaning": "X光检测机"}], "grammar": [{"num": 1, "title": "Please fill out these tags and attach them to your suitcases.", "desc": ["（请填好这些标签后把它们系在你的行李箱上。）", "= fill in...", "attach A to B 把A系在/到B上"], "formulas": [], "examples": []}, {"num": 2, "title": "I'm afraid your luggage is overweight.", "desc": ["= I'm afraid that your luggage is overweight.", "（恐怕你的行李超重了。）", "上列句型中 that 常被省略。", "I'm afraid (that) it is going to rain this afternoon.", "（恐怕今天下午会下雨。）", "Anyone can see that you're overweight; you should go on a diet.", "（任何人都看得出来你体重过重，你应该要节食了。）"], "formulas": [], "examples": []}, {"num": 3, "title": "You'll have to pay an excess baggage charge.", "desc": ["（你必须额外付行李超重费。）", "have to 和 must 虽然都可译为“必须”，但 have to 是含有被勉强而不得不的意味。而 must 则除此意之外，尚有道德上不得不然的意味。", "You have to / must do this work whether you like it or not.", "（不管你喜不喜欢，你都必须做这工作。）"], "formulas": [], "examples": []}, {"num": 4, "title": "How much will that be?", "desc": ["（那要多少钱？）", "购物时，不论你买多少样东西，加总后得到的价钱，总额是一个数字，故代名词用 that。"], "formulas": [], "examples": []}, {"num": 5, "title": "Let me see-US$ 10.", "desc": ["（让我看看——10美元。）", "Let me see 或 Let's see 之后常接破折符号（——），表示停顿之意，说话者此时可能是在看、计算、想或思考等。"], "formulas": [], "examples": []}, {"num": 6, "title": "That's not too bad.", "desc": ["（那还不算太糟。）", "= What a shame!"], "formulas": [], "examples": []}, {"num": 1, "title": "Here are your tickets. The baggage claim stubs are attached to them.", "desc": ["（这里是你的机票，领取行李的存根就附在上面。）"], "formulas": [], "examples": []}, {"num": 2, "title": "And here is your boarding pass. You board at Gate 12.", "desc": ["= And here is your boarding pass. You board at Gate Number 12.", "（这儿是你的登机证，你在12号门登机。）"], "formulas": [], "examples": []}, {"num": 3, "title": "Is that all?", "desc": ["（就这样吗？）"], "formulas": [], "examples": []}, {"num": 4, "title": "Please wait here till your baggage goes through the X-ray machine.", "desc": ["（请在这里等你的行李通过X光检测机。）", "= They will not leave until the sun goes down.", "（他们直到太阳下山才会离开。）", "= I'll stay here until Friday.", "（我将一直待到这个礼拜五。）"], "formulas": [], "examples": []}, {"num": 5, "title": "Have a nice flight.", "desc": ["= May you have a nice flight.", "= I hope (that) you (may) have a nice flight.", "（祝你搭机愉快。）", "由上列等句中，大家不难看出 &quot;Have a nice flight.&quot; 的简化过程。其他如 &quot;Have a good time&quot;（祝你玩得愉快。）", "或 &quot;Have a nice day&quot;（祝你今天过得愉快。）", "等，其简化过程亦如上列。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "I'm afraid [your luggage is overweight. / I have to leave now.]", "zh": "恐怕你的行李超重了。 / 恐怕我现在必须离开了。", "pairs": [{"en": "I'm afraid [your luggage is overweight. / I have to leave now.]", "zh": "恐怕你的行李超重了。 / 恐怕我现在必须离开了。"}]}, {"num": 2, "en": "You [have to / must] finish the job by twelve o'clock.", "zh": "你必须在12点前完成这项工作。", "pairs": [{"en": "You [have to / must] finish the job by twelve o'clock.", "zh": "你必须在12点前完成这项工作。"}]}, {"num": 3, "en": "[That's too bad! / What a shame!]", "zh": "太可惜了！", "pairs": [{"en": "[That's too bad! / What a shame!]", "zh": "太可惜了！"}]}, {"num": 4, "en": "[Here are your tickets. / Here is your book.]", "zh": "这里是你的机票/书。", "pairs": [{"en": "[Here are your tickets. / Here is your book.]", "zh": "这里是你的机票/书。"}]}, {"num": 5, "en": "You board at [Gate 12. / Gate Number 12.]", "zh": "你在12号门登机。", "pairs": [{"en": "You board at [Gate 12. / Gate Number 12.]", "zh": "你在12号门登机。"}]}, {"num": 6, "en": "Please wait here [till / until] your luggage goes through the X-ray machine.", "zh": "请在这里等你的行李通过X光检测机。", "pairs": [{"en": "Please wait here [till / until] your luggage goes through the X-ray machine.", "zh": "请在这里等你的行李通过X光检测机。"}]}, {"num": 7, "en": "[Have a nice flight. / May you have a nice flight. / I hope that you may have a nice flight.]", "zh": "祝你搭机愉快。", "pairs": [{"en": "[Have a nice flight. / May you have a nice flight. / I hope that you may have a nice flight.]", "zh": "祝你搭机愉快。"}]}], "exercises": []}, {"num": 25, "title_en": "At the Post Office", "title_zh": "在邮局", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "I'd like to register this letter, please.", "zh": "麻烦你，我想用挂号寄这封信。"}, {"speaker": "B", "en": "Where to?", "zh": "寄到哪里？"}, {"speaker": "A", "en": "Los Angeles.", "zh": "洛杉矶。"}, {"speaker": "B", "en": "Ok. Let me weigh it. That'll be three dollars, please.", "zh": "好的，让我来称一下重量。邮资是3美元，麻烦你。"}, {"speaker": "A", "en": "Here you are. Do I have to fill out a form?", "zh": "拿去吧。我必须填写表格吗？"}, {"speaker": "B", "en": "No. Just give me your name, address and telephone number.", "zh": "不必。只要把你的姓名、住址和电话给我就行了。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "I'd like to send this by air mail, please.", "zh": "我想要用航空邮寄这个，麻烦你。"}, {"speaker": "B", "en": "Is it a birthday card?", "zh": "那是生日贺卡吗？"}, {"speaker": "A", "en": "Yes. Why do you ask?", "zh": "是的。你为什么这样问？"}, {"speaker": "B", "en": "Cards are cheaper than letters.", "zh": "卡片比信件要来得便宜。"}, {"speaker": "A", "en": "Oh! Really?", "zh": "哦！真的吗？"}, {"speaker": "B", "en": "You can't seal the envelope, though.", "zh": "不过你不能把信封封起来。"}, {"speaker": "A", "en": "Ok. How much for the stamps?", "zh": "好吧。我要贴多少钱的邮票？"}, {"speaker": "B", "en": "Two dollars.", "zh": "2美元。"}]}], "reading": null, "vocab": [{"num": 1, "word": "post office", "phonetic": "[ˈpost,ɔfɪs]", "pos": "名", "meaning": "邮局"}, {"num": 2, "word": "register", "phonetic": "[ˈrɛdʒɪstɚ]", "pos": "动", "meaning": "挂号邮寄"}, {"num": 3, "word": "letter", "phonetic": "[ˈlɛtɚ]", "pos": "名", "meaning": "信"}, {"num": 4, "word": "weigh", "phonetic": "[we]", "pos": "动", "meaning": "称……重量"}, {"num": 5, "word": "address", "phonetic": "[ˈædrɛs / əˈdrɛs]", "pos": "名", "meaning": "地址"}, {"num": 1, "word": "send", "phonetic": "[sɛnd]", "pos": "动", "meaning": "寄；发出"}, {"num": 2, "word": "airmail", "phonetic": "[ˈɛr, mel]", "pos": "名", "meaning": "航空邮件"}, {"num": 3, "word": "card", "phonetic": "[kɑrd]", "pos": "名", "meaning": "卡片；birthday card 生日卡片"}, {"num": 4, "word": "seal", "phonetic": "[sil]", "pos": "动", "meaning": "封；密封"}, {"num": 5, "word": "envelope", "phonetic": "[ˈɛnvə, lop]", "pos": "名", "meaning": "信封"}, {"num": 6, "word": "though", "phonetic": "[ðo]", "pos": "副", "meaning": "不过，然而"}, {"num": 7, "word": "stamp", "phonetic": "[stæmp]", "pos": "名", "meaning": "邮票"}], "grammar": [{"num": 1, "title": "语法详解", "desc": ["at the post office 在邮局", "in the post office 在邮局里面", "注意这里用 at 和 in 的区别：", "用 at 时，表示在某栋建筑物的里面或外面并不一定；而用 in 时则强调是在建筑物的里面。"], "formulas": [], "examples": []}, {"num": 1, "title": "I'd like to register this letter, please.", "desc": ["（麻烦你，我想用挂号寄这封信。）", "register this letter 用挂号寄这封信"], "formulas": [], "examples": []}, {"num": 2, "title": "Where to?", "desc": ["= Where do you want to send this letter?", "（你要把信寄到哪里？）", "&quot;Where to?&quot; 是极常用的口语。因为 where 是副词，不能直接作介词 to 的宾语，但简略成口语用法时，则常说 &quot;Where to?&quot;。"], "formulas": [], "examples": []}, {"num": 3, "title": "Let me weigh it.", "desc": ["（让我来称一下它的重量。）"], "formulas": [], "examples": []}, {"num": 4, "title": "That'll be three dollars, please.", "desc": ["（邮资是3美元，麻烦你。）", "That'll 是 That will 的缩写。", "= Please sit down.", "（请坐。）", "= Please open the door.", "（请把门打开。）"], "formulas": [], "examples": []}, {"num": 5, "title": "Do I have to fill out a form?", "desc": ["（我必须填写表格吗？）", "fill out a form / fill in a form 填写表格", "Please fill out / in the form in detail.", "（请详细填写这份表格。）"], "formulas": [], "examples": []}, {"num": 1, "title": "I'd like to send this by air mail, please.", "desc": ["（我想要用航空邮寄这个，麻烦你。）", "by air mail 寄航空", "by sea mail 寄海运", "by regular mail 寄平信", "by registered mail 寄挂号", "by special delivery = by express delivery 寄限时专送", "= I want to send the letter by express delivery.", "（我要用限时专送寄这封信。）", "mail 作名词时，表示各种邮件的总称（包括信及包裹），为不可数名词；作动词时表示“邮寄”。", "mail a letter 寄一封信", "= send a letter", "= post a letter", "→ I usually receive a lot of mail every day. (O)", "（通常我每天都会收到很多邮件。）", "= Please send the letter for me.", "= Please post the letter for me.", "（请帮我寄这一封信。）"], "formulas": [], "examples": []}, {"num": 2, "title": "You can't seal the envelope, though.", "desc": ["（不过你不能把信封封起来。）", "尾，前面加逗点。", "×本句的&quot;You can't seal the envelope, though. 即为此种用法。", "的句法，英文中不能用&quot;Because&quot;so&quot;&quot;的句法，而只能用其一。", "→Though he is nice, I don't like him. (O)", "→He is nice, but I don't like him. (o)", "（虽然他人很好，但是我不喜欢他。）", "→Because he is nice, I like him. (o)", "→He is nice, so I like him. (o)", "（因为他人很好，所以我喜欢他。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "I'll meet you [at / in] the restaurant.", "zh": "我将和你在餐厅/在餐厅里面碰面。", "pairs": [{"en": "I'll meet you [at / in] the restaurant.", "zh": "我将和你在餐厅/在餐厅里面碰面。"}]}, {"num": 2, "en": "[Let me weigh it. / Let me help you.]", "zh": "让我来称一下它的重量。 / 让我帮你吧。", "pairs": [{"en": "[Let me weigh it. / Let me help you.]", "zh": "让我来称一下它的重量。 / 让我帮你吧。"}]}, {"num": 3, "en": "Would you please [do me a favor? / open the door for me?]", "zh": "可不可以请你帮我一个忙？ / 可不可以请你帮我开个门？", "pairs": [{"en": "Would you please [do me a favor? / open the door for me?]", "zh": "可不可以请你帮我一个忙？ / 可不可以请你帮我开个门？"}]}, {"num": 4, "en": "I'd like to send this by [air mail, / sea mail, / regular mail, / registered mail, / special delivery,] please.", "zh": "我想要用航空/海运/平信/挂号/限时专送邮寄这个，麻烦你。", "pairs": [{"en": "I'd like to send this by [air mail, / sea mail, / regular mail, / registered mail, / special delivery,] please.", "zh": "我想要用航空/海运/平信/挂号/限时专送邮寄这个，麻烦你。"}]}, {"num": 5, "en": "[Though he is rich, he is very stingy. / He is rich, but he is very stingy.]", "zh": "虽然他很有钱，但他却很吝啬。", "pairs": [{"en": "[Though he is rich, he is very stingy. / He is rich, but he is very stingy.]", "zh": "虽然他很有钱，但他却很吝啬。"}]}, {"num": 6, "en": "[Because I am busy, I can't go with you. / I am busy, so I can't go with you.]", "zh": "因为我很忙，所以我不能跟你去。", "pairs": [{"en": "[Because I am busy, I can't go with you. / I am busy, so I can't go with you.]", "zh": "因为我很忙，所以我不能跟你去。"}]}], "exercises": []}, {"num": 26, "title_en": "At the Doctor's", "title_zh": "看病", "type": "dialogue", "category": "日常高频情境口语", "tip": "看病就诊：描述症状常用 'I have a fever / sore throat / headache.'，或者 'I'm not feeling well.'", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Doctor, I think I have the flu.", "zh": "医生，我想我得了流行性感冒。"}, {"speaker": "B", "en": "Do you have a cough, too?", "zh": "你也有咳嗽吗？"}, {"speaker": "A", "en": "No. Not really.", "zh": "不，算不上真的咳嗽。"}, {"speaker": "B", "en": "Do you have a sore throat?", "zh": "喉咙会痛吗？"}, {"speaker": "A", "en": "A little. But I have a bit of a fever.", "zh": "一点点。但我有一点发烧。"}, {"speaker": "B", "en": "Ok. Let me have a look.", "zh": "好的。让我来看看。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Open your mouth and say, &quot;Ah...!&quot;", "zh": "张开嘴巴说“啊...”！"}, {"speaker": "B", "en": "Ah...", "zh": "啊..."}, {"speaker": "A", "en": "Yes, it's quite serious. I think you need a shot.", "zh": "是了，情况相当严重。我想你得打一针。"}, {"speaker": "B", "en": "Is it going to hurt?", "zh": "会不会痛呢？"}, {"speaker": "A", "en": "Don't worry. It'll soon be over.", "zh": "别担心，很快就会结束的。"}, {"speaker": "B", "en": "Ouch!", "zh": "哎哟！"}, {"speaker": "A", "en": "OK. It's done. Also, take these pills 3 times a day after meals.", "zh": "好了，打完针了。还有，饭后服用这些药丸，一天三次。"}, {"speaker": "B", "en": "Ok. Thanks, doctor. Bye.", "zh": "好的。谢谢你，医生。再见。"}]}], "reading": null, "vocab": [{"num": 1, "word": "doctor", "phonetic": "[ˈdɑktɚ]", "pos": "名", "meaning": "医生；at the doctor's 在医生诊所 = at the doctor's office"}, {"num": 2, "word": "flu", "phonetic": "[flu]", "pos": "名", "meaning": "流行性感冒"}, {"num": 3, "word": "cough", "phonetic": "[kɔf]", "pos": "名", "meaning": "咳嗽"}, {"num": 4, "word": "sore", "phonetic": "[sɔr]", "pos": "形", "meaning": "（疼） 痛的"}, {"num": 5, "word": "throat", "phonetic": "[θrot]", "pos": "名", "meaning": "喉咙"}, {"num": 6, "word": "fever", "phonetic": "[ˈfivɚ]", "pos": "名", "meaning": "发烧"}, {"num": 1, "word": "mouth", "phonetic": "[maʊθ]", "pos": "名", "meaning": "嘴，口"}, {"num": 2, "word": "ah", "phonetic": "[ɑ]", "pos": "叹", "meaning": "啊（表示悲、喜、惊、怜悯等的感叹声）"}, {"num": 3, "word": "quite", "phonetic": "[kwaɪt]", "pos": "副", "meaning": "颇，相当地"}, {"num": 4, "word": "serious", "phonetic": "[ˈsɪrɪəs]", "pos": "形", "meaning": "严重的"}, {"num": 5, "word": "shot", "phonetic": "[ʃɑt]", "pos": "名", "meaning": "打针"}, {"num": 6, "word": "hurt", "phonetic": "[hɝt]", "pos": "动", "meaning": "疼痛；伤害"}, {"num": 7, "word": "soon", "phonetic": "[sun]", "pos": "副", "meaning": "不久，马上"}, {"num": 8, "word": "over", "phonetic": "[ˈovɚ]", "pos": "形", "meaning": "完毕的，结束的"}, {"num": 9, "word": "ouch", "phonetic": "[aʊtʃ]", "pos": "叹", "meaning": "哎唷"}, {"num": 10, "word": "also", "phonetic": "[ˈɔlso]", "pos": "副", "meaning": "也，并且"}, {"num": 11, "word": "pill", "phonetic": "[pɪl]", "pos": "名", "meaning": "药丸"}, {"num": 12, "word": "time", "phonetic": "[taɪm]", "pos": "名", "meaning": "次，回"}, {"num": 13, "word": "after", "phonetic": "[ˈæftɚ]", "pos": "介", "meaning": "在……之后"}, {"num": 14, "word": "meal", "phonetic": "[mil]", "pos": "名", "meaning": "一餐"}], "grammar": [{"num": 1, "title": "Doctor, I think I have the flu.", "desc": ["（医生，我想我得了流行性感冒。）", "来表示。本来自己是否得了流行性感冒，自己应该很清楚，但如果直接说 &quot;Doctor, I have the flu&quot; 则未免太过武断，对医生来说也不太尊重，故用 &quot;I think (that)...&quot; 或 &quot;I'm afraid (that)...&quot; 来缓和语气。", "I think (that) it is going to rain today.", "（我想今天会下雨。）", "I'm afraid (that) it is going to rain today.", "（恐怕今天会下雨。）", "表示“得了流行性感冒”，flu 之前须置定冠词 the，而不可用不定冠词 a。", "（约翰因为得了流行性感冒，所以身体不舒服。）", "have a cold 得了感冒", "= catch a cold", "= catch cold", "Pull on your coat, or you will catch (a) cold.", "（把外套穿起来，否则你会感冒。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Do you have a cough, too?", "desc": ["（你也有咳嗽吗？）", "have a cough 咳嗽", "此处的 cough （咳嗽） 是名词，但 cough 也可以作动词用。"], "formulas": [], "examples": []}, {"num": 3, "title": "No. Not really.", "desc": ["（不，算不上真的咳嗽。）"], "formulas": [], "examples": []}, {"num": 4, "title": "Do you have a sore throat?", "desc": ["（喉咙会痛吗？）", "have a sore throat 喉咙痛", "sore 是形容词，表示“疼痛的”，指发炎或受伤的部位一碰就痛的感觉；此外，sore 还可用来表示肌肉方面“酸痛的”，如：have a sore arm （手臂酸痛）、have a sore leg （腿部酸痛）。", "ache [ek] 也可表示“疼痛”，常常和其他字并用形成复合字，但 ache 则是指某部位持续疼痛的感觉，例如："], "formulas": [], "examples": []}, {"num": 5, "title": "A little. But I have a bit of a fever.", "desc": ["= I have a little of a sore throat. But I have a bit of a fever.", "（一点点。但我有一点发烧。）", "= a little bit of...", "= a little of..."], "formulas": [], "examples": []}, {"num": 6, "title": "Let me have a look.", "desc": ["（让我看看。）", "中文说“让我看看”，英文是&quot;Let me have a look。有许多学生为了俏皮常说成&quot;Let me see see：或&quot;Let me look look：，固然有趣，但却是错误的用法，应该说 &quot;Let me have a look&quot; 才对。", "会话。"], "formulas": [], "examples": []}, {"num": 1, "title": "It's quite serious. I think you need", "desc": ["（情况相当严重，我想你得打一针。）", "（他用功读书。）", "（她看起来很美。）", "（他很用功读书。）", "（他是个年轻男孩。）", "（她很美。）", "It is fairly/quite/rather hot today.", "（今天相当热。一但不是很热）", "get / take a shot （接受） 打针", "= get / take an injection"], "formulas": [], "examples": []}, {"num": 2, "title": "ls it going to hurt?", "desc": ["（打针会不会痛呢？）", "= It will rain this afternoon.", "（今天下午将会下雨。）", "= I will take a trip next week.", "（我下周将会去旅行。）"], "formulas": [], "examples": []}, {"num": 3, "title": "Don't worry. It'll soon be over.", "desc": ["（别担心。很快就会结束的。）", "是会话中经常使用来安慰他人的话，同学宜记住。", "worry about... 担心...", "= be worried about...", "= We are all worried about you very much.", "（我们都非常担心你。）"], "formulas": [], "examples": []}, {"num": 4, "title": "Ouch!", "desc": ["哎唷！", "&quot;Ouch!&quot; 是英文中的拟声词，表示因突来的疼痛而发出的叫声。其他常见的声音词尚有：", "Wow! [waʊ]（哇！）", "表示惊奇、赞叹；", "Uh-oh! ['ʌ'o]（喔唷！）", "表示事情不妙；", "Uh-huh! ['ʌ'hʌ]（嗯哼！）", "表示赞同之意。"], "formulas": [], "examples": []}, {"num": 5, "title": "OK. It's done.", "desc": ["= OK. It is done.", "= OK. It is finished.", "（好了，打完针了。）", "此处 done 是形容词，表示“做完的”，等于 finished。"], "formulas": [], "examples": []}, {"num": 6, "title": "Also, take these pills 3 times a day after meals.", "desc": ["（还有，饭后服用这些药丸，一天三次。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Doctor, I think I have [the flu. / a cold.]", "zh": "医生，我想我得了流行性感冒/感冒。", "pairs": [{"en": "Doctor, I think I have [the flu. / a cold.]", "zh": "医生，我想我得了流行性感冒/感冒。"}]}, {"num": 2, "en": "Do you have a [cough, / sore throat, / fever,] too?", "zh": "你也有咳嗽/喉咙痛/发烧吗？", "pairs": [{"en": "Do you have a [cough, / sore throat, / fever,] too?", "zh": "你也有咳嗽/喉咙痛/发烧吗？"}]}, {"num": 3, "en": "It's [quite / very / extremely] serious.", "zh": "情况相当/很/极为严重。", "pairs": [{"en": "It's [quite / very / extremely] serious.", "zh": "情况相当/很/极为严重。"}]}, {"num": 4, "en": "I think you need [a shot. / an injection.]", "zh": "我想你得打一针。", "pairs": [{"en": "I think you need [a shot. / an injection.]", "zh": "我想你得打一针。"}]}, {"num": 5, "en": "Is it going to [hurt? / rain?]", "zh": "会不会痛呢？ / 会不会下雨呢？", "pairs": [{"en": "Is it going to [hurt? / rain?]", "zh": "会不会痛呢？ / 会不会下雨呢？"}]}, {"num": 6, "en": "[Also, take these pills 3 times a day after meals. / Tom goes to Hong Kong once a week. / This magazine is published 4 times a month.]", "zh": "还有，饭后服用这些药丸，一天三次。 / 汤姆一个星期去香港一趟。 / 这本杂志一个月出版四次。", "pairs": [{"en": "[Also, take these pills 3 times a day after meals. / Tom goes to Hong Kong once a week. / This magazine is published 4 times a month.]", "zh": "还有，饭后服用这些药丸，一天三次。 / 汤姆一个星期去香港一趟。 / 这本杂志一个月出版四次。"}]}], "exercises": []}, {"num": 27, "title_en": "At the Zoo", "title_zh": "在动物园", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I take a picture with the lion, Dad?", "zh": "我可以和狮子照张相吗，老爸？"}, {"speaker": "B", "en": "Sure. But don't go too near the cage.", "zh": "当然可以。不过不要太靠近笼子喔。"}, {"speaker": "A", "en": "I'll stand behind the railing.", "zh": "我会站在栏杆后面。"}, {"speaker": "B", "en": "OK. Are you ready? Say &quot;Cheese!&quot;", "zh": "好了，准备好了吗？说“Cheese”！"}, {"speaker": "A", "en": "Cheese!", "zh": "Cheese!"}, {"speaker": "B", "en": "That's a good one.", "zh": "这张照得很棒。"}, {"speaker": "A", "en": "Lions are beautiful, aren't they?", "zh": "狮子好漂亮喔，对不对？"}, {"speaker": "B", "en": "They sure are. After all, the lion is &quot;king of the beasts!&quot;", "zh": "当然啰。毕竟，狮子是“万兽之王”啊。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Wow! Look at that elephant. It's gigantic!", "zh": "哇！看那头大象，好大喔！"}, {"speaker": "B", "en": "It sure is.", "zh": "它的确是。"}, {"speaker": "A", "en": "Can I feed it?", "zh": "我可以喂它吗？"}, {"speaker": "B", "en": "No. There's a no-feeding sign over there.", "zh": "不行。那儿有一个禁止喂食的标志。"}, {"speaker": "A", "en": "Poor elephant.", "zh": "可怜的大象。"}, {"speaker": "B", "en": "There aren't many elephants left in the world, are there?", "zh": "世界上所剩的大象不多了，不是吗？"}, {"speaker": "A", "en": "People kill them for their tusks. Now they are an endangered species.", "zh": "人们为取得象牙而杀害它们，现在它们成了濒临绝种动物。"}, {"speaker": "B", "en": "Man sometimes behaves worse than animals.", "zh": "人类的行为有时候连禽兽都不如。"}]}], "reading": null, "vocab": [{"num": 1, "word": "zoo", "phonetic": "[zu]", "pos": "名", "meaning": "动物园"}, {"num": 2, "word": "picture", "phonetic": "[ˈpɪktʃɚ]", "pos": "名", "meaning": "相片，照片"}, {"num": 3, "word": "lion", "phonetic": "[ˈlaɪən]", "pos": "名", "meaning": "狮子"}, {"num": 4, "word": "near", "phonetic": "[nɪr]", "pos": "介", "meaning": "靠近……的"}, {"num": 5, "word": "cage", "phonetic": "[kedʒ]", "pos": "名", "meaning": "笼子"}, {"num": 6, "word": "stand", "phonetic": "[stænd]", "pos": "动", "meaning": "站立"}, {"num": 7, "word": "behind", "phonetic": "[bɪˈhaɪnd]", "pos": "介", "meaning": "在……后面"}, {"num": 8, "word": "railing", "phonetic": "[ˈreln]", "pos": "名", "meaning": "栏杆；围栏"}, {"num": 9, "word": "ready", "phonetic": "[ˈred]", "pos": "形", "meaning": "准备好的"}, {"num": 10, "word": "cheese", "phonetic": "[tiz]", "pos": "名", "meaning": "乳酪，干酪"}, {"num": 11, "word": "after all", "phonetic": "", "pos": "", "meaning": "毕竟,终究"}, {"num": 12, "word": "king of the beasts 万兽之王；king", "phonetic": "[kɪŋ]", "pos": "名", "meaning": "国王；beast [bist] 名 野兽"}, {"num": 1, "word": "elephant", "phonetic": "[ˈɛləfənt]", "pos": "名", "meaning": "象"}, {"num": 2, "word": "gigantic", "phonetic": "[dʒaɪˈɡæntɪk]", "pos": "形", "meaning": "巨大的"}, {"num": 3, "word": "feed", "phonetic": "[fid]", "pos": "动", "meaning": "喂食"}, {"num": 4, "word": "no-feeding sign 禁止喂食的标志；sign", "phonetic": "[saɪn]", "pos": "名", "meaning": "标志"}, {"num": 5, "word": "poor", "phonetic": "[pʊr]", "pos": "形", "meaning": "可怜的；贫穷的"}, {"num": 6, "word": "left", "phonetic": "[lɛft]", "pos": "形", "meaning": "剩下（来） 的"}, {"num": 7, "word": "in the world", "phonetic": "[wɝld]", "pos": "名", "meaning": "在世界上"}, {"num": 8, "word": "kill", "phonetic": "[kɪl]", "pos": "动", "meaning": "杀（害）"}, {"num": 9, "word": "tusk", "phonetic": "[tʌsk]", "pos": "名", "meaning": "（象等的） 长牙"}, {"num": 10, "word": "endangered", "phonetic": "[ɪnˈdendʒɚd]", "pos": "形", "meaning": "濒临绝种的"}, {"num": 11, "word": "species", "phonetic": "[ˈspiʃiz]", "pos": "名", "meaning": "种，种类（单复数同形）"}, {"num": 12, "word": "man", "phonetic": "[mæn]", "pos": "名", "meaning": "人类（用单数形）；男人（复数形为 men [mɛn]）"}, {"num": 13, "word": "sometimes", "phonetic": "[ˈsʌmtaɪmz]", "pos": "副", "meaning": "有时候"}, {"num": 14, "word": "behave", "phonetic": "[bɪˈhev]", "pos": "动", "meaning": "行为，举止"}, {"num": 15, "word": "animal", "phonetic": "[ˈænəml]", "pos": "名", "meaning": "动物"}], "grammar": [{"num": 1, "title": "Can I take a picture with the lion, Dad?", "desc": ["（我可以和狮子照张相吗，老爸？）"], "formulas": [], "examples": []}, {"num": 2, "title": "But don't go too near the cage.", "desc": ["= But don't go too close to the cage.", "（不过不要太靠近笼子。）", "= His house is close to the school.", "（他家离学校很近。）"], "formulas": [], "examples": []}, {"num": 3, "title": "I'll stand behind the railing.", "desc": ["（我会站在栏杆后面。）", "railing 是“栏杆”的意思，此处乃指防止游客靠近的狮笼的栏杆而言。"], "formulas": [], "examples": []}, {"num": 4, "title": "OK. Are you ready? Say &quot;Cheese!&quot;", "desc": ["（你准备好了吗？说“Cheese”！）"], "formulas": [], "examples": []}, {"num": 5, "title": "That's a good one.", "desc": ["（这张照得很棒。）", "&quot;That's a good one.&quot; 是表示赞许的话，字面上的意思是“这个很不错。”通常在他人说了一句好词，或一则好笑的笑话，我们可以说 &quot;That's a good one&quot;，以示嘉许之意；但依对话上下文判断，此处则是指被照相者微笑很甜，洗出来一定是一张很棒的照片。"], "formulas": [], "examples": []}, {"num": 6, "title": "Lions are beautiful, aren't they?", "desc": ["（狮子好漂亮喔，对不对？）", "本句为标准的反问句。其原则为：", "叙述句为肯定时，接否定反问句； 叙述句为否定时，接肯定反问句。", "此外，反问句的主语一定为代词。", "Let 之后若接其他的人作宾语，则反问句要用 will you。"], "formulas": [], "examples": []}, {"num": 7, "title": "They sure are. After all, the lion is &quot;king of the beasts.&quot;", "desc": ["= They sure are beautiful. After all, the lion is &quot;king of the beasts.&quot;", "（他们的确漂亮。毕竟，狮子是“万兽之王”啊。）"], "formulas": [], "examples": []}, {"num": 1, "title": "Wow! Look at that elephant. It's gigantic!", "desc": ["（哇！看那头大象，好大喔！）", "= Take a look at that girl. Isn't she beautiful?", "= Have a look at that girl. Isn't she beautiful?", "（看那位女孩，是不是很漂亮啊？）"], "formulas": [], "examples": []}, {"num": 2, "title": "It sure is.", "desc": ["= It sure is gigantic.", "（它的确是很大。）"], "formulas": [], "examples": []}, {"num": 3, "title": "Can I feed it?", "desc": ["（我可以喂它吗？）", "feed 是动词，表示“喂食”的意思。"], "formulas": [], "examples": []}, {"num": 4, "title": "Poor elephant.", "desc": ["（可怜的大象。）", "此处的 poor 是形容词，表示“可怜的”之意；但 poor 亦可以表示“贫穷的”。"], "formulas": [], "examples": []}, {"num": 5, "title": "There aren't many elephants left in the world, are there?", "desc": ["（世界上所剩的大象不多了，不是吗？）", "此处的 left 是由动词 leave 演变而来的形容词，表示“剩下来的”，使用时置于名词之后。"], "formulas": [], "examples": []}, {"num": 6, "title": "People kill them for their tusks. Now they are an endangered species.", "desc": ["（人们为取得象牙而杀害他们，现在他们成了濒临绝种的动物。）", "species 是单复数同形的名词，亦即可说 one species, two species, many species 等。本来英文中一般的名词由单数变成复数时，通常在字尾加 -s 或 -es，如 one book, two books 和 one inch （一英寸），two inches；但有些名词的单数形和复数形拼法不变，此类单复数同形的名词，除上述 species 之外，常见的尚有：fish （鱼）、sheep [ʃip]（绵羊）、deer [dɪr]（鹿）、salmon ['sæmən]（鲑鱼）、buffalo ['bʌfəlo]（水牛）、antelope ['æntəlop]（羚羊） 等。这些字的确令人困扰，但幸好它们为数并不多，只要见一个记一个，日子一久功力加深，问题自可迎刃而解。"], "formulas": [], "examples": []}, {"num": 7, "title": "Man sometimes behaves worse than animals.", "desc": ["（人类的行为有时候连禽兽都不如。）", "常见用法：", "behave oneself 循规蹈矩，守规矩", "behave well 行为表现良好", "worst [wɝst] 副 最坏地（是副词 badly 的最高级）", "better ['bɛtɚ] 副 较好地（是副词 well 的比较级）", "best [bɛst] 副 最好地（是副词 well 的最高级）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "[Can I take a picture with the lion, Dad? / Can I take a picture of the monkey, Mom? / Excuse me, can you take a picture for us?]", "zh": "我可以和狮子照张相吗，老爸？ / 我可以给狮子照张相吗，老妈？ / 打扰一下，可以请你为我们照张相吗？", "pairs": [{"en": "[Can I take a picture with the lion, Dad? / Can I take a picture of the monkey, Mom? / Excuse me, can you take a picture for us?]", "zh": "我可以和狮子照张相吗，老爸？ / 我可以给狮子照张相吗，老妈？ / 打扰一下，可以请你为我们照张相吗？"}]}, {"num": 2, "en": "[Are you ready? / Are you ready to go? / Are you ready for lunch?]", "zh": "你准备好了吗？ / 你准备好要走了吗？ / 你准备好吃午餐了吗？", "pairs": [{"en": "[Are you ready? / Are you ready to go? / Are you ready for lunch?]", "zh": "你准备好了吗？ / 你准备好要走了吗？ / 你准备好吃午餐了吗？"}]}, {"num": 3, "en": "[Lions are beautiful, aren't they? / Bill can't speak Japanese, can he? / May goes to bed late, doesn't she? / Stop talking, will you? / Let's take a break, shall we?]", "zh": "狮子好漂亮喔，对不对？ / 比尔不会说日文，是吗？ / 小梅都很晚睡，对不对？ / 别讲话了，好吗？ / 咱们休息一下吧，好不好？", "pairs": [{"en": "[Lions are beautiful, aren't they? / Bill can't speak Japanese, can he? / May goes to bed late, doesn't she? / Stop talking, will you? / Let's take a break, shall we?]", "zh": "狮子好漂亮喔，对不对？ / 比尔不会说日文，是吗？ / 小梅都很晚睡，对不对？ / 别讲话了，好吗？ / 咱们休息一下吧，好不好？"}]}, {"num": 4, "en": "[Look / Take a look / Have a look] at that elephant.", "zh": "看那头大象。", "pairs": [{"en": "[Look / Take a look / Have a look] at that elephant.", "zh": "看那头大象。"}]}], "exercises": []}, {"num": 28, "title_en": "Going to the Movies", "title_zh": "看电影", "type": "dialogue", "category": "日常高频情境口语", "tip": "熟读并大声跟读会话，注意连读与语调起伏。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Can I have two tickets for Titanic, please?", "zh": "可以给我两张“铁达尼号”的票吗？"}, {"speaker": "B", "en": "For what time?", "zh": "什么时间的？"}, {"speaker": "A", "en": "The 9:30 p. m. show, please.", "zh": "麻烦晚上九点半那一场。"}, {"speaker": "B", "en": "I'm afraid it's full. How about the midnight show?", "zh": "恐怕已经客满了，午夜场如何？"}, {"speaker": "A", "en": "That'll be fine. Can I have our seats up front, please?", "zh": "可以，请给我前排的座位好吗？"}, {"speaker": "B", "en": "Sure. That'll be twenty dollars, please.", "zh": "没问题。麻烦你总共是20美元。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Where were you last night?", "zh": "你昨晚到哪儿去了？"}, {"speaker": "B", "en": "I was at the movies. I went to see Titanic.", "zh": "我在看电影，我跑去看“铁达尼号”。"}, {"speaker": "A", "en": "How was it?", "zh": "好看吗？"}, {"speaker": "B", "en": "It was fantastic. The main actor and actress really did a good job.", "zh": "非常好看。男女主角演得真是棒极了。"}, {"speaker": "A", "en": "Sounds like it was a very good movie.", "zh": "听你这么说好像是部很棒的电影。"}, {"speaker": "B", "en": "You can say that again!", "zh": "你说的一点也没错！"}]}], "reading": null, "vocab": [{"num": 1, "word": "Titanic", "phonetic": "[taɪˈtænɪk]", "pos": "名", "meaning": "泰坦尼克号（电影名）；the Titanic 泰坦尼克号轮船（英国巨轮，1912年在其处女航中于纽芬兰南方海面撞上冰山而沉没）"}, {"num": 2, "word": "show", "phonetic": "[ʃo]", "pos": "名", "meaning": "（电影、电视、戏剧、广播的） 演出节目"}, {"num": 3, "word": "full", "phonetic": "[fʊl]", "pos": "形", "meaning": "满的"}, {"num": 4, "word": "midnight show", "phonetic": "", "pos": "", "meaning": "午夜场"}, {"num": 1, "word": "were", "phonetic": "[wɚ]", "pos": "", "meaning": "be 动词 are 的过去式"}, {"num": 2, "word": "was", "phonetic": "[wʌz]", "pos": "", "meaning": "be 动词 am, is 的过去式"}, {"num": 3, "word": "went", "phonetic": "[wɛnt]", "pos": "动", "meaning": "词 go 的过去式"}, {"num": 4, "word": "fantastic", "phonetic": "[fænˈtæstɪk]", "pos": "形", "meaning": "很棒的，极好的"}, {"num": 5, "word": "main", "phonetic": "[men]", "pos": "形", "meaning": "主要的，最重要的"}, {"num": 6, "word": "actor", "phonetic": "[ˈæktɚ]", "pos": "名", "meaning": "男演员"}, {"num": 7, "word": "actress", "phonetic": "[ˈæktrɪs]", "pos": "名", "meaning": "女演员"}, {"num": 8, "word": "did", "phonetic": "[dɪd]", "pos": "动", "meaning": "词 do 的过去式"}], "grammar": [{"num": 1, "title": "语法详解", "desc": ["go to the movies 看电影", "go to the movies 表示“看电影”，movies 须用复数。但表示“看一场电影”则可有下列用法：", "watch a movie 看一场电影", "= see a movie", "= take in a movie", "= We are going to see a movie tonight.", "= We are going to take in a movie tonight.", "（我们今晚要去看一场电影。）"], "formulas": [], "examples": []}, {"num": 1, "title": "Can I have two tickets for Titanic, please?", "desc": ["（可以给我两张“铁达尼号”的票吗？）"], "formulas": [], "examples": []}, {"num": 2, "title": "For what time?", "desc": ["= For what time would you like the tickets?", "（什么时间的？/你要什么时间的票？）", "此处 &quot;For what time?&quot; 是由 &quot;For what time would you like the tickets?&quot; 简化而来。"], "formulas": [], "examples": []}, {"num": 3, "title": "The 9.30 p. m. show, please.", "desc": ["= I'd like to have tickets for the 9:30 p. m. show, please.", "（麻烦晚上9：30那一场。/麻烦我要晚上9：30那一场的票。）", "show 本来是指表演、演出，此处则是指电影。", "We will go to see the 3:00 p. m. show (of the movie).", "= We will go to see the movie that is shown at 3:00 p. m.", "（我们将去看下午3点放映的那场电影。）"], "formulas": [], "examples": []}, {"num": 4, "title": "I'm afraid it's full. How about the midnight movie?", "desc": ["= I'm afraid that the tickets are sold out. What about the midnight show?", "（恐怕已经客满了/恐怕票已经卖光了，午夜场如何？）", "be full of... 充满...", "= What about going to the movies tonight?", "（今晚去看电影如何？）"], "formulas": [], "examples": []}, {"num": 5, "title": "Can I have two seats up front, please?", "desc": ["（请给我前排的座位好吗？）", "Can I have a seat... - please?", "请给我...的座位好吗？", "Can I have a seat near/by the aisle, please?", "（请给我靠走道的座位好吗？）", "Can I have a seat on the left/right side, please?", "（请给我左/右边的座位好吗？）"], "formulas": [], "examples": []}, {"num": 6, "title": "That'll be twenty dollars, please.", "desc": ["（麻烦你总共是20美元。）", "That'll be + 金钱 一共是...（钱）", "= That'll be + 金钱 + in total", "= All this comes to + 金钱", "= That'll be 50 dollars in total.", "= All this comes to 50 dollars.", "（甲：我要付你多少钱？）", "（乙：一共是50美元。）"], "formulas": [], "examples": []}, {"num": 7, "title": "其他和电影有关的用语如下：", "desc": ["When will the new movie/film be on?", "（这部新片何时上映？）", "That movie is a rerun; that's why it's cheaper.", "（那部电影是二轮片，所以比较便宜。）"], "formulas": [], "examples": []}, {"num": 1, "title": "Where were you last night?", "desc": ["（你昨晚到哪儿去了？）", "此处的 were 是 be 动词 are 的过去式。", "过去式是表示在过去时间所发生的事，中英文在表示过去式时态时差别很大。中文里会用过去时间来表示，动词维持不变，英文虽也用过去时间，但动词形态改变。例如中文说：“我爱她。”和“我三年前很爱她。”，动词“爱”不改变，但英文说：&quot;I love her.&quot; 和 &quot;I loved her three years ago.&quot;。动词由现在式 love 变成过去式 loved，因此我们必须随时注意，以免犯下文法错误。", "步骤 1: 规则变化（原形动词加 -ed 或 -d，或去 y 改 -ied）：", "步骤 2: 不规则变化（见一个记一个）", "C. 过去式使用的时机：", "过去式是表过去所发生的事、动作或状态，通常和过去时间并用。", "(I go to school every day.(现在式）", "（我每天去上学。）", "（我昨天去上学。）"], "formulas": [], "examples": []}, {"num": 2, "title": "I was at the movies.", "desc": ["（我在看电影。）", "be at the movies 在看电影"], "formulas": [], "examples": []}, {"num": 3, "title": "It was fantastic.", "desc": ["= It was great.", "= It was wonderful.", "（它很棒。）"], "formulas": [], "examples": []}, {"num": 4, "title": "The main actor and actress really did a good job.", "desc": ["（男女主角演得真是棒极了。）", "= main actress 女主角；lead actress ['lid 'æktrɪs]", "= do (very) well", "= He did very well in the speech contest.", "（他在演讲比赛中表现优异。）"], "formulas": [], "examples": []}, {"num": 5, "title": "Sounds like it was a very good movie.", "desc": ["（听起来好像是部很棒的电影。）", "就文法而言，&quot;sound like&quot; 之中的 like 为介词，之后只能接名词作宾语，不能接主语和动词；若要接主语和动词，则须改用 &quot;sound as if...&quot;（听起来仿佛...），因为 as if 才是连接词。但在现代英文中，已把 like 既视为介词，之后接名词作宾语，又视之为连接词，之后接主语和动词。", "= He sounds like he knows everything about it.", "（听他的口气仿佛他对这件事知道得一清二楚。）"], "formulas": [], "examples": []}, {"num": 6, "title": "You can say that again!", "desc": ["（你说的一点也没错！）", "本句为赞同他人意见的用语，为极口语的用法。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "We are going to [watch / see / take in] a movie tonight.", "zh": "我们今晚要去看一场电影。", "pairs": [{"en": "We are going to [watch / see / take in] a movie tonight.", "zh": "我们今晚要去看一场电影。"}]}, {"num": 2, "en": "I'm afraid that [it's full. / the tickets are sold out.]", "zh": "恐怕已经客满了/票已经卖光了。", "pairs": [{"en": "I'm afraid that [it's full. / the tickets are sold out.]", "zh": "恐怕已经客满了/票已经卖光了。"}]}, {"num": 3, "en": "Can I have a seat [up front, / in the back, / by the aisle, / towards the center, / on the left side,] please?", "zh": "请给我前排/后面/靠走道/靠中间/左边的座位好吗？", "pairs": [{"en": "Can I have a seat [up front, / in the back, / by the aisle, / towards the center, / on the left side,] please?", "zh": "请给我前排/后面/靠走道/靠中间/左边的座位好吗？"}]}, {"num": 4, "en": "[That'll be twenty dollars, please. / That'll be twenty dollars in total, please. / All this comes to twenty dollars, please.]", "zh": "麻烦你总共是20美元。", "pairs": [{"en": "[That'll be twenty dollars, please. / That'll be twenty dollars in total, please. / All this comes to twenty dollars, please.]", "zh": "麻烦你总共是20美元。"}]}, {"num": 5, "en": "Where [were you / were they / was she] last night?", "zh": "你/他们/她昨晚到哪儿去了？", "pairs": [{"en": "Where [were you / were they / was she] last night?", "zh": "你/他们/她昨晚到哪儿去了？"}]}, {"num": 6, "en": "It was [fantastic. / great. / wonderful.]", "zh": "它很棒。", "pairs": [{"en": "It was [fantastic. / great. / wonderful.]", "zh": "它很棒。"}]}], "exercises": []}, {"num": 29, "title_en": "Job Interviews", "title_zh": "求职面试", "type": "dialogue", "category": "日常高频情境口语", "tip": "面试与自我介绍：重点在于表达 'I'm looking for an opportunity to grow and contribute my skills.'（展现热情与匹配度）。", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "Tell me, Mr. Wang. Why do you want to join our company?", "zh": "告诉我，王先生。为何你想加入我们公司？"}, {"speaker": "B", "en": "It has a good reputation.", "zh": "贵公司有良好的声誉。"}, {"speaker": "A", "en": "Do you have any work experience?", "zh": "你有任何工作经验吗？"}, {"speaker": "B", "en": "Not much. But I am willing to learn.", "zh": "不太多。但我很愿意学习。"}, {"speaker": "A", "en": "Why did you quit your last job?", "zh": "你为什么辞去上一个工作？"}, {"speaker": "B", "en": "I think I'll have a better future with your company.", "zh": "我认为在贵公司我会比较有前途。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Do you have any questions?", "zh": "你有任何问题吗？"}, {"speaker": "B", "en": "Yes. Will I have to work overtime?", "zh": "是的。我必须要加班吗？"}, {"speaker": "A", "en": "Sometimes.", "zh": "有时候要。"}, {"speaker": "B", "en": "How about holidays?", "zh": "那么放假呢？"}, {"speaker": "A", "en": "After a year, you'll get an annual leave of seven days.", "zh": "满一年后，你每年就会有7天的假期。"}, {"speaker": "B", "en": "And is there a year-end bonus?", "zh": "是否有年终奖金呢？"}, {"speaker": "A", "en": "That depends. If you work hard and the company makes money, you'll get one.", "zh": "那要视情况而定。如果你工作努力而且公司赚钱的话就会有。"}, {"speaker": "B", "en": "That sounds fair.", "zh": "听起来很合理。"}]}], "reading": null, "vocab": [{"num": 1, "word": "interview", "phonetic": "[ˈɪntɚˌvju]", "pos": "名", "meaning": "面谈；会晤"}, {"num": 2, "word": "join", "phonetic": "[dʒɔɪn]", "pos": "动", "meaning": "加入，参加"}, {"num": 3, "word": "company", "phonetic": "[ˈkʌmpənɪ]", "pos": "名", "meaning": "公司"}, {"num": 4, "word": "reputation", "phonetic": "[ˌrɛpjəˈteʃən]", "pos": "名", "meaning": "名声，声誉"}, {"num": 5, "word": "experience", "phonetic": "[ɪkˈspɪrɪəns]", "pos": "名", "meaning": "经验"}, {"num": 6, "word": "willing", "phonetic": "[ˈwɪlɪŋ]", "pos": "形", "meaning": "乐意的"}, {"num": 7, "word": "learn", "phonetic": "[lɝn]", "pos": "动", "meaning": "学习"}, {"num": 8, "word": "did", "phonetic": "[dɪd]", "pos": "助动", "meaning": "词 do 的过去式"}, {"num": 9, "word": "quit", "phonetic": "[kwɪt]", "pos": "动", "meaning": "辞（职）"}, {"num": 10, "word": "future", "phonetic": "[ˈfjutʃɚ]", "pos": "名", "meaning": "未来，将来"}, {"num": 1, "word": "question", "phonetic": "[ˈkwɛstʃən]", "pos": "名", "meaning": "问题"}, {"num": 2, "word": "overtime", "phonetic": "[ˈovɚˌtaɪm]", "pos": "副", "meaning": "超出时间地"}, {"num": 3, "word": "holiday", "phonetic": "[ˈhɑləˌde]", "pos": "名", "meaning": "假日，休假"}, {"num": 4, "word": "annual", "phonetic": "[ˈænjʊəl]", "pos": "形", "meaning": "每年的；一年一次的"}, {"num": 5, "word": "leave", "phonetic": "[liv]", "pos": "名", "meaning": "准假，休假（期间）"}, {"num": 6, "word": "year-end", "phonetic": "[ˈjɪrˈɛnd]", "pos": "形", "meaning": "年底的，年终的"}, {"num": 7, "word": "bonus", "phonetic": "[ˈbonəs]", "pos": "名", "meaning": "奖金；分红"}, {"num": 8, "word": "depend", "phonetic": "[dɪˈpɛnd]", "pos": "动", "meaning": "视……而定"}, {"num": 9, "word": "hard", "phonetic": "[hɑrd]", "pos": "副", "meaning": "努力地"}, {"num": 10, "word": "make money", "phonetic": "", "pos": "", "meaning": "赚钱"}, {"num": 11, "word": "fair", "phonetic": "[fɛr]", "pos": "形", "meaning": "公平的，合理的"}], "grammar": [{"num": 1, "title": "Why do you want to join our company?", "desc": ["（为何你想加入我们公司？）"], "formulas": [], "examples": []}, {"num": 2, "title": "It has a good reputation.", "desc": ["（贵公司有良好的声誉。）", "此处 It 指上一句的 company。"], "formulas": [], "examples": []}, {"num": 3, "title": "Do you have any work experience?", "desc": ["（你有任何工作经验吗？）", "work experience 工作经验"], "formulas": [], "examples": []}, {"num": 4, "title": "But I am willing to learn.", "desc": ["（但我很愿意学习。）"], "formulas": [], "examples": []}, {"num": 5, "title": "Why did you quit your last job?", "desc": ["（你为什么辞去上一个工作？）", "注意宾语 job，resign 则须先置 from 再接宾语 job。此外，quit 亦可表示“戒除、放弃”之意，此时可等于 give up。", "= Carlos will never resign from his job.", "（卡洛士绝不会辞去他的工作。）", "= My doctor told me to give up smoking.", "（我的医生叫我要戒烟。）"], "formulas": [], "examples": []}, {"num": 6, "title": "I think I'll have a better future with your company.", "desc": ["（我认为在贵公司我会比较有前途。）", "future 是名词，表示“未来/将来”，有下列常见的用法：", "carve out a bright future 开创光明的前途"], "formulas": [], "examples": []}, {"num": 1, "title": "Will I have to work overtime?", "desc": ["（我必须要加班吗？）", "work overtime 加班"], "formulas": [], "examples": []}, {"num": 2, "title": "sometimes ['sʌmˌtaɪmz] 副 有时候", "desc": ["= on occasion [ə'keʒən]", "= occasionally [ə'keʒənəlɪ]", "= every now and then", "= He visits me on occasion.", "= He visits me occasionally.", "= He visits me every now and then.", "（他有时候会来看我。）"], "formulas": [], "examples": []}, {"num": 3, "title": "After a year, you'll get an annual leave of seven days.", "desc": ["（满一年后，你每年就会有7天的假期。）", "此处的 leave 是名词，表示“休假、假期”的意思。", "ask for leave 请假", "be on leave 休假中", "be on holiday 度假中", "= be on vacation [ve'keʃən]", "be on leave 指一般的休假而言，时间较短约一天或两天；be on holiday/vacation 则指时间较长的度假，有时可达一个月之久。", "= They are on vacation in Hawaii.", "（他们正在夏威夷度假。）"], "formulas": [], "examples": []}, {"num": 4, "title": "And is there a year-end bonus?", "desc": ["（是否有年终奖金呢？）", "year-end bonus 年终奖金"], "formulas": [], "examples": []}, {"num": 5, "title": "That depends.", "desc": ["= It depends.", "（那要视情况而定。）"], "formulas": [], "examples": []}, {"num": 6, "title": "If you work hard and the company makes money, you'll get one.", "desc": ["（如果你工作努力而且公司赚钱的话就会有。）", "表示“赚钱”的动词除了 make 以外，还可以用 earn [ɝn]。", "make money 赚钱", "= earn money", "make a fortune 赚大钱", "= earn a fortune", "= make/earn a lot of money", "make a living by... 靠...谋生，靠...维生", "= earn a living by...", "= Eric earned a fortune in the stock market.", "= Eric made/earned a lot of money in the stock market.", "（艾力克在股票市场赚了一大笔钱。）", "= He earns a living by driving a taxi.", "（他靠开出租车维生。）"], "formulas": [], "examples": []}, {"num": 7, "title": "That sounds fair.", "desc": ["（听起来很合理。）"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Why do you want to [join our company? / wear long hair?]", "zh": "为何你想加入我们公司？ / 为何你想留长发呢？", "pairs": [{"en": "Why do you want to [join our company? / wear long hair?]", "zh": "为何你想加入我们公司？ / 为何你想留长发呢？"}]}, {"num": 2, "en": "[But I am willing to learn. / Helen is unwilling to work overtime.]", "zh": "但我很愿意学习。 / 海伦不愿意加班。", "pairs": [{"en": "[But I am willing to learn. / Helen is unwilling to work overtime.]", "zh": "但我很愿意学习。 / 海伦不愿意加班。"}]}, {"num": 3, "en": "The doctor told my father to [quit / give up] drinking.", "zh": "医生叫我爸爸要戒酒。", "pairs": [{"en": "The doctor told my father to [quit / give up] drinking.", "zh": "医生叫我爸爸要戒酒。"}]}, {"num": 4, "en": "[That / It] depends.", "zh": "那要视情况而定。", "pairs": [{"en": "[That / It] depends.", "zh": "那要视情况而定。"}]}, {"num": 5, "en": "Carlos [makes / earns] a living by [teaching. / writing novels.]", "zh": "卡洛士靠教书/写小说维生。", "pairs": [{"en": "Carlos [makes / earns] a living by [teaching. / writing novels.]", "zh": "卡洛士靠教书/写小说维生。"}]}, {"num": 6, "en": "[That sounds fair. / You look terrible. / The steak tastes good. / The milk smells sour. / I'm feeling better today.]", "zh": "听起来很合理。 / 你看起来糟透了。 / 这牛排吃起来很棒。 / 这牛奶闻起来酸酸的。 / 我今天觉得好多了。", "pairs": [{"en": "[That sounds fair. / You look terrible. / The steak tastes good. / The milk smells sour. / I'm feeling better today.]", "zh": "听起来很合理。 / 你看起来糟透了。 / 这牛排吃起来很棒。 / 这牛奶闻起来酸酸的。 / 我今天觉得好多了。"}]}], "exercises": []}, {"num": 30, "title_en": "Emergency Calls", "title_zh": "紧急电话", "type": "dialogue", "category": "日常高频情境口语", "tip": "紧急电话：美国火警、医疗急救、报警统称 911；开门见山说明地点与险情：'I need an ambulance at [地址] right away.'", "dialogs": [{"label": "💬 会话 A", "turns": [{"speaker": "A", "en": "This is an emergency call! Get an ambulance here right away.", "zh": "这是紧急电话！请马上派一部救护车到这里来。"}, {"speaker": "B", "en": "Where are you calling from?", "zh": "你从哪里打的电话？"}, {"speaker": "A", "en": "I'm at No. 10 Zhong Hua Road.", "zh": "我在中华路10号。"}, {"speaker": "B", "en": "What's the problem?", "zh": "发生了什么事？"}, {"speaker": "A", "en": "A taxi ran into a truck.", "zh": "一辆出租车撞上了一部卡车。"}]}, {"label": "💬 会话 B", "turns": [{"speaker": "A", "en": "Fire! There's a fire. Come quick!", "zh": "失火了！发生火灾了，快点来！"}, {"speaker": "B", "en": "Where's the fire?", "zh": "哪里发生火灾了？"}, {"speaker": "A", "en": "At No. 7 Kaifeng Street.", "zh": "在开封街7号。"}, {"speaker": "B", "en": "What's burning?", "zh": "什么东西着火了？"}, {"speaker": "A", "en": "My restaurant is on fire.", "zh": "我的餐馆烧起来了。"}, {"speaker": "B", "en": "How did it happen?", "zh": "怎么发生的？"}, {"speaker": "A", "en": "A gas tank exploded.", "zh": "瓦斯桶爆炸。"}, {"speaker": "B", "en": "We'll be right there.", "zh": "我们马上到！"}]}], "reading": null, "vocab": [{"num": 1, "word": "emergency", "phonetic": "[ɪˈmɝdʒənsɪ]", "pos": "形", "meaning": "紧急的 &amp; 名 紧急情况"}, {"num": 2, "word": "ambulance", "phonetic": "[ˈæmbjʊləns]", "pos": "名", "meaning": "救护车"}, {"num": 3, "word": "ran", "phonetic": "[ræn]", "pos": "", "meaning": "是动词 run [rʌn]（跑） 的过去式"}, {"num": 4, "word": "truck", "phonetic": "[trʌk]", "pos": "名", "meaning": "卡车，货车"}, {"num": 1, "word": "fire", "phonetic": "[ˈfaɪr]", "pos": "名", "meaning": "火（不可数）；火灾（可数）"}, {"num": 2, "word": "quick", "phonetic": "[kwɪk]", "pos": "副", "meaning": "快速地，迅速地"}, {"num": 3, "word": "burn", "phonetic": "[bɝn]", "pos": "动", "meaning": "燃烧（burning 是 burn 的现在分词）"}, {"num": 4, "word": "happen", "phonetic": "[ˈhæpən]", "pos": "动", "meaning": "发生"}, {"num": 5, "word": "gas tank", "phonetic": "[ˈɡæs tæŋk]", "pos": "名", "meaning": "瓦斯桶；gas [gæs] 名 瓦斯；tank [tæŋk] 名 （水、油、瓦斯等的） 槽"}, {"num": 6, "word": "explode", "phonetic": "[ɪkˈsplod]", "pos": "动", "meaning": "爆炸"}, {"num": 11, "word": "bomb", "phonetic": "[bɑm]", "pos": "名", "meaning": "炸弹"}], "grammar": [{"num": 1, "title": "This is an emergency call!", "desc": ["（这是紧急电话！）", "此处的 emergency 是形容词，表示“紧急的”之意；但 emergency 也可作名词，表示“紧急（情况）”。"], "formulas": [], "examples": []}, {"num": 2, "title": "Get an ambulance here right away.", "desc": ["（请马上派一部救护车来这里。）", "（你应该把外套穿起来。）", "→ Put on your coat.（命令句）", "（把外套穿起来。）", "（你应该要安静。）", "→ Be quiet!（命令句）", "（安静！）", "（你应该不要靠近那只狗。）", "→ Keep away from that dog.（命令句）", "（不要靠近那只狗。）", "= immediately [ɪ'midɪətlɪ] = instantly ['ɪnstəntlɪ]", "= The police came to help me immediately.", "= The police came to help me instantly.", "（警察立刻赶来援助我。）"], "formulas": [], "examples": []}, {"num": 3, "title": "I'm at No. 10 Zhong Hua Road.", "desc": ["（我在中华路10号。）", "通常与数字有关的介词都用 at 表示，如下列各", "但：I live on Zhong Hua Road.", "（我住在中华路上。）", "= at the age of + 数字", "= He got married at the age of 27.", "（他在27岁时结婚。）"], "formulas": [], "examples": []}, {"num": 4, "title": "What's the problem?", "desc": ["= What's the matter?", "= What's wrong?", "（发生了什么事？）"], "formulas": [], "examples": []}, {"num": 5, "title": "A taxi ran into a truck.", "desc": ["= A taxi hit a truck.", "（一辆出租车撞上了一部卡车。）", "run into... 撞到...", "= hit [hɪt] 动 碰撞（过去式亦为 hit）", "= The car hit the tree at a high speed.", "（那辆车以高速撞上那棵树。）", "= I bumped into an old friend on my way here.", "（在我来这里的途中，我和一位老朋友不期而遇。）"], "formulas": [], "examples": []}, {"num": 1, "title": "Fire! There's a fire!", "desc": ["（失火了！发生火灾了。）", "be on fire 着火；燃烧中", "= Someone set the building on fire.", "（有人放火烧了那栋楼。）"], "formulas": [], "examples": []}, {"num": 2, "title": "Come quick!", "desc": ["= Come quickly!", "（快点来！）", "quick 原为形容词，表示“快/迅速的”，但在口语中，quick 也可作副词用，等于 quickly ['kwɪklɪ]。由于 quick 比 quickly 说起来较简洁，故在口语中常用 quick 代替 quickly。", "（大卫走路很快。）", "Come quick; something terrible has happened.（副词）", "（快来呀，发生可怕的事情啦。）"], "formulas": [], "examples": []}, {"num": 3, "title": "What's burning?", "desc": ["（什么东西在燃烧/着火了？）", "此处的 burning 是动词 burn （燃烧） 的现在分词。"], "formulas": [], "examples": []}, {"num": 4, "title": "We'll be right there!", "desc": ["= We'll be there right away!", "= We'll be there immediately!", "（我们马上到！）", "此处的right 为副词，作强调用法。"], "formulas": [], "examples": []}], "substitution": [{"num": 1, "en": "Get an ambulance here [right away. / immediately. / instantly.]", "zh": "请马上派一部救护车来这里。", "pairs": [{"en": "Get an ambulance here [right away. / immediately. / instantly.]", "zh": "请马上派一部救护车来这里。"}]}, {"num": 2, "en": "He graduated from college [at 15. / at the age of 15.]", "zh": "他15岁时就大学毕业了。", "pairs": [{"en": "He graduated from college [at 15. / at the age of 15.]", "zh": "他15岁时就大学毕业了。"}]}, {"num": 3, "en": "What's [the problem? / the matter? / wrong?]", "zh": "发生了什么事？/怎么了？", "pairs": [{"en": "What's [the problem? / the matter? / wrong?]", "zh": "发生了什么事？/怎么了？"}]}, {"num": 4, "en": "A taxi [ran into / hit] a truck.", "zh": "一辆出租车撞上了一部卡车。", "pairs": [{"en": "A taxi [ran into / hit] a truck.", "zh": "一辆出租车撞上了一部卡车。"}]}, {"num": 5, "en": "I [ran into / bumped into] one of my high school classmates last night.", "zh": "我昨晚和一位高中同学不期而遇。", "pairs": [{"en": "I [ran into / bumped into] one of my high school classmates last night.", "zh": "我昨晚和一位高中同学不期而遇。"}]}, {"num": 6, "en": "Come [quickly! / right away!]", "zh": "快点来！", "pairs": [{"en": "Come [quickly! / right away!]", "zh": "快点来！"}]}, {"num": 7, "en": "The crazy man [set fire to his own house. / set his own house on fire.]", "zh": "那个疯子放火烧了自己的房子。", "pairs": [{"en": "The crazy man [set fire to his own house. / set his own house on fire.]", "zh": "那个疯子放火烧了自己的房子。"}]}], "exercises": []}];